return {
  [1130369089158656] = "Linda, linda! É ainda mais vermelho que minha gravata borboleta!",
  [813713766775808] = "O que há de errado com ele?",
  [813709740108800] = "Estou usando batom novo hoje, parece bom?",
  [813709740069376] = "Parece muito bom.",
  [1139165181885952] = "<P_Heart> (Não, não posso ir para casa!) </>",
  [818107786943488] = "Que peito robusto! Parece que não pode ser aberto diretamente.",
  [818107786594304] = "Pare de dar desculpas. Diga ao Sr. Yate que este ano cultivarei as abóboras maiores e mais doces, ainda mais doces que as uvas dele!",
  [1143563228289536] = "Mas professor, apenas as escrituras da igreja contêm mais registros sobre a Guerra dos Quatro Imperadores. Talvez seja mais provável encontrar a verdade comum nestes documentos...",
  [1143563228824064] = "A identidade de Susie permite que ela evite muitos problemas. Quando não sabemos o que fazer, Susie apenas diz: 'Não sei, afinal, sou apenas um cachorro.'",
  [1143563228820992] = "Senhorita Audrey, você tem um título? Se eu quiser pedir ajuda a você, o que devo cantar?",
  [822439798257664] = "O que você está fazendo?",
  [1130369089158912] = "Droga, vamos terminar se vai ser assim!",
  [611399600443904] = "Espaço reservado",
  [822505833627648] = "Eles são do tipo... que te deixam acordado à noite depois de vê-los.",
  [822505833666560] = "Parabéns.",
  [822505833496576] = "O tempo passado com você é sempre tão prazeroso, deixe-me aproveitar mais um pouco esse momento de paz.",
  [822505833547264] = "Nossa, nossa, você me encontrou!!!",
  [822505833365504] = "Boa tarde, conhecer você é realmente uma alegria inesperada. Você estaria disposto a se juntar a mim para o chá da tarde no caminho?",
  [822505833404416] = "Não, não é que eu impressione, mas sim pelos materiais que vendo.",
  [822505833234432] = "Obrigado a todos por tudo que fizeram por Tingen, que a Deusa os proteja!",
  [822505833273344] = "Desperdiçar água é vergonhoso, seu maldito ladrão!",
  [822505833103360] = "Pobre criança...",
  [822505833142272] = "Estou disposto a trabalhar por 10 centavos por dia, por favor me dê essa oportunidade de trabalho, meu pai está doente e preciso desse dinheiro para comprar remédios...",
  [822505832973824] = "O que você está cozinhando?",
  [822505833011200] = "Desculpe, tenho coisas para fazer, infelizmente tenho que ir primeiro.",
  [822505833076736] = "Amigo, bem-vindo, você está de olho no Dolby?",
  [360778595239424] = "Mas...",
  [360778595430144] = "Abaixe-se!",
  [818107786943232] = "Você estende a mão para sondar, mas o baú do tesouro não se move – está trancado.",
  [818107786944000] = "Se você quiser abrir este baú, terá que jogar comigo.",
  [818107786944256] = "Interessante, você estava tentando me ignorar agora há pouco? Que pena, você já foi “lembrado” por mim.",
  [822505833285632] = "Bater na porta?",
  [822505833285888] = "Ele só bate em uma porta com força a cada vez, e bate em uma porta diferente a cada vez. Da última vez foi o mais próximo das plantas...",
  [818107786803200] = "Espere, {Sr.{Sra.|}}.",
  [1152359321523200] = "Esta é uma... terapia muito especial. Parece eficaz, requer apenas um pouco de coragem.",
  [1143563228833024] = "Cuidado com os espectadores...",
  [1143563228832512] = "O espectador Caminho Beyonders pode não apenas realizar psicoterapia, mas também usar o controle mental para levar Beyonders ao colapso.",
  [1143563228832256] = "Isto não é Invisibilidade no sentido tradicional, mas sim “Invisibilidade Psicológica” – quando a cognição é guiada pela sugestão, a realidade também escapa do campo de visão.",
  [1143563228832000] = "O que? Senhorita Susie está usando Invisibilidade?",
  [1143563228831744] = "Por exemplo, você não pode ver Susie agora, mas ela realmente está deitada a seus pés, tirando uma soneca.",
  [1143563228831488] = "O nome Sequência \"Espectador\" pode fazer as pessoas pensarem erroneamente que este é um Caminho bom apenas para observação e suporte. Mas, na realidade, é também uma forma de disfarce – um disfarce que faz com que as pessoas o subestimem ainda mais.",
  [1143563228830976] = "Senhorita Audrey, a sua identidade no mundo real é a de um psiquiatra?",
  [1143563228830720] = "Sim, as bicicletas disponíveis para alugar na rua foram uma ideia que apresentei anteriormente.",
  [1143563228830464] = "Na verdade, você é acionista da empresa de bicicletas!",
  [822505833587456] = "Haha, o que você está dizendo? Claro, sou um verdadeiro candidato a prefeito!",
  [1143563228829184] = "Senhorita Audrey, além da propriedade da família, você investe?",
  [1143563228828928] = "Não posso lhe dar uma quantia em dinheiro diretamente todas as vezes, mas posso lhe ensinar como investir. O Imperador Roselle disse uma vez: 'É melhor ensinar um homem a pescar do que dar-lhe um peixe!'",
  [1143563228828672] = "Em todo o caso! Se você tiver pouco dinheiro no futuro, pode vir até mim.",
  [1143563228827648] = "Senhorita Audrey, obrigado pelo dinheiro que me deu antes.",
  [822505833009664] = "\"Eles me chamam de poeta da flauta\"",
  [822505833284096] = "O protagonista da história é um homem rico chamado Dawn, e ela está sendo publicada em série em jornais de toda Loen.",
  [1143563228823040] = "Senhorita Audrey, por que Susie consegue falar? Ela é... uma criatura mágica?",
  [1143563228822784] = "Entendido. Obrigado; Aprendi mais alguns Beyonder conhecimentos.",
  [822505833283840] = "Esse é o meu favorito! No entanto, Miss Fors escreveu novos trabalhos recentemente.",
  [1143563228822272] = "No Mundo Extraordinário, cantar um nome honorífico desconhecido provavelmente evocará perigos desconhecidos. Exceto pelos nomes honoríficos de Deuses verdadeiros e seus companheiros no Clube do Tarô , você não deve cantar outros nomes honoríficos.",
  [822505833009408] = "\"Meus dedos dançam uma valsa na válvula\"",
  [822505833587200] = "Você é realmente um candidato a prefeito?",
  [1143563228292608] = "Haha, adoraria conhecer esse senhor se tiver oportunidade!",
  [1143563228292352] = "Era um instrutor chamado Azik. Estávamos muito próximos. Já faz muito tempo desde a última vez que nos falamos; Eu me pergunto como esse sujeito está.",
  [1143563228292096] = "Você chegou atrasado; isso foi há vários anos.",
  [1143563228291840] = "Oh? Houve um adversário que correspondesse ao nível do Professor?",
  [1143563228291584] = "Há muito tempo atrás, havia um sujeito que sempre discutia comigo até ficar com o rosto vermelho... Essa é realmente uma lembrança distante.",
  [1143563228291328] = "O professor Cohen é muito rigoroso academicamente e fico muito feliz em discutir minhas ideias com ele.",
  [1143563228291072] = "Debate? Haha, é apenas uma troca de pesquisas entre meus alunos e eu; não se qualifica como um debate.",
  [1143563228290816] = "Olá. Eu estava de passagem e ouvi o seu debate; parecia muito interessante.",
  [1143563228290560] = "Olá, jovem. Já faz um tempo que vejo você aqui; você gostaria de participar da discussão?",
  [1143563228290304] = "<P_Heart> (O que eles estão discutindo?) </>",
  [822505833284864] = "Você também recebeu essa carta? Droga, eu deveria ter queimado no momento em que vi!",
  [822505833588224] = "Faz três dias que não como... sem emprego, vou morrer de fome...",
  [822505833010432] = "Sim, estou pensando em como acabar com isso. Talvez você possa me fornecer alguma inspiração – se estiver disposto.",
  [1139165181887744] = "<P_Heart> (Se eu fosse um Beyonder também, não entraria em pânico...) </>",
  [822505833077760] = "Custa apenas 5 soli por dia... não, 3 soli, levar para 'aquelas' tabernas para se inscrever, você pode ganhar dinheiro.",
  [822505833112832] = "Por que não dar uma olhada nos comentários do jornal sobre isso?",
  [822505833507072] = "Esse garoto bobo não tem guarda nenhuma. Vamos ser rápidos, pegá-lo e levar todo o dinheiro para ele...",
  [822505833508608] = "Ele é um idiota que confundiu sorte com habilidade e nos trouxe uma nova maneira de ganhar dinheiro.",
  [822505832977664] = "Muito misterioso... eles não vão usar isso para algo ruim, vão?",
  [822505833270272] = "Hmm... recomendo os lilases e os girassóis; eles são todos recém-colhidos nos subúrbios. Há também begônias, ipomeias...",
  [822505833143552] = "Se você não puder pagar, afaste-se; há muitas pessoas competindo por esta vaga.",
  [822505833718528] = "Mas vendo o quanto ela leva a dança a sério, não sei dizer se ela quer estrear ou sair em missão.",
  [822505833718272] = "Yousner é um recém-chegado muito competitivo.",
  [822505833718016] = "Bem, essa é a versão embelezada. Na verdade, eles disseram: 'Simplesmente desajeitado.' Então comecei a estudar na Escola de Artes; dançar deve ser um ótimo treinamento de coordenação!",
  [822505833717760] = "O idoso comentou que minha coordenação corporal não é suficiente.",
  [822505833717504] = "Como estudante do Golden Autumn Lake que veio para a Hoey University, sinto-me muito orgulhoso.",
  [822505833717248] = "As crianças adoravam jogar frutas nos cestos na época da colheita, o que gerava uma série de regras derivadas do seu trabalho.",
  [822505833716992] = "Você provavelmente não sabe que o esporte de arremesso que atualmente varre Loen se originou de um jogo infantil no Golden Autumn Lake.",
  [822505833716736] = "O que eles sabem? Desde que comecei a aprender dança na Escola de Artes, não tive tempo para beber!",
  [822505833716480] = "Todos esses idiotas como Llosa pensam que estou bêbado e causando uma cena aqui. Ninguém acredita que realmente parei de beber.",
  [822505833716224] = "Venha para a Escola de Arte apoiar minha atuação e me ajudar a recuperar tudo que é meu!",
  [822505833715968] = "Eu era o dançarino principal da organização de quadrilha Saint Selena, mas um período agitado de exames finais me fez perder esta posição...",
  [822505833715712] = "Se você estiver disposto a comprar meio quilo de carne, direi que você pode aprender uma dança tão boa apenas frequentando a Escola de Artes.",
  [822505833715456] = "Gentil {{Sr.|Sra.}}, se você gosta da minha dança, por favor vá até a barraca de carne na frente e apoie os negócios da minha irmã Mary Jane.",
  [822505833715200] = "Admito que eles são mais populares que nós nas apresentações da Escola de Arte, mas com certeza somos melhores na competição!",
  [822505833714944] = "Heinz e eu estamos treinando para a competição de amanhã; organizamos uma partida amistosa com a trupe de arte do departamento vizinho.",
  [822505833714688] = "Usar a música tocada pela orquestra ao lado como acompanhamento é o ideal. Hmm, usar você como dançarina reserva também não parece ruim. Que tal, interessado?",
  [822505833714432] = "Como você pode ver, estou criando minha nova dança para a Escola de Artes.",
  [822505833713152] = "Bomba de caramelo! Bomba de caramelo! Delicioso e acessível, uma garrafa vale duas!",
  [822505833712896] = "Ei! Sr. Shermin não está mais conseguindo! Está esgotado! Diga-me, quando ele voltará a desenvolver novas bebidas? Meus clientes mal podem esperar!",
  [822505833712640] = "Você tem \"Bomba de Caramelo\"?",
  [822505833712384] = "{{Sr.|Sra.}}! É você! Que bebida você gostaria hoje?",
  [822505833712128] = "Lembre-se, enquanto você acreditar na Deusa, nada aqui poderá prejudicá-lo.",
  [822505833711872] = "E à noite, toda a catedral cai na tranquilidade sob a proteção da Deusa.",
  [822505833711616] = "Durante o dia, a luz do sol manchada pelas janelas altas de ambos os lados do corredor enche de paz toda a catedral.",
  [822505833711360] = "Todos os crentes podem vir aqui em busca da orientação da Deusa.",
  [822505833711104] = "A Catedral de Santa Selena é a sede da Igreja da Deusa da Noite Eterna em Tingen.",
  [822505833710848] = "Um desejo mágico obriga você a querer experimentar desesperadamente. “Vá pegá-lo e experimente”, diz ele, com a linguagem do diabo fazendo cócegas em seu coração.",
  [822505833710592] = "Um banheiro **estranho**. Seu proprietário anterior claramente conduzia algum tipo de ritual aqui. Os resultados do ritual permanecem lá dentro, emitindo um odor **estranho**, e se recusam a ser reconhecidos pela sociedade civilizada.",
  [822505833710336] = "O Fate Café está aberto para negócios. Eu me pergunto o que Rebecca preparou hoje?",
  [822505833710080] = "Que a Deusa da Meia Noite guarde você.",
  [822505833709824] = "Esse cara é inteligente e feroz; pode sentir o cheiro de qualquer pessoa que esteja na lista negra do bar, com certeza.",
  [822505833709568] = "Diz-se que trabalhava na delegacia; Não sei como acabou sendo adotado pelo Evil Dragon Bar.",
  [822505833709312] = "Mocha é realmente um cachorro difícil de enganar.",
  [822505833709056] = "<P_Heart> (Cheirar cheirar) </> Uau.",
  [822505833708800] = "...Parece que a orientação do destino já desceu. Hoje, ainda é adequado você entrar no clube e encontrar um verdadeiro adivinhação mestre para realizar um adivinhação.",
  [822505833708544] = "Por favor, compre uma carta, vamos observar o destino – opa! Desculpe, não segurei as cartas com firmeza, todas derramaram.",
  [822505833708288] = "Como Domador de Feras, não posso domar a fera gigante que é o destino. Mas, como entusiasta do Tarot, posso interpretá-lo.",
  [822505833708032] = "Eu sou muito preciso! Embora eu seja um Domador de Feras, não sou pior que os adivinhos do clube.",
  [822505833707776] = "Que a beleza e a fragrância favoreçam você.",
  [822505833707520] = "Olá! Eu sou Oliver, o contato para assuntos do clube. Será que você já se juntou a um clube? Algumas coisas são acessíveis apenas aos membros; se ainda não o fez, não é tarde demais para aderir agora.",
  [822505833707264] = "Olá, sou Oliver, o contato responsável pelos assuntos do clube. Parece que você já é membro de um clube – muito bom, você pode usar tudo aqui. Se você precisar ver o que está disponível ou quiser relaxar no clube, pode me encontrar.",
  [822505833706240] = "São mais seis! Eu estive contando!",
  [822505833705984] = "De onde veio esse louco...",
  [822505833705728] = "Pombos! Há pombos no seu chapéu! Deixe-os sair!",
  [822505833705472] = "Você tem coragem! Então vá em frente!",
  [822505833705216] = "Você está aqui? Tem certeza de que deseja lutar contra a sombra de Bonnie?",
  [822505833704704] = "O verdadeiro cenário está nos telhados! Que tal dar uma volta comigo?",
  [822505833704448] = "Qualquer um pode ganhar velocidade, mas a verdadeira dificuldade é o controle. Deixe-me ver seu limite?",
  [822505833703424] = "Estou traçando os ecos passados ​​de um “Professor”. Seu movimento do destino se despedaçou em três fragmentos, perdidos por Tingen.",
  [822505833702656] = "Estou traçando os ecos passados ​​de um 'Guardião'. Seu movimento do destino se despedaçou em três fragmentos, perdidos por Tingen.",
  [822505833702400] = "A apreciação de moda avançada está aberta apenas para aqueles que passaram na avaliação intermediária de membro de moda. Participe primeiro dos <P_Yellow> dois </> desafios intermediários de apreciação de moda de dificuldade normal em Tingen! Depois de se tornar um membro sênior da Fashion Association, volte e discuta ideias de estilo comigo!",
  [822505833702144] = "A apreciação da moda geralmente começa com desafios básicos. Depois de obter o reconhecimento de <P_Yellow> cinco </> membros juniores de moda em Tingen e se tornar um membro intermediário de moda, volte e compartilhe suas idéias de estilo comigo.",
  [822505833701888] = "Sua roupa é mais impressionante que essa neve branca eterna. Vamos, deixe-me ver como você interpreta o modo de apreciação pertencente ao reino da neve.",
  [822505833701632] = "O brilho das joias será obscurecido pela neve voadora, mas o traje apropriado nunca desaparecerá. Vamos! Deixe-me ver sua forma de apreciação.",
  [822505833701376] = "A moda aqui nunca busca ostentação, mas sim manter a calma em pleno inverno. Já que você veio para este gelo e neve, por que não me deixa ver sua forma de apreciação?",
  [822505833701120] = "A verdadeira moda é a capacidade de mostrar o temperamento entre a fragrância das flores e a brisa; já que você já está no mundo das flores, porque não aceitar este desafio de apreciação pertencente ao mar de flores.",
  [822505833700864] = "A moda flui com a época de floração e muda com o humor; já que você veio para esse mar de flores, por que não deixar uma cor própria no seu look? Vamos fazer um desafio de apreciação da moda!",
  [822505833700608] = "Alguns são adequados para rosas brancas à luz da manhã, enquanto outros são mais parecidos com íris à noite. Como você completará sua própria apreciação? Vamos fazer um desafio de apreciação da moda!",
  [822505833700352] = "Alguns preferem a intensidade da plena floração, enquanto outros preferem a maciez da queda das pétalas. Que tipo de história sua roupa contará? Vamos fazer uma apreciação da moda!",
  [822505833700096] = "Originalmente, eu não pretendia deixar uma vaga de membro da moda para um estranho... até ver você andando pelo caminho das flores. No entanto, se você quiser receber um convite, primeiro terá que passar no meu teste de apreciação.",
  [822505833699840] = "Algumas roupas não precisam de decorações complicadas; apenas ficar entre as sombras das flores é suficiente para fazer as pessoas pararem. Vamos, deixe-me ver como você reagirá ao olhar deste mar de flores.",
  [822505833699328] = "Alguns preferem tons de pétalas leves e suaves, enquanto outros gostam de combinações requintadas e contidas. Diferentes ocasiões têm naturalmente sua própria linguagem de moda. Vamos fazer um desafio de apreciação da moda!",
  [822505833697792] = "Isso é incrível, você é praticamente um mestre em pistolas!",
  [822505833696768] = "A Associação de Moda prepara-se recentemente para realizar um encontro de intercâmbio limitado aos associados internos. Eu não tinha planejado convidar nenhum recém-chegado até ver sua roupa, o que me fez mudar um pouco de ideia. No entanto, se quiser receber um convite, você deve primeiro passar no meu teste.",
  [822505833696512] = "Alguns preferem tons de pétalas leves e suaves, enquanto outros gostam de combinações requintadas e contidas. Vamos fazer um desafio de apreciação!",
  [822505833696256] = "As pessoas entendem uma pessoa através de suas roupas; diferentes ocasiões e diferentes identidades têm sua própria linguagem de moda. Vamos fazer um desafio de apreciação da moda!",
  [822505833696000] = "Hmm... Posso ver que seu gosto para roupas não é o de uma pessoa comum. Você está interessado em ingressar no nosso intercâmbio da Fashion Association? \nClaro, você precisa concluir meu teste primeiro.",
  [822505833695744] = "Vamos conversar enquanto caminhamos, vou te levar a algum lugar.",
  [822505833695488] = "Você está aqui? Eu sabia que você conseguiria desenterrar aquele pedaço de papel.",
  [822505833695232] = "Moda não é exibir roupas elegantes, mas sim um equilíbrio entre identidade, etiqueta e estética. Já que você está aqui, por que não aceitar um verdadeiro desafio de apreciação da moda?",
  [822505833694976] = "Estou aqui toda semana. Se você vier e sentar um pouco, escreverei outro para você. Só para você.",
  [822505833694720] = "Então onde devo encontrar você no futuro?",
  [822505833694464] = "Minha poesia parece querer apenas nascer aqui sob as luzes. Se eu mudar de lugar, tenho medo de não conseguir escrever.",
  [822505833694208] = "Pagarei o triplo da recompensa se você escrever apenas para mim. Venha comigo esta noite.",
  [822505833693952] = "Você me lisonjeia, senhora. É uma honra escrever algumas palavras para você.",
  [822505833693696] = "Sua poesia não deveria ficar apenas num lugar como este.",
  [822505833693440] = "Boa sorte.",
  [822505833693184] = "Linda moça, só peço que saia comigo!",
  [822505833692928] = "Não estou com falta de dinheiro, posso dar a ela o que ela quiser!",
  [822505833692672] = "Você também pensa assim, certo! Definitivamente terei sucesso desta vez! Seus olhos estavam sorrindo quando ela aceitou meu colar – ela deve estar emocionada.",
  [822505833692416] = "Parece que você é uma pessoa muito carinhosa.",
  [822505833692160] = "Esperando por aquela minha senhora. Dei a ela vinte colares no total; com este hoje, ela deveria finalmente concordar e concordar em fazer uma refeição comigo, certo?",
  [822505833691904] = "Você está esperando por alguém?",
  [822505833691648] = "Prepare-se para iniciar o ritual.",
  [822505833691392] = "Um bandido incomoda um idoso que varre o chão, o clima está um pouco tenso.",
  [822505833691136] = "Isso é ótimo! Obrigado! Minha casa é fácil de encontrar, é a casa mais próxima da beira do lago!",
  [822505833690880] = "Talvez eu possa ajudá-lo a pegar seu chapéu?",
  [822505833690624] = "Espero aqui todos os dias, querendo recebê-lo com a melhor aparência, mas hoje esqueci meu chapéu em casa.",
  [822505833690368] = "Ah, olá! Estou esperando meu marido aqui. Ele saiu da pequena cidade para trabalhar e deve voltar dentro de alguns dias.",
  [822505833690112] = "Senhora, você parece muito perturbada.",
  [822505833689856] = "A cruzada de ferro e sangue nunca termina; a caixa de areia histórica aguarda um novo mestre – entre no jogo, Conquistador.",
  [822505833689600] = "Espero poder dormir bem esta noite...",
  [822505833689344] = "Espero que aquela menina possa ver a performance como ela desejava.",
  [822505833689088] = "Estou ansioso para que você traga uma melodia totalmente nova desta vez. É claro que, em troca, minha recompensa também será entregue a você através da Echo Box.",
  [822505833688832] = "Nos encontramos novamente, amigo. A música aqui também contém ecos do passado.",
  [822505833688576] = "Eles parecem estar prestes a lutar... talvez eu possa aprender algumas técnicas de combate.",
  [822505833688320] = "<P_Yellow> A tempestade é mais violenta que a bebida forte. </>",
  [822505833687808] = "De qual sala você está falando? E que tipo de comoção?",
  [822505833687552] = "A comoção naquela sala... Não vou conseguir dormir de novo esta noite.",
  [822505833687296] = "Olá, gostaria de dar uma olhada.",
  [822505833687040] = "<P_Heart> (Parece bastante interessante, devo dar uma olhada?) </>",
  [822505833686784] = "Dê uma olhada no que quiser, dez soli cada. Eles ficam muito bem como decoração na parede.",
  [822505833686272] = "Olá, {{Sr.|Sra.}}, nos encontramos novamente.",
  [822505833686016] = "<P_Heart> (Parece que ele não responderá novamente, vamos observá-lo primeiro.) </>",
  [822505833685760] = "...Vá embora, deixe-me ficar aqui sozinho.",
  [822505833685504] = "Senhor, agora é muito tarde, você deveria ir para casa descansar.",
  [822505833683968] = "Eu também comprei algumas maçãs para ela, você deveria levá-las com você também.",
  [822505833683712] = "Realmente? Isso é ótimo! Eu lhe devo um favor!",
  [822505833683456] = "Que tal isso, posso tentar! Eu... sou um palhaço estagiário.",
  [822505833683200] = "Aquela garotinha está muito doente e seu maior desejo agora é ver uma apresentação do Palhaço. Suspiro, eu errei uma promessa tão simples.",
  [822505833682944] = "Eu deveria ter ido à clínica fazer uma apresentação para uma menina, mas caí de uma escada e machuquei a mão. Não consigo segurar nada firme agora.",
  [822505833682688] = "Você está aqui... Você finalmente está aqui... A Porta está no céu... Não olhe para trás... Você não pode escapar dela!!!!!",
  [822505833682176] = "<P_Heart> (surpreso) </> Você está aqui para se apresentar para a garotinha do 305? Ela chorou de dor o dia todo; se ela vir um palhaço, com certeza sorrirá!",
  [822505833681920] = "Olá, sou Palhaço contratado para atuar, posso perguntar...",
  [822505833681664] = "<P_Heart> (Suprimindo uma risada) </> Sua perspectiva sobre arte é única.",
  [822505833681408] = "As pinturas são estáticas, as pessoas estão vivas. Você não acha... linhas fluidas têm mais tensão artística?",
  [822505833681152] = "Um pouco. Mas comparado com o que está na tela... prefiro observar... a beleza dinâmica.",
  [822505833680896] = "Você sabe muito sobre arte?",
  [822505833680640] = "Olhe para esta pintura. As pinceladas são ousadas, as cores são intensas... principalmente a curva da cintura, é realmente obra de mestre.",
  [822505833680384] = "<P_Heart> (Tímido) </> Só acho que o vinho que você compra tem um gosto um pouco mais doce.",
  [822505833680128] = "Você é bastante direto.",
  [822505833679872] = "<P_Heart> (pisca) </> Sim. Mas você tem que me pagar uma bebida primeiro, então eu posso legitimamente... ficar e não ir embora.",
  [822505833679616] = "Então você quer que eu vá ver você?",
  [822505833679360] = "Claro que me lembro. Cada vez que você vem, eu me lembro. É que... você não vem me ver com muita frequência.",
  [822505833679104] = "Você se lembra do que eu usei da última vez?",
  [822505833678848] = "Você parece ainda melhor esta noite do que da última vez.",
  [822505833678592] = "<P_Heart> (Suavemente) </> Muito bem, senhorita Hedy.",
  [822505833678336] = "...Só por esta noite, não me chame de 'Senhora'. Você pode fazer isso?",
  [822505833678080] = "Então, esta noite, você será aquele que será devidamente observado.",
  [822505833677824] = "Honra? Você diz isso toda vez. Porém... pelo menos você me olha nos olhos quando fala. O que está em casa não me olha direito há três anos.",
  [822505833677568] = "É uma honra que a senhorita Hedy possa vir.",
  [822505833677312] = "Vindo aqui uma vez por mês, quase me tornei um cliente regular seu.",
  [822505833677056] = "Juro que nunca mais aceitarei os chamados “serviços especiais”. Isso me deixou com tanta raiva que até desenvolvi rugas!",
  [822505833676800] = "Que tipo de “serviço especial” é esse? Eu estava vestida tão escassamente, usando salto alto, fazendo fila ao vento...",
  [822505833676544] = "Só... é isso?",
  [822505833676288] = "Oh! Deusa! Você nunca vai adivinhar, o 'serviço especial' estava na fila na entrada do teatro para comprar ingressos para a nova peça!",
  [822505833676032] = "A que se refere “serviço especial”?",
  [822505833675776] = "Pretendo ir para o segundo andar e sentar um pouco. A senhora que conheci da última vez é bastante interessante.",
  [822505833675520] = "Então você pretende...",
  [822505833675264] = "Embora existam belas paisagens lá fora, o cenário aqui é verdadeiramente único.",
  [822505833675008] = "Estou na natureza há muito tempo, só estou procurando um lugar confortável para sentar um pouco.",
  [822505833674752] = "Você está bebendo sozinho?",
  [822505833674496] = "Depois de trabalhar aqui por muito tempo, basta um olhar para saber quem está aqui para se divertir e quem está aqui para encrencar.",
  [822505833674240] = "Esse é o meu trabalho. Se alguém causa problemas, eu o arrasto; se alguém fica bêbado, fico de olho; se alguém quiser ir para o segundo andar... tenho que confirmar se pode pagar o preço.",
  [822505833673984] = "Você tem que observar tantas pessoas normalmente?",
  [822505833673728] = "Sim. Vem toda semana, fica bêbado toda semana. Na semana passada ele quase quebrou o copo no piano.",
  [822505833673472] = "Você ficou observando aquele bêbado ali o tempo todo?",
  [822505833673216] = "Muitos convidados que vêm aqui são assim; eles são claramente muito pobres e miseráveis, mas insistem em agir de forma nobre.",
  [822505833672960] = "Ele apenas observa e não se aproxima de mim. Acho que ele está falido e tentando esconder isso.",
  [822505833672704] = "Bem, há alguém no segundo andar vestido de detetive. Ele esteve aqui várias vezes esta semana e sempre me encara.",
  [822505833672448] = "Você acabou de mencionar o segundo andar...",
  [822505833672192] = "Eu sou o mestre em servir bebidas aqui! O chefe sempre me elogia por fazer os clientes beberem um pouco mais, mas com ele não sinto nenhuma sensação de realização.",
  [822505833671936] = "Aquele ao meu lado? Cada vez que eles vêm, ficam bêbados com menos de três copos.",
  [822505833671680] = "Olá, parece que esta pessoa é sua convidada?",
  [822505833671424] = "Ele tem convidado a mesma senhora para sair a semana toda. Ouvi dizer que ela também tem bolsos bem fundos. Suspiro, é muito bom ser rico.",
  [822505833671168] = "Então, há algum resultado da sua observação?",
  [822505833670912] = "Aquele de chapéu lá embaixo. O cliente me pediu para observar quem ele encontra aqui.",
  [822505833670400] = "{{Jovem, você tem uma língua doce. Mas falar é barato. Quando você se cansar de olhar para eles, que tal me pagar uma bebida? Você tem uma língua doce. É uma pena que as luzes aqui nunca esperem por ninguém. }}",
  [822505833670144] = "Acho que sua maquiagem e tez não são diferentes das deles.",
  [822505833669888] = "Antigamente, eu também estava sob as luzes da pista de dança. Só que agora... aquela luz não me alcança mais.",
  [822505833669632] = "O que há de tão bom no primeiro andar? A maioria dos convidados apenas olha para o palco e ninguém me convida para um drink lá embaixo.",
  [822505833669376] = "Por que não descer para assistir?",
  [822505833669120] = "Assistindo a uma dança.",
  [822505833668864] = "Por que você está aqui?",
  [822505833668608] = "<P_Heart> (Embora o efeito tenha sido alcançado, por que parece diferente do que eu esperava?) </>",
  [822505833668352] = "<P_Heart> (Sincero) </> Quer se inscrever em uma aula de canto? Conheço um professor que ensina muito bem.",
  [822505833668096] = "Contanto que o efeito tenha sido alcançado.",
  [822505833667840] = "Quase fiquei surpreso com suas notas altas quando corri para a porta.",
  [822505833667328] = "(Hesita) Embora fosse muito imponente, era realmente terrível de ouvir.",
  [822505833667072] = "Embora o quê?",
  [822505833147392] = "Como isso pôde acontecer! Em alguns dias, será a festa de aniversário do nosso reino—",
  [822505833666304] = "Ela, ela aceitou! Ela disse que também está me notando há muito tempo!",
  [822505833666048] = "<P_Heart> (Ele precisa de um pouco de coragem. Uma canção de Bardo será útil.) </>",
  [822505833665792] = "Com medo que ela recuse. Com medo de dizer a coisa errada. Com medo que ela ria de mim. Com medo... com medo de tudo.",
  [822505833665536] = "Você está com medo?",
  [822505833665280] = "Eu não me atrevo. Estou sentado aqui há duas horas, minhas pernas estão parecendo gelatina.",
  [822505833665024] = "Então por que você não entra?",
  [822505833664768] = "Sim, estou pensando... em dar este buquê para o <P_Yellow> caixa do café do outro lado da rua </> .",
  [822505833664512] = "Este buquê é seu?",
  [822505833664256] = "<P_Heart> (Assustado) </> Não, nada. Só estou pensando em uma coisa...",
  [822505833664000] = "O que você tem? Você não está se sentindo bem?",
  [822505833663744] = "Deixe-me considerar isso...",
  [822505833663488] = "Faz muito tempo que estou varrendo por aqui! Estou sempre sozinho.",
  [822505833663232] = "Mas você está sozinho?",
  [822505833662976] = "Senhora, não tenho nenhum problema com isso!",
  [822505833662720] = "É tão tarde, você está varrendo chaminés?",
  [809242973968640] = "Oh, eu realmente não posso fazer nada com você!",
  [809242974011648] = "Ela definitivamente irá.",
  [822505833662464] = "Senhora, precisa de limpar a sua chaminé? Apenas dois soli.",
  [822505833662208] = "Então não serei educado.",
  [822505833661952] = "Na sessão da próxima semana, os assentos estão muito bons.",
  [822505833661696] = "Realmente? Há muito tempo que estou ansioso por essa peça.",
  [822505833661440] = "Claro, já pedi para alguém comprar os ingressos, dois lugares juntos.",
  [822505833661184] = "Por que, você tem uma maneira de conseguir ingressos?",
  [822505833660928] = "Deusa, rezo para que você o deixe receber o castigo que merece!",
  [822505833660672] = "Oh! Não...",
  [822505833660416] = "Shh! Fale baixo, você quer que ele ouça você?",
  [822505833660160] = "Ele é muito difícil de lidar. Ele até me pediu para...",
  [822505833659904] = "Eu realmente simpatizo com as irmãs que ele escolhe.",
  [822505833659648] = "Isto... não é fácil de dizer em voz alta.",
  [822505833659392] = "O que... exatamente aconteceu com ele?",
  [822505833659136] = "Prefiro ir ao banheiro do que ir até ele.",
  [822505833658880] = "Chega, Angela, não diga mais nada. Não quero ter esse tipo de experiência nunca mais na minha vida!",
  [822505833658624] = "Apenas aquela pessoa com cara de aventureiro ali. Quem ele escolher...",
  [822505833658368] = "De quem você está falando?",
  [822505833658112] = "Eu... me arrependo de não ter ouvido você, encontrei ele pela primeira vez...",
  [822505833657856] = "Preciso encontrar uma desculpa para pedir licença. O que você acha da desculpa da ‘dor de cabeça’?",
  [822505833657600] = "Esse explorador está aqui novamente. Oh! Deusa Proteção, espero que ele não me escolha hoje!",
  [822505833657344] = "Você pode passear mais pelo primeiro andar. Depois de saber o que quer, você entenderá naturalmente.",
  [822505833657088] = "Cabine privada?",
  [822505833656832] = "Antes, havia um cara que não suportava o ronco da esposa, então ele passou uma noite inteira em uma cabine particular no segundo andar para acalmar seus nervos torturados.",
  [822505833656576] = "O segundo andar é mais silencioso e privado. Pessoas discutindo negócios em particular, aqueles que querem ficar sozinhos por um tempo, e... <P_Heart> (Abaixa a voz) </> algumas coisas que não são convenientes para falar em público, todos vão para o segundo andar.",
  [822505833656320] = "O que há no segundo andar?",
  [822505833656064] = "Isso depende de como você conversa. Algumas pessoas apenas conversam; algumas pessoas, quando estão de bom humor, conseguem fechar um negócio; <P_Heart> (Voz baixa) </> e algumas pessoas, enquanto conversam, acabam indo para o segundo andar.",
  [822505833655808] = "Apenas... apenas conversando?",
  [822505833655552] = "O primeiro andar é onde se entrelaçam passos de dança e taças de vinho. Se você quiser encontrar as mulheres para tomar uma bebida, fique à vontade para se sentar. Não importa sobre o que você pretende falar, eles sabem como fazer as pessoas se abrirem.",
  [822505833655296] = "<P_Heart> (Olha você de cima a baixo) </> Todo mundo que vem pela primeira vez pergunta isso. Deixe-me dar uma breve explicação.",
  [822505833655040] = "Estou aqui pela primeira vez, há... algo para ver aqui?",
  [822505833654784] = "Por favor, fique à vontade para dar uma olhada. Se a atuação das meninas não é do seu agrado... também há quem se especialize em conversar com as mulheres; eles têm línguas muito doces.",
  [822505833648384] = "Boa noite, senhora. Gostaria de começar com uma taça de vinho ou gostaria de conhecer o local primeiro?",
  [822505833648128] = "Claro, ver para crer. Se você gostou do que viu, vá conversar um pouco, não precisa se conter. Não há muitas regras aqui.",
  [822505833647872] = "Algumas pessoas gastam dinheiro para se divertir, outras gastam dinheiro... para encontrar esse \"irmão\".",
  [822505833647616] = "Aqueles que estiveram ocupados o dia todo e estão com problemas vêm aqui para passar a noite, ouvem-na chamá-los de irmão algumas vezes e saem com sorrisos no rosto.",
  [822505833647360] = "Só isso. Aqueles que ficaram correndo o dia todo, cheios de irritação, vêm aqui passar a noite, ouvem ela chamá-los de “irmão” algumas vezes, e vão embora com sorrisos no rosto.",
  [822505833647104] = "Só... isso?",
  [822505833646848] = "Ela só faz uma coisa: inclina a cabeça, olha para você e pergunta: “Irmão, você está cansado hoje?”",
  [822505833646592] = "Senhorita Yellow Crystal Daisy, a mais nova daqui. Ela não toca piano, não dança e não fala sobre assuntos mundiais.",
  [822505833646336] = "Alguns convidados que pensam que têm conhecimento adoram escolhê-la - eles sempre se sentem um pouco mais espertos depois de conversar com ela do que quando chegaram.",
  [822505833646080] = "Você fala de história, ela consegue acompanhar; fale de política, ela consegue acompanhar; falar de negócios, de arte, que teatro tem peça nova... ela consegue acompanhar tudo. E ela faz isso com elegância.",
  [822505833645568] = "Ônix Preto Senhorita Cerve. Se você for até ela, não precisa levar vinho, basta um tema decente.",
  [822505833645312] = "Alguns convidados sentam-se com a intenção de conversar enquanto tomam um drink, mas quando se levantam querem deixar todo o seu coração com ela.",
  [822505833645056] = "Apenas essa frase, e tantas pessoas estão dispostas a ficar sentadas ao lado dela a noite toda, contando tudo o que nunca contaram a ninguém em suas vidas.",
  [822505833644800] = "Jogar bem é uma coisa, mas a Srta. Lillian é diferente: quando ela fala com você, ela ouve tudo o que você diz e depois pergunta: \"E depois?\"",
  [822505833644544] = "É porque ela joga bem?",
  [822505833644288] = "Sapphire Lillian, aquela que toca piano. No momento em que ela se senta ao piano e as pontas dos dedos caem, o barulho de todo o salão diminui.",
  [822505833644032] = "<P_Heart> (Risos) </> De qualquer forma, ele voltou no terceiro dia.",
  [822505833643776] = "Então, você confirmou no final?",
  [822505833643520] = "Algumas pessoas olham para ela e voltam no dia seguinte dizendo: 'Tenho que confirmar se ela realmente me viu'.",
  [822505833643264] = "Ela nunca fica apenas no palco. Ela entra na multidão como uma rajada de vento passando por você, e você nem tem tempo de sentir o calor dela... deixando apenas um olhar que faz você se perguntar a noite toda: aquele olhar foi realmente feito para você?",
  [822505833643008] = "Ruby Rosa, sem dúvida a nossa melhor dançarina. Assim que ela sobe no palco, o público fica em silêncio.",
  [822505833642752] = "Temos quatro senhoras, conhecidas como as “Quatro Joias”. Por qual você gostaria de começar?",
  [822505833642496] = "O que significa “as pessoas são ainda mais”?",
  [822505833642240] = "Olhando para você, é a primeira vez que entra na noite de Tingen? Então você encontrou o lugar certo. Esta é a única esquina desta cidade onde o tempo passa mais devagar. O vinho é de primeira qualidade e as pessoas... mais ainda.",
  [822505833641984] = "Uma escolha sábia. Vou preparar uma bebida exclusiva para você. Não há necessidade de pressa para se sentar - caminhe, assista ao espetáculo desta noite e, quando você voltar, o vinho terá respirado em seu melhor estado.",
  [822505833641728] = "Boa noite, senhor. Gostaria de começar com uma taça de vinho ou gostaria de conhecer o local primeiro?",
  [822505833641472] = "Se eu for incomodado por outros convidados, você tem que vir me resgatar, irmão!",
  [822505833641216] = "Claro, eu só massageio você, irmão.",
  [822505833640960] = "Você está falando sério?",
  [822505833640704] = "Irmão, você diz que está cansado toda vez que vem, isso faz meu coração doer. De agora em diante, vou massagear você todos os dias.",
  [822505833640448] = "<P_Heart> (Risos) </> Como eu poderia suportar deixar suas mãos cansadas?",
  [822505833640192] = "Então deixe-me massagear você, irmão, você não ficará cansado depois que eu terminar.",
  [822505833639936] = "Estou tão cansado hoje que estou prestes a desmoronar.",
  [822505833639680] = "Leia o suficiente e você se lembrará naturalmente. Quanto ao que não lembrei... que tal um jogo? Você pergunta, eu respondo. Se eu errar, você me penaliza com uma bebida, ou... devo penalizá-lo com uma bebida?",
  [822505833639424] = "Senhorita Cerve, seu volume de leitura é realmente surpreendente.",
  [822505833639168] = "Isso é. Mas o dinheiro pode suavizar qualquer coisa. <P_Heart> (Suspiros) </> O teatro quer um nome que venda ingressos; quem se importa com quem realmente escreveu o roteiro?",
  [822505833638912] = "Isso não é apenas roubar?",
  [822505833638656] = "Ele pagou para comprar os direitos de autoria e promoveu-o como se fosse seu, mas o verdadeiro autor teve sua reputação roubada.",
  [822505833638400] = "Então o que fez o dramaturgo que eles estão promovendo agora?",
  [822505833638144] = "Sim, aquele esqueleto foi retirado de uma obra antiga de um escritor do Intis, apenas mudaram os nomes.",
  [822505833637888] = "Não é de admirar. Quando eu estava assistindo, senti que o terceiro ato não se conectava de forma alguma com o resto, como se tivesse sido forçado.",
  [822505833637632] = "<P_Heart> (Abaixa a voz) </> Ele escreveu os dois primeiros atos. O terceiro ato não foi ele.",
  [822505833637376] = "Então o da semana passada também foi escrito por ele?",
  [822505833637120] = "Presente de um amigo, com assinatura do autor na página de rosto. Ele também escreveu 'Mist Harbor', aquela peça do ano retrasado sobre trabalhadores portuários.",
  [822505833636864] = "Você pelo menos leu o original? Esse livro não é fácil de encontrar.",
  [822505833636608] = "Na obra original, aquela senhora pulou no rio no final, mas o roteiro foi alterado para um final feliz e todos os três segmentos do prenúncio foram excluídos. Sem esses três segmentos, todas as lutas anteriores não se sustentam.",
  [822505833636352] = "Então onde você acha que o script falhou?",
  [822505833636096] = "A escrita era tão fina quanto o gelo em uma taça de vinho – depois que derrete, não sobra mais nada.",
  [822505833635840] = "Senhorita Cerve, o que achou daquela nova peça da semana passada?",
  [822505833635584] = "Claro. Pelo menos por enquanto, sou seu único “artista”.",
  [822505833635328] = "<P_Heart> (Tocado) </> Você é muito mandão.",
  [822505833635072] = "Traga a nova partitura da próxima vez. Estarei esperando para jogar. Mas, não fique acordado até o meio da noite de novo, ok?",
  [822505833634816] = "...Coisas como esta não são raras. Mas a sua música... pelo menos para mim, será sempre a melhor.",
  [822505833634560] = "Há duas semanas, enviei uma música tema para uma nova peça, mas eles acabaram escolhendo uma que não combinava em nada com a peça. Eu nem sei de onde surgiu esse compositor.",
  [822505833634304] = "Heh, de que adianta ser bom? Ninguém faz, ninguém escuta, ninguém... <P_Heart> (Pausa) </> ninguém quer.",
  [822505833634048] = "É porque sua composição é boa.",
  [822505833633792] = "Você tocou esta peça muito bem hoje.",
  [822505833633536] = "Vale a pena! Como poderia não ser? Aquele olhar que ela me deu foi mais caloroso do que o que minha esposa me deu em um ano.",
  [822505833633280] = "Rosa, aquela mulher... ela faz você gastar dinheiro e faz você sentir que vale a pena.",
  [822505833633024] = "Melhorar? Eu realmente tive que fazer horas extras por uma semana quando voltei, caso contrário, como eu teria dinheiro para buscá-la novamente esta noite?",
  [822505833632768] = "Um aumento? Sua mentira é muito melhor que a minha.",
  [822505833632512] = "Pff, isso não é nada. Na semana passada ela piscou para mim enquanto dançava, e minha esposa perguntou: 'Por que você está sorrindo como um idiota?' Eu disse: 'Estava pensando em um aumento'.",
  [822505833632256] = "Quando ela não está fazendo as coisas de propósito? Da última vez que ela passou por mim e tocou minha manga, não tive coragem de lavar aquela camisa por três dias.",
  [822505833632000] = "O vestido da Rosa hoje... foi de propósito, né?",
  [822505833631744] = "<P_Heart> (Piscadelas) </> Estou aqui há tantos anos, que tipo de homem eu não vi? Persuadindo os homens... <P_Heart> (Abaixa a voz) </> você tem que aprender a escolher, aprender a esperar e aprender - a parar no momento certo.",
  [822505833631488] = "Parece que você sabe muito?",
  [822505833631232] = "Sim, alguém que saiba conversar, persuadir você e seja bonito. Escolha um, peça para ele te chamar de “irmã” algumas vezes e garanto que você ficará de bom humor por uma semana.",
  [822505833630976] = "Um modelo masculino?",
  [519041160896256] = "Senhorita, você pode me ouvir? Parece que você está em péssimo estado.",
  [519041160896512] = "Senhor, minha cabeça dói muito e não consigo nem abrir os olhos...",
  [519041160954112] = "Miau?",
  [822505833630720] = "Então você veio ao lugar certo. Mas assistir a uma dança é chato; por que não tentar... fazer com que os cavalheiros aqui se sentem com você?",
  [519041160970496] = "Terceira viagem! Esta caixa de lata está ficando cada vez mais quente! Não vai explodir, vai!",
  [822505833630464] = "Só de passagem, olhando em volta.",
  [519041161081088] = "Para mais estilos, você pode ir até a loja \"Rain Halfway\" na rua para escolhê-los!",
  [519041161101824] = "Miau-woo...",
  [822505833630208] = "<P_Heart> (Levanta uma sobrancelha) </> Ah, que beleza? Está aqui pela emoção ou procurando alguém?",
  [822505833629952] = "<P_Heart> (com um sorriso nos lábios) </> Se você quiser assistir a um baile, é só encontrar um lugar. Se quiser conversar um pouco mais... encha primeiro a taça de vinho.",
  [822505833629440] = "Perto o suficiente... para que você possa sentir o cheiro do perfume no meu cabelo. Isso é perto o suficiente?",
  [519041161238528] = "Irmão... irmão! Eu, estou pedindo direções...",
  [519041161272576] = "EU...",
  [822505833629184] = "Quanto mais perto?",
  [822505833628928] = "<P_Heart> (Risos) </> Brincadeirinha. Se você realmente quer que eu veja você claramente, pode me pagar uma bebida mais tarde. Se eu estiver de bom humor, posso chegar um pouco mais perto.",
  [822505833628416] = "A iluminação é um pouco fraca aqui. Por que você não se aproxima para que eu possa vê-lo claramente?",
  [822505833628160] = "É assim mesmo?",
  [822505833147648] = "Calma, todos se acalmem. Sei que isso é muito repentino, mas precisamos pensar em uma contramedida.",
  [822505833627392] = "O que há de tão especial em seus movimentos de dança?",
  [822505833627136] = "Porque este lugar tem o melhor vinho, os melhores conversadores e... <P_Heart> (Piscadelas) </> meus passos de dança.",
  [822505833626624] = "Com tantos lugares em Tingen, o fato de você ter escolhido vir aqui mostra que você tem bom gosto.",
  [822505833626368] = "Só de passagem, entrei para dar uma olhada.",
  [822505833626112] = "<P_Heart> (Olha você de cima a baixo, com um sorriso malicioso nos lábios) </> Um rosto novo, primeira vez aqui?",
  [822505833625856] = "Devolva se não for comê-lo.",
  [822505833625600] = "Este é o único pedaço pequeno de pão...",
  [822505833625344] = "Tudo bem, é isso por hoje. Se você estiver com falta de um centavo amanhã, você não come!",
  [822505833625088] = "A família não estava em casa hoje, não me deixaram entrar.",
  [822505833624832] = "Seis centavos? Foram oito centavos ontem. Afrouxando?",
  [822505833624576] = "Bebida! Não quero pensar naquela maldita escada esta noite!",
  [822505833624320] = "Cinco soli para pintar uma sala inteira e eles têm que fornecer refeições.",
  [822505833624064] = "Não me atrevo a aceitar empregos no distrito fabril – se você trabalhar lá por muito tempo, seus pulmões se encherão de fiapos de algodão.",
  [822505833623808] = "No negócio de reformas, você está na casa de um cliente hoje e na de outro amanhã.",
  [822505833623552] = "O amarelo acastanhado mais profundo. Heh, o nevoeiro em Tingen já está amarelo o suficiente, e agora tenho que pintar minha casa de amarelo também.",
  [822505833623296] = "Para a lei – ela protege os ricos. Para mim mesmo – eu protejo aqueles que bebem.",
  [822505833623040] = "Heh... hehe... sem essa compensação! Como sua filha poderia ter sido curada!",
  [822505833622784] = "Bebida!",
  [822505833622528] = "...Para esse processo, o dono da fábrica têxtil teve que vir me procurar pessoalmente.",
  [822505833622272] = "Ganhei mais ações judiciais do que pedras na Rua Cruz de Ferro!",
  [822505833622016] = "Eu ganhei, eu ganhei! Haha!",
  [822505833621760] = "Então? O que você quer escrever? Posso te dar um desconto; Só estou querendo ganhar algum dinheiro com vinho.",
  [822505833621504] = "Mais tarde... mais tarde parei de aceitar empregos.",
  [822505833620992] = "Claro! Até ganhei alguns casos e ajudei as pessoas a receber o dinheiro que lhes era devido.",
  [822505833620736] = "Você já foi advogado?",
  [822505833620480] = "Algo como um contrato de arrendamento habitacional custa seis centavos; testamentos e petições têm pelo menos um sol. Você terá que me contar sua situação antes que eu possa julgar.",
  [822505833620224] = "Quanto custa uma peça?",
  [822505833619968] = "Claro! Que queixas você tem? Salários retidos pela fábrica? Proprietário se recusando a devolver seu depósito?",
  [822505833619712] = "Você pode escrever qualquer coisa?",
  [822505833619456] = "{{Sr.|Sra.}}, dê uma olhada nisso? Dividir propriedades, redigir testamentos, escrever petições – posso fazer tudo.",
  [822505833619200] = "Claro, você tem que escrever sobre essas coisas se quiser ser famoso.",
  [822505833618944] = "Parece um grande tópico.",
  [822505833618688] = "Está tudo lá: trabalhadores, fábricas, proprietários de fábricas, vereadores – tudo o que acontece em Tingen.",
  [822505833618432] = "Do que se trata?",
  [822505833618176] = "Não, é um artigo para o jornal.",
  [822505833617920] = "O que você está pensando? Um romance?",
  [822505833617664] = "\"Fumaça preta sobe das chaminés de Tingen; algumas pessoas começam a trabalhar, algumas pessoas começam a negociar\"... Não é muito apropriado.",
  [822505833617408] = "Como a abertura deve ser escrita? ‘Cantos escondidos de Tingen guardam segredos’? Um pouco clichê.",
  [822505833617152] = "...Se isso não for publicado, estou acabado.",
  [822505833616896] = "Se isso for publicado, ficarei rico.",
  [822505833616640] = "Que tal nomear a série como 'Ofertas nos bastidores em Tingen'? Desta vez o tema é um encontro privado entre um vereador e um magnata de uma fábrica.",
  [822505833616384] = "Deixe-me pensar...",
  [822505833616128] = "Apenas aguente firme. Assim que meu novo rascunho for lançado, será um sucesso!",
  [822505833615872] = "O sótão custa apenas um sol de aluguel, seis centavos de pão, pelo menos ainda me sobra meia garrafa de vinho...",
  [822505833615616] = "Pelo menos esse rascunho foi aceito...",
  [822505833615360] = "Ele só me deu dois soli por um relatório que valia pelo menos cinco.",
  [822505833615104] = "Por favor, aceite minha homenagem! Você ganhou isso sozinho!",
  [822505833614592] = "Eu também tenho que trabalhar duro! Não posso causar mais problemas ao meu pai!",
  [822505833614336] = "\"Urso Pardo\" Er é meu pai! Ele não é incrível? Papai tem trabalhado duro para ganhar dinheiro para tratar a doença da minha irmã mais nova...",
  [822505833614080] = "Pai? Seu pai poderia ser...",
  [822505833613824] = "Obrigado pela sua generosidade! Se eu tiver que pagar uma indenização, a briga do meu pai esta noite terá sido em vão...",
  [822505833613568] = "Desculpe. Hoje... estou um pouco cansado.",
  [822505833613056] = "Por que tantas perguntas? Você vai perguntar por que posso abrir uma clínica em um lugar como este a seguir?",
  [822505833612544] = "É meu, mas não abri.",
  [822505833612288] = "Porque alguém tem que estar aqui.",
  [822505833611776] = "Então por que você ainda está aqui?",
  [822505833611520] = "Pessoas que estão realmente doentes não podem entrar aqui. Eles não podem pagar por isso.",
  [822505833611264] = "Pacientes? Hoje só tem ‘clientes’: ‘Doutor, me receita um tônico’, ‘Doutor, meu dedo está sangrando’...",
  [822505833611008] = "Porque há muitos pacientes?",
  [822505833610752] = "De mau humor? Não, só estou um pouco cansado.",
  [822505833610496] = "Aqueles que procuram um médico estão naturalmente necessitados, mas algumas pessoas precisam mais de ajuda.",
  [822505833610240] = "Então você acha que as pessoas que realmente precisam de ajuda não estão na clínica?",
  [822505833609984] = "Se estamos falando sobre ficar realmente doente... heh, não é a vez deles.",
  [822505833609728] = "Quanto maior a pilha de frascos de remédios, maior será a vida útil.",
  [822505833609472] = "Então você tem sorte. As vagas estão lotadas hoje - todas são pessoas que dizem: 'Estou tonto, como esse remédio que você receitou é suficiente?'",
  [822505833609216] = "Vendo um médico? Você marcou uma consulta?",
  [822505833608960] = "A vida vai te ensinar essas regras.",
  [822505833608704] = "Isso não é fácil.",
  [822505833608448] = "Quando você está fora de casa, sua identidade é o que você faz dela. Se eu me vestir como um mendigo, quem compraria meus produtos?",
  [822505833608192] = "Eles não foram roubados ou roubados; Comprei-os com meu primeiro pote de ouro.",
  [822505833607936] = "Essas suas roupas...",
  [822505833607680] = "Claro, minha família e eu moramos dentro disso.",
  [822505833607424] = "...Não pergunte sobre coisas que não lhe dizem respeito.",
  [822505833607168] = "Por que tão barato?",
  [822505833606912] = "Eles vendem por pelo menos 2 soli na loja de souvenirs. Normalmente os vendo por 1 soli e 6 centavos. Se você quiser um agora, que tal 1 soli?",
  [822505833606656] = "Algo que todos em Tingen sabem: uma lembrança da Escultura do Conhecimento.",
  [822505833606400] = "Hmm... estes parecem muito bons. Vou levar alguns ao Central Plaza para vender amanhã.",
  [822505833605376] = "Não se preocupe, a Deusa cuidará de cada um de Seus crentes.",
  [822505833604864] = "Que a Deusa da Meia Noite guarde você.",
  [822505833604608] = "...Eu realmente quero beber uma 'Bomba de Caramelo'!",
  [822505833604096] = "Você quer ir à delegacia para beber?",
  [822505833603840] = "Da última vez, depois de orar ao Senhor do Banheiro, um policial {{Sr.|Sra.}} desceu do céu e nos ajudou a resolver o problema da diarreia. Se orarmos novamente, será que isso poderia ressuscitar a 'Bomba de Caramelo'?",
  [822505833603584] = "Absolutamente não! Ele está ocupado misturando esses agentes de limpeza todos os dias e há muito esqueceu que alguém está esperando amargamente por uma garrafa de bebida!",
  [822505833603328] = "O Sr. Shermin ainda está desenvolvendo diligentemente a nova 'Bomba de Caramelo'?",
  [822505833603072] = "O que você gostaria?",
  [822505833602816] = "Não incomode a criança; Eu cuidarei disso.",
  [822505833602560] = "Caramba! Esses sapatos são os meus favoritos! Seu pirralho, você está realmente pedindo por isso!",
  [822505833602304] = "Desculpe! Este convidado... eu não queria!",
  [822505833602048] = "Esta é uma poção especial. Preciso que você misture na bebida do Urso Pardo antes da partida. Afinal, ele realmente precisa de um descanso.",
  [822505833601792] = "Qual é o seu plano?",
  [822505833601536] = "Apostei no adversário do Urso Pardo e preciso de algumas garantias simples.",
  [822505833601280] = "Não entendo muito bem o que você quer dizer.",
  [822505833601024] = "Sou um jogador generoso, só preciso de um... assistente confiável.",
  [822505833600768] = "Você está pronto para ser o próximo guerreiro?",
  [822505833600512] = "Isso é uma armação! Espere meu advogado vir e lhe causar problemas!",
  [822505833600256] = "<P_Heart> (falando em voz deliberadamente baixa) </> Aquela Camilla, ela é a amante que você mantém secretamente! Os tablóides são todos verdadeiros!",
  [822505833600000] = "A velha que você está amaldiçoando, não seria sua esposa?",
  [822505833599744] = "O que você ouviu? Estou lhe dizendo, não existe tal coisa!",
  [822505833599488] = "Assim que eu for eleito com sucesso, tudo o que prometi ao povo será cumprido!",
  [822505833599232] = "Claro, serei um bom prefeito que se preocupa com o povo.",
  [822505833598976] = "As pessoas, afinal, precisam ter um emprego adequado para poder comer com dignidade.",
  [822505833598720] = "Não existem 'mas'. Em dois anos, você poderá trabalhar e então poderá comer até se fartar todos os dias.",
  [822505833598208] = "O que você está dizendo? Não aprenda maus hábitos; roubar não é uma coisa boa!",
  [822505833597952] = "Sinto tanta fome todos os dias e quero poder me fartar como você...",
  [822505833597696] = "Irmão, você pode me ensinar a roubar?",
  [822505833597440] = "Tudo bem, vou deixar você ir desta vez. Não faça isso de novo; roubar nunca é uma coisa boa.",
  [822505833597184] = "Também não como há dias e estava com tanta fome que não conseguia enxergar direito, por isso fiz isso...",
  [822505833596928] = "Você é uma pessoa generosa, por favor, deixe-me ir desta vez...",
  [822505833596672] = "Shh! Shh! Shh! Não, não, vou colocá-lo de volta agora mesmo...",
  [822505833596416] = "Coloque-o de volta rapidamente, ou chamarei o patrulheiro para prendê-lo agora mesmo...",
  [822505833596160] = "Você está roubando!!!",
  [822505833595904] = "Eu me pergunto quanto custa aquele que ela viu durante o dia? É a primeira vez que compro um item tão luxuoso...",
  [822505833595648] = "Se um colar pode fazê-la se sentir melhor, estou disposto a ser extravagante desta vez.",
  [822505833595392] = "Emily, minha esposa, ela merece uma vida melhor, mas eu simplesmente não posso dar isso a ela...",
  [822505833595136] = "Comporte-se, comprarei para você na próxima vez. Vamos para casa primeiro...",
  [822505833594880] = "Eu só quero um colar meu. O que há de errado nisso!!!",
  [822505833594624] = "Naquela época, para casar com você, eu nem pedia dote, e fui repreendido por tanto tempo por ser um 'brinde'...",
  [822505833594368] = "Estamos casados ​​há tantos anos e nunca te pedi nada...",
  [822505833594112] = "Querido, isso já é metade do aluguel que implorei para você!",
  [822505833593856] = "Mas... o aluguel da sua casa também não é baixo...",
  [822505833593600] = "Meu pai não permite que eu me case com um homem que só consegue alugar uma casa...",
  [822505833593344] = "Provavelmente quando você tiver sua própria casa.",
  [822505833593088] = "Não quero ter que me esconder assim toda vez que estou sozinho com você...",
  [822505833592832] = "Querido, quando poderei ter um status oficial?",
  [822505833592576] = "Nada, nada... você deve ter ouvido mal...",
  [822505833592320] = "Ah, o que você disse? Por que ouvi o nome da minha filha...",
  [822505833592064] = "A localização, os custos dos móveis baratos e, claro, há Charlotte aqui...",
  [822505833591808] = "Isso porque tudo na sua casa está bem!",
  [822505833591296] = "Deitar aqui para descansar um pouco deve ser muito mais confortável do que enrolar em um canto...",
  [822505833591040] = "Ok, depois de comer, você pode me deixar descansar um pouco aqui?",
  [822505833590784] = "...Obrigado por aceitar minha entrevista. A comida na mesa é o pagamento da entrevista.",
  [822505833590528] = "É por isso que me tornei um andarilho, Sr. Repórter.",
  [822505833590272] = "Minha família faliu, meu marido faleceu e meu filho não aguentou o golpe e optou pelo suicídio...",
  [822505833590016] = "O que eu tenho agora? Haha, ainda tenho três cigarros...",
  [822505833589760] = "Desde então, muitas vezes não consegui encontrar trabalho e lentamente me tornei um morador de rua.",
  [822505833589504] = "Fiquei muito tempo internado, perdi meu emprego, perdi meu patrimônio e até perdi minha família...",
  [822505833589248] = "Eu era um trabalhador decente, com esposa e dois filhos adoráveis, até que uma doença infecciosa, há alguns anos atrás...",
  [822505833588992] = "Por que você se tornou um morador de rua?",
  [822505833588736] = "Posso lidar com muitos trabalhos. Eu deveria ter sido um bom trabalhador...",
  [822505833588480] = "O asilo tem longas filas. A boa sorte nem sempre me favorece; na maioria das vezes, não consigo nem uma porção de comida.",
  [1143563228289792] = "Aston, acredito que você entende que a igreja tem sua própria postura. É difícil tirar isso...",
  [822505833587968] = "A eleição está chegando; Espero que você possa dar seu precioso voto em mim!",
  [822505833587712] = "Mesmo como funcionário do governo, há momentos em que é preciso ir às ruas, por isso não é estranho me encontrar.",
  [1143563228829440] = "Meu primeiro investimento bem-sucedido foi em ações de uma empresa de bicicletas. Eu não tinha dinheiro suficiente para comprar as ações na época, mas meu pai me ensinou uma técnica de investimento.",
  [1143563228821248] = "Meu nome honorífico é – O Espírito Santo que tudo vê, o Abençoado do Rei Amarelo e Preto, o viajante dos sonhos e das mentes.",
  [822505833586944] = "Você gostaria de experimentar um desafio tenso e emocionante 'Um em Cem Ovos'?",
  [822505833586176] = "Missão começou",
  [822505833585920] = "Por favor, aceite seu prêmio em dinheiro! Você mesmo mereceu!",
  [822505833585664] = "Incrível! Você realmente fez Abi perder a partida. Eu nunca o vi desmaiar no ringue antes!",
  [822505833585408] = "Muito bom, muito bom. Você tem dois minutos! Então começamos!",
  [822505833585152] = "Olá, senhor. Eu gostaria de tentar desafiar o campeão Abi.",
  [822505833584896] = "<P_Heart> (Se eu quiser treinar minhas habilidades de luta no futuro, talvez eu possa tentar.) </>",
  [822505833584640] = "Ou você gostaria de tentar empurrar aquela montanha de carne do palco para fora do ringue? Não subestime sua própria força!",
  [822505833584384] = "Acredito que você não gostaria de perder esta grande oportunidade de ganhar dinheiro. Campeão Abi contra o próximo azarado, as chances são de um para trinta!",
  [822505833584128] = "Bem-vindo! Bem-vindo! Embora você tenha perdido a última partida do Campeão Abi - ah, o pobre Billy levou um chute nos dentes - a próxima começará em breve!",
  [822505833581824] = "O marido dela chamou a polícia, mas eles ainda não encontraram nenhuma pista. (cospe) Um bando de gente inútil!",
  [822505833581056] = "Não parece diferente dos outros ovos... mas aumenta muito a produção de ovos! Espero que possa ser promovido em breve para que ninguém passe fome...",
  [822505833580800] = "Ouvi dizer que este galo era um dos principais candidatos em brigas de galo antes. Não admira que seja tão produtivo; é realmente uma 'galinha lutadora'!",
  [822505833580544] = "Sr. Frank é realmente incrível. Na verdade, ele conseguiu pesquisar uma maneira de fazer os galos botarem ovos.",
  [822505833580288] = "Brilhante, brilhante. Você sempre inventa um motivo para chegar atrasado. Mas Toby, não haverá próxima vez. Estou cansado de ouvir essas histórias.",
  [822505833580032] = "E então, e então minha carteira foi roubada! Levei muito tempo para encontrá-lo!",
  [822505833579776] = "Desculpe, desculpe! No caminho para cá, conheci uma criança muito lamentável e dei-lhe uma moeda...",
  [822505833579520] = "Este é o nosso terceiro encontro e também é a terceira vez que você se atrasa.",
  [822505833579264] = "É por isso que tenho que investigar esse maldito mercado! Se eu descobrir quem fez isso, eles estarão acabados!",
  [822505833579008] = "Isso parece sério. Um vazamento em grande escala deve envolver alguém de dentro.",
  [822505833578752] = "Um aluno relatou que alguém no mercado está divulgando questões do exame em grandes quantidades, afetando seriamente a imparcialidade do exame.",
  [822505833578496] = "Aconteceu alguma coisa?",
  [822505833578240] = "Caramba! De todos os lugares, tinha que ser o mercado. Com tantas pessoas, por onde devo começar?",
  [822505833577984] = "Além disso, aqui fica perto da banca de livros do Sênior Ambrose... não, espere, é que estou acostumada a estar aqui!",
  [822505833577728] = "Não estou acostumado a estudar sem barulho.",
  [822505833577472] = "Por que você está lendo aqui?",
  [822505833577216] = "Senhor das Tempestades... Deusa da Meia Noite... Hmm... Que o velho sênior também me abençoe...",
  [822505833576960] = "Hum? Tentando me enganar? Vá embora, vá embora!",
  [822505833576704] = "Escopo do exame?",
  [822505833576448] = "Se você não me contar, como posso fornecer o escopo do exame?",
  [822505833575936] = "Multar. O que você está estudando e quem é seu professor?",
  [822505833575680] = "Ah... sim. Não pareço um?",
  [822505833575424] = "Um amigo te apresentou? Você também é estudante?",
  [822505833575168] = "Um amigo me apresentou.",
  [822505833574912] = "Hum? De onde você veio? Vá embora, vá embora!",
  [822505833574656] = "Isso não parece apenas isso.",
  [822505833574400] = "Hum... a regra é que você tem que pagar um depósito para reservas.",
  [822505833574144] = "Quais regras habituais?",
  [822505833573888] = "As regras de sempre, você sabe... Hmm? Quem é você?",
  [822505833573632] = "Obrigado por suas amáveis ​​​​palavras; Espero que eles também se tornem realidade.",
  [822505833573376] = "Uau! Uau!",
  [822505833573120] = "Parece impecável.",
  [822505833572608] = "Diga-me, como está minha sorte hoje?",
  [822505833572352] = "O que devo fazer...",
  [822505833572096] = "Então você é um caçador de manuscritos.",
  [822505833571840] = "Além disso, está quase na hora de enviar o manuscrito, então me sinto mais seguro em ficar de olho nele.",
  [822505833571584] = "Suspiro, estou preocupado que ele tenha ficado obcecado por seu próprio romance. Ele tem agido de forma estranha ultimamente.",
  [822505833571328] = "O que está errado?",
  [822505833571072] = "Uma pessoa usando cartola e traje formal? Talvez eu deva acrescentar: alguém que está sempre falando para o alto.",
  [822505833570816] = "Você já viu...",
  [822505833570560] = "Bêbado, preciso de bebida... preciso beber... quero beber...",
  [822505833570304] = "Parece... ainda não está certo?",
  [822505833570048] = "<P_Heart> (abaixando a voz deliberadamente) </> Eu não quero falar com um... v-v-vampiro como você.",
  [822505833569536] = "<P_Heart> (falando em voz deliberadamente baixa) </> Não trabalhei duro? Eu trabalhei muito! O trabalho duro rende dinheiro? Trabalhei muito e não consegui nada!",
  [822505833569280] = "Eh...",
  [822505833569024] = "Às vezes pense em seus próprios motivos! Já se passaram tantos anos; seu salário aumentou? Você trabalhou duro?",
  [822505833568512] = "Além de beber e jogar cartas, seu sangue também não tem um gosto tão bom.",
  [822505833568256] = "Miau... miau.",
  [822505833568000] = "Ele realmente tem esse tipo de experiência?",
  [822505833567488] = "<P_Heart> (falando deliberadamente em voz estridente) </> Se alguém puder oferecer 50 peixes secos neste momento crítico, será o prefeito de Tingen no futuro!",
  [822505833566976] = "A lenda do amanhã, o filho mais novo do Rei, está sendo expulso por alienígenas e enfrenta uma crise de escassez de alimentos.",
  [822505833566720] = "Ele - o Montague IV de Vlad, o quarto filho do rei, o leão mais jovem...",
  [822505833566464] = "Recuperando seu território?",
  [822505833566208] = "Kairos está reivindicando seu território.",
  [822505833565952] = "O que você está fazendo?",
  [822505833565696] = "<P_Heart> (falando com uma voz deliberadamente estridente) </> Ei, seu maldito pombo, venha aqui.",
  [822505833564928] = "<P_Heart> (falando com uma voz deliberadamente estridente) </> Não aja como se nada estivesse acontecendo. Fugir! É aqui que eu durmo!",
  [822505833564672] = "Quem sabe.",
  [822505833564416] = "Os dois não moram na Memorial Square? Isso não é estranho para Robert?",
  [822505833564160] = "Acho que foi a senhorita Ariel.",
  [822505833563904] = "Acho que ele foi cortejar a senhorita Campbell.",
  [822505833563648] = "Para onde aquele cara, Robert, fugiu, deixando o pequeno Robert para trás novamente?",
  [822505833563392] = "Não tem problema, Sra. Julia.",
  [822505833563136] = "Ah, quase esqueci. Só preciso de 5 quilos de pão hoje.",
  [822505833562880] = "Isso soa bem. Dê-me dois bolos de limão e hortelã.",
  [822505833562624] = "Tem a acidez do limão e o aroma refrescante da menta, além da receita secreta de bolo do meu pai. É delicioso.",
  [822505833562368] = "Sim, dona Júlia. Você gostaria de comprar um bolo? Recomendo o bolo de limão e menta de hoje.",
  [822505833562112] = "Pequeno Robert, você está ajudando seu pai a cuidar da loja sozinho de novo hoje?",
  [822505833561856] = "Deve ser porque seu cérebro está crescendo!",
  [822505833561600] = "Por que minha cabeça está coçando...",
  [822505833561344] = "Isso significa que nos tornamos mais inteligentes?",
  [822505833561088] = "Claro! Essa foi uma fórmula que me foi dada por um mestre do misticismo.",
  [822505833560832] = "Uau! Este ritual realmente parece funcionar!",
  [822505833560576] = "Eu sinto que algum tipo de existência desceu!",
  [822505833560320] = "Jen... não quero que você encontre o colar que te dei. Você ficou no mesmo lugar por muito tempo.",
  [822505833560064] = "Jane é minha esposa.",
  [822505833559808] = "Quem é essa Jane de quem você está falando?",
  [822505833559552] = "Jane, perdoe meu egoísmo. O colar está no canto do telhado.",
  [822505833559296] = "Ela quer que eu saiba que não devo ficar olhando para trás, pois o caminho à frente é ainda mais bonito.",
  [822505833559040] = "Arrependimento? Talvez tudo isso seja a orientação da Deusa.",
  [822505833558784] = "Lamento muito ouvir isso.",
  [822505833558528] = "E a única coisa que eles deixaram para você desapareceu, o que você faria?",
  [822505833558272] = "Se, digamos, um membro da sua família muito precioso e querido faleceu...",
  [822505833558016] = "Parece que você está de mau humor. Aconteceu alguma coisa?",
  [822505833557760] = "Para a família, sugiro aqui estas tulipas... talvez você também deva adicionar sua própria companhia.",
  [822505833557504] = "Para um amante, você pode escolher rosas ou lírios.",
  [822505833557248] = "Se for presente para um amigo, recomendo violetas ou margaridas.",
  [822505833556992] = "Você tem alguma recomendação?",
  [822505833556736] = "Se você gostar de algum, posso te dar alguns.",
  [822505833556480] = "Sinta-se à vontade para dar uma olhada em qualquer uma dessas flores.",
  [822505833556224] = "Estou apenas olhando.",
  [822505833555968] = "{{Sr.|Sra.}}, você gostaria de comprar algumas flores?",
  [822505833555712] = "Mas mesmo agora, quando ela está sentada em sua barraca, ela olha de vez em quando para o colar que seu marido lhe deixa.",
  [822505833555456] = "Foi uma sorte que os vizinhos a ajudaram nos momentos mais difíceis.",
  [822505833555200] = "O marido faleceu cedo e o casal não teve filhos, deixando apenas estas flores para ela.",
  [822505833554944] = "Pensando bem, realmente não é fácil para a Sra. Wyndham sozinha.",
  [822505833554688] = "Eu realmente não sei como a Sra. Wyndham consegue cuidar de tantas flores!",
  [822505833554432] = "No mercado e na casa dela são só flores! Também há flores que ela plantou no telhado.",
  [822505833554176] = "Já que um transeunte disse isso, você deveria me perdoar desta vez.",
  [822505833553920] = "Qualquer um pode ver que isso não é razoável. Romper!",
  [822505833553664] = "Sim, você!",
  [822505833553408] = "Eu... devo julgar?",
  [822505833553152] = "Deixe um transeunte julgar isso. Cujo amante só pode reservar um dia por semana para você?",
  [822505833552896] = "Não fale bobagem, eu só amo você.",
  [822505833552640] = "Você tem outra mulher lá fora? Por que você nem tem tempo de me acompanhar?",
  [822505833552384] = "Mas está tudo bem, não vim procurá-lo? Ele definitivamente ficará agradavelmente surpreso em me ver!",
  [822505833552128] = "Eu o entendo. O trabalho no teatro está sempre ocupado e, como gestor, ele tem ainda mais trabalho.",
  [822505833551872] = "Meu marido Bradley nunca está em casa e, mesmo quando volta, já é tarde da noite.",
  [822505833551616] = "Senhora, seu marido está sempre ocupado?",
  [822505833551360] = "O casamento é verdadeiramente o túmulo do amor. Pessoas que antes estavam juntas a cada momento ficam distantes depois de entrarem no casamento...",
  [822505833551104] = "Podemos ter um encontro agradável e perfeito à beira do lago!",
  [822505833550848] = "Espero que não haja nenhum problema irritante que obrigue Bradley a sair repentinamente durante este encontro.",
  [822505833550592] = "Na verdade, sempre que o vejo, não consigo deixar de querer abraçá-lo.",
  [822505833550336] = "Devo ser reservado quando o vir mais tarde ou devo me jogar em seus braços?",
  [822505833550080] = "Quando eu for eleito prefeito, você não será? Apenas aguente um pouco mais, meu tesouro.",
  [822505833549824] = "Ainda não, você é tão chato...",
  [822505833549568] = "Certo, eu te amo mais.",
  [822505833549312] = "Sim, o candidato a prefeito que mais ama a esposa!",
  [822505833549056] = "Como poderia? Ninguém pode me ver, e mesmo que vissem, pensariam que estavam vendo coisas.",
  [822505833548800] = "Você vindo ver minha apresentação não vai te tirar uma foto, certo? Este é o período crítico da sua campanha.",
  [822505833548544] = "Espere, a manchete de amanhã será uma foto dos dois juntos!",
  [822505833548288] = "Hoje é o aniversário de um ano da estreia de sua amante, e a candidata a prefeito vem ver sua atuação.",
  [822505833548032] = "Aquele candidato a prefeito que se apresenta como tendo uma família feliz e amando sua esposa e filha tem uma amante secreta que é atriz deste teatro.",
  [822505833547776] = "Isso é bom, você não deve fazer barulho. Estou de olho em um grande furo!",
  [822505833547520] = "Hum, só estou de passagem...",
  [822505833542144] = "<P_Heart> (Rindo) </> Considere isso seu amor por fazer guias.",
  [822505833541888] = "Então qual era o objetivo do guia que passei a noite toda pesquisando?",
  [822505833541632] = "É a primeira vez que eles visitam uma cidade grande, então a excitação e a curiosidade são inevitáveis. Acho que eles foram brincar sozinhos.",
  [822505833541376] = "Eu disse para eles me esperarem na entrada enquanto eu subia para pegar o guia. Mas quando voltei, eles tinham ido embora!",
  [822505833541120] = "Sim! Eles estão vindo para Tingen pela primeira vez, então preparei especialmente um 'Guia de Viagem de Tingen' com antecedência, querendo levá-los adequadamente.",
  [822505833540864] = "Você está separado de sua família?",
  [822505833540608] = "Se acontecer de você vê-lo na universidade, diga olá por mim. Estou um pouco bagunçado, então não vou lá e envergonhá-lo.",
  [822505833540352] = "Assim que ele se formar e encontrar um emprego decente, nossa família poderá realmente permanecer firme em Tingen!",
  [822505833540096] = "<P_Heart> (radiante) </> Cantando sobre meu filho! Meu filho Harvey entrou na Hoey University! Ele é um estudante universitário!",
  [822505833539840] = "O que você está cantando?",
  [822505833539584] = "<P_Heart> (Sorriso amargo) </> Obrigado, eu realmente entendo a lógica... Esqueça, voltarei depois de terminar este copo. Eu realmente não posso apodrecer aqui, certo?",
  [822505833539328] = "Você pode ir devagar, terminar os estudos primeiro e depois pensar em encontrar um emprego. O caminho é percorrido um passo de cada vez.",
  [822505833539072] = "Eu o decepcionei e tenho medo do futuro... Neste Tingen, para quem estuda literatura, qual é a saída?",
  [822505833538816] = "<P_Heart> (Sufocando com soluços) </> Nossa família fica na Rua Iron Cross... Papai trabalhou duro para me criar como um estudante universitário. Mesmo assim, fico bêbado aqui todos os dias, como lama que não gruda na parede.",
  [822505833538560] = "<P_Heart> (Irritado) </> Não é só isso. Há também o futuro sem fim! A cidade cheia de fumaça de carvão, barulho e monstros de aço – onde há espaço para uma mesa silenciosa? Minha caneta pode escrever poesia, mas não consegue atravessar essa névoa espessa.",
  [822505833538304] = "Como poderia ser assim? A pressão acadêmica é muito alta?",
  [822505833538048] = "Sim... Departamento de Literatura da Universidade Hoey, mas essa minha vida universitária... <P_Heart> (Sorriso autodepreciativo) </> quanto mais eu vou, mais eu quero desistir...",
  [822505833537792] = "Você é um estudante universitário?",
  [822505833537536] = "<P_Heart> (Atordoado) </> Me deixe em paz, deixe-me ficar bêbado até o amanhecer... de qualquer maneira... de qualquer maneira, meus colegas vão me carregar de volta...",
  [822505833537280] = "Você está bem? Por que você está bebendo sozinho aqui?",
  [822505833537024] = "<P_Heart> (Desamparado) </> Você deve ir até a recepção e olhar o catálogo do clube e escolher um adequado.",
  [822505833536768] = "Então você sabe qual adivinho é o mais preciso? Vou deixar que ele calcule o jantar para mim primeiro, estou com pressa para saber!",
  [822505833534976] = "<P_Heart> (Desamparado) </> Tenho algumas coisas para fazer hoje, você deveria ir até a recepção e olhar o catálogo do clube.",
  [822505833534720] = "Então você vai me ajudar a calcular ou não? Apresse-se e calcule primeiro o jantar, estou com pressa para saber!",
  [822505833534208] = "<P_Heart> (Mãos na cintura) </> Você não entende, gente rica tem problemas de gente rica! De qualquer forma, não estou com falta de dinheiro!",
  [822505833533952] = "<P_Heart> (Segurando a testa) </> Você gastou dinheiro para vir aqui só por isso...",
  [822505833533696] = "Aliás, quero comprar chá gelado doce esta noite, quero perguntar se o de hoje vai ser bom! Folha de chá adivinhação é a mais indicada! Finalmente, se meu cachorro vai roubar meus lanches! Isso está me deixando louco, meu pudim de limão—",
  [822505833533440] = "Além disso, devo colocar o relógio que meu pai me deu no bolso esquerdo ou no bolso direito para que seja menos provável que seja roubado? Isso precisa ser calculado cuidadosamente com um mapa estelar!",
  [822505833533184] = "Quero usar o Tarô para calcular o que o mordomo vai fazer para o jantar hoje à noite – não deixe que sejam aquelas folhas de vegetais de novo! Depois use o pêndulo para perguntar se minha mãe vai descobrir se eu faltar à aula amanhã!",
  [822505833532928] = "Então deixe-me contar minhas perguntas!",
  [822505833532672] = "Depende da pergunta que você deseja fazer para escolher o adivinho certo.",
  [822505833532416] = "<P_Heart> (Parecendo um pouco desapontado) </> Oh. Então você sabe quem é o adivinho mais preciso aqui?",
  [822505833532160] = "Sou apenas um cliente também.",
  [822505833531904] = "<P_Heart> (Limpando a garganta, fingindo ser formal) </> Posso perguntar o que você quer adivinhar?",
  [822505833531648] = "<P_Heart> (Olhos iluminando) </> Sério? Então por favor calcule para mim! Vamos encontrar um quarto privado, diga seu preço!",
  [822505833531392] = "Para ser sincero, conheço um pouco sobre Pendulum Adivinhação e Tarot Adivinhação .",
  [822505833531136] = "<P_Heart> (Olhando para cima e para baixo) </> Você é o adivinho aqui? Que tipo de adivinhação você faz?",
  [822505833530880] = "Você parece muito animado.",
  [822505833529600] = "Perguntei se passaria no exame de história. Embora eu esteja bastante interessado em história, sinto dor de cabeça assim que começo a memorizar.",
  [822505833529088] = "A família dele é tão rica que ele pode conseguir o que quiser, mas ainda assim quer adivinhação ? Não consigo imaginar o que ele iria perguntar...",
  [822505833528832] = "Eu contei a Orland sobre isso também. A família dele não é muito rica? Ele ameaçou tentar todas as adivinhações.",
  [822505833528576] = "Embora seja o resultado do seu trabalho duro, ainda parece muito mágico! Também quero testar alguns eventos importantes da vida, como casamento, carreira e assim por diante.",
  [822505833528320] = "Aí gastei uma mesada para ganhar uma moeda adivinhação , e ela dizia que eu poderia passar - no final, consegui mesmo, e a pontuação não foi baixa! Da próxima vez pretendo ir e adivinhar se posso ir para Backlund para me desenvolver após a formatura.",
  [822505833528064] = "Perguntei se conseguiria passar no exame de história. Você sabe, embora eu realmente queira ouvir com atenção, este curso é realmente hipnótico.",
  [822505833527808] = "Diga-me rapidamente, o que você testou? É tão mágico?",
  [822505833527552] = "Aguardo sua palestra!",
  [822505833527296] = "Obrigado, de repente não estou mais tão ansioso. Depois de terminar a próxima cirurgia, correrei para terminar o resumo da palestra hoje à noite!",
  [822505833527040] = "<P_Heart> (Sorrindo) </> Ter alguém que você conhece por perto também pode aliviar um pouco a tensão.",
  [822505833526784] = "<P_Heart> (Um pouco relaxado) </> Mas nossas enfermeiras do hospital podem ser melhores nesse aspecto. Vou procurar uma enfermeira para ser minha parceira!",
  [822505833526528] = "<P_Heart> (Acenando com a cabeça) </> Boa ideia. Por exemplo, enxágue com água fria imediatamente após uma queimadura, em vez de espalhar pomadas aleatórias; pequenas feridas devem ser limpas com soro fisiológico fervido e resfriado antes de serem embrulhadas em pano de algodão limpo. Estes tratamentos simples podem evitar muitas infecções subsequentes.",
  [822505833526272] = "Acho que podemos popularizar alguns métodos comuns de primeiros socorros para lidar com algumas emergências diárias.",
  [822505833526016] = "Essa é exatamente a reputação de padrão ouro do hospital! É a melhor promoção!",
  [822505833525760] = "É claro que nem todas as famílias de trabalhadores podem arcar com as taxas de cirurgia, que é a parte mais desamparada neste momento. Tudo o que podemos fazer é realizar todas as cirurgias com solidez e não decepcionar a confiança dos pacientes.",
  [822505833525504] = "No passado, um ferimento grave arruinaria uma família. Agora, graças à cirurgia, muitas pessoas podem retornar aos seus postos. Mesmo que haja infecção pós-operatória ocasional, praticamos há muito tempo os procedimentos subsequentes de desinfecção e troca de curativos, e a maioria pode ser estabilizada!",
  [822505833525248] = "A área fabril tem um ambiente precário e a maioria dos trabalhadores tem doenças pulmonares, e a taxa de acidentes de trabalho também é muito alta.",
  [822505833524992] = "<P_Heart> (Pensando) </> Essa deve ser a taxa de sucesso da cirurgia! Embora nosso hospital só tenha utilizado a cirurgia como um método de tratamento importante nos últimos anos, nossos médicos aprendem muito rapidamente e curaram muitos ferimentos industriais e doenças agudas de trabalhadores de fábricas.",
  [822505833524736] = "Já que o diretor quer que você promova o hospital, por que não falar sobre os pontos fortes do hospital?",
  [822505833524480] = "<P_Heart> (Envergonhado) </> Agora que você mencionou... parece que é realmente esse o caso.",
  [822505833524224] = "Esse conhecimento pode realmente ajudar muitas pessoas. E veja, você é claramente muito bom em explicar essas coisas.",
  [822505833523968] = "E cuidados com feridas. Muitas pessoas o lavam diretamente com água suja ou embrulham-no em um pedaço de pano aleatório, o que facilita a infecção. Limpeza, desinfecção e curativos adequados não são difíceis de aprender.",
  [822505833523712] = "Isso faz sentido... Por exemplo, a gripe durante as mudanças sazonais. Na verdade, prestar atenção à ventilação e lavar as mãos com frequência pode reduzir bastante a transmissão. Muitas pessoas ficam com medo de que seja tuberculose assim que tossem, o que acaba atrasando o tratamento.",
  [822505833523456] = "Você poderia falar sobre o bom senso médico básico, deixar que todos entendam como lidar com doenças comuns e evitar pânico e erros de julgamento.",
  [822505833523200] = "Eu penso...",
  [822505833522944] = "Eu realmente não consigo lidar com uma multidão tão grande. Prefiro realizar mais algumas cirurgias! Eu nem tenho ideia do esboço da palestra ainda.",
  [822505833522688] = "Nosso diretor do hospital quer que eu vá para a Universidade de Tingen para dar uma palestra médica, popularizar alguns conhecimentos médicos e, aliás, promover o hospital.",
  [822505833522432] = "<P_Heart> (Atordoado por um momento) </> Ah, não, não é nada. Estou apenas tendo um simples ataque de nervosismo e ansiedade.",
  [822505833522176] = "<P_Heart> (Surpreso) </> O hospital não está logo atrás de você? Mas olhando para você, temo que nem mesmo o Imperador Roselle possa ajudar.",
  [822505833521920] = "Sinto que meu coração está prestes a explodir e meu sangue está como água fervente agora! Minhas mãos, braços, pernas, pés, tudo está tremendo! Vou fazer uma cirurgia mais tarde e não consigo nem segurar o bisturi assim!",
  [822505833521664] = "Doutor, o que há de errado com você? Você precisa consultar um médico?",
  [822505833521152] = "<P_Heart> (Surpreso) </> Hein? Isso... eu realmente não pensei nisso dessa perspectiva...",
  [822505833520896] = "Então é possível que a comida em si simplesmente não tenha um gosto bom?",
  [822505833520640] = "Mais importante ainda, a senhora que serve a comida não! Sacudir! Dela! Mão!",
  [822505833520384] = "<P_Heart> (Levantando a voz, parecendo orgulhoso) </> Olha, a decoração da nossa cafeteria é incomparável; está completamente ao nível de um restaurante topo de gama, luminoso e imponente; os assentos são macios e muito confortáveis; e os preços também são muito baratos.",
  [822505833520128] = "Realmente? Mas as pessoas não parariam de vir sem motivo.",
  [822505833519872] = "O número de pessoas que frequentam o refeitório diminuiu visivelmente recentemente. As sobras na cozinha estão empilhadas e faz muito tempo que não vejo muitos rostos familiares. Estou pensando nisso há dias, mas não consigo entender o que há de errado com o refeitório!",
  [822505833519616] = "Você é o cozinheiro do refeitório, certo? Você teve algum problema?",
  [822505833519360] = "<P_Heart> (Lágrimas de alegria) </> Oh, meu estômago, seus dias bons estão finalmente chegando—",
  [822505833519104] = "Sim! É hora de tratar melhor meu estômago!",
  [822505833518848] = "Ah, Deusa! Isso soa cem vezes melhor do que o refeitório! Vamos marcar um horário para ir lá uma vez!",
  [822505833518592] = "Ouvi dizer que eles grelham o bife até que a crosta fique carbonizada e perfumada, enquanto o interior fica macio e suculento, com um molho rico e suave. Ao contrário da sopa da cafeteria, que é tão insípida que nem tem gosto.",
  [822505833518336] = "Quero muito comer o bife de pimenta preta do restaurante do Velho Will...",
  [822505833518080] = "E aquela carne ensopada pegajosa e ovos fritos queimados... <P_Heart> (Nauseado) </> Chega, chega! Só de pensar nisso me dá vontade de vomitar!",
  [822505833517824] = "Isso é assassinato contra comida! Repolho cozido demais, alface cozida seca e dura, sopa de ervilha com gosto de água...",
  [822505833517568] = "Se eu continuar comendo nesta cafeteria, tenho medo que meu estômago tente falhar enquanto eu durmo!",
  [822505833517312] = "Wuu... isso realmente não é possível? Tudo bem, eu mesmo farei isso.",
  [822505833517056] = "Que boa criança, mas temo que as canetas não façam a lição de casa sozinhas.",
  [822505833516800] = "Eles estão trabalhando ou fazendo tarefas domésticas e já estão muito cansados. Se a caneta pudesse dividir o fardo do meu dever de casa, eu teria tempo para ajudá-los a se preparar para a festa depois de amanhã.",
  [822505833516544] = "Meu pai, minha mãe, meu irmão e eu fazemos aniversário no mesmo dia. Todos os anos, na festa de aniversário, fico preso fazendo lição de casa enquanto eles estão ocupados...",
  [822505833516288] = "Por que você não faz isso sozinho?",
  [822505833516032] = "Pen, você é uma caneta madura agora. Você deve aprender a fazer sua lição de casa sozinho.",
  [822505833515776] = "Onde eu conseguiria tanto dinheiro! Além disso, papai e mamãe são saudáveis ​​e minha irmã mais nova é sensata e boa nos estudos. Poder comer juntos nesta época todos os anos – não há presente melhor do que esse.",
  [822505833515520] = "Já que é aniversário de toda a família, que tal o seu próprio presente?",
  [822505833515264] = "Sim, toda a minha família faz aniversário depois de amanhã. Um par de luvas novas para o papai, uma faca de cozinha nova para a mamãe e uma caneta nova para minha irmã mais nova.",
  [822505833515008] = "Esses presentes estão preparados para alguém?",
  [822505833514752] = "Então, essa deve ser a vontade de Deus, querer que eu cuide da minha família. Juro que, enquanto eu ainda puder trabalhar, meus presentes anuais de aniversário nunca se atrasarão!",
  [822505833514496] = "Não acredito que exista tal coincidência no mundo.",
  [822505833514240] = "Não vou mentir para você, nós quatro da família fazemos aniversário no mesmo dia.",
  [822505833513984] = "Sua esposa e filhos fazem aniversário no mesmo dia?",
  [822505833513728] = "Sim, minha esposa e meus filhos fazem aniversário depois de amanhã. Vou fazer uma boneca para cada um deles.",
  [822505833513472] = "Você está fazendo artesanato?",
  [822505833513216] = "<P_Heart> (Por que seus olhos estão olhando ao redor?) </>",
  [822505833512960] = "...Desculpe, cliente, acabamos de esgotar. Definitivamente da próxima vez.",
  [822505833512704] = "Isso é bom? Compre um para mim também.",
  [822505833512448] = "Bebida refrescante, forte e barata, é uma dádiva de Deus para um pobre como eu.",
  [822505833512192] = "Que tipo de lugar é esse?",
  [822505833511936] = "Obrigado, ficarei de olho.",
  [822505833511680] = "Esses contrabandistas não têm resultados financeiros; eles usam matérias-primas industriais que nem mesmo as fábricas querem para fabricar álcool, prejudicando outras pessoas em seu próprio benefício. Você também deve ter cuidado para não ser enganado. Se você encontrar alguém suspeito de ser contrabandista, por favor me avise.",
  [822505833511424] = "Um contrabandista que a agência vem rastreando fugiu perto da siderúrgica. Acho que ele deve estar escondido em um canto tranquilo, então vim aqui procurar. Acontece que encontrei este senhor caído no chão. Felizmente, não era tarde demais.",
  [822505833510912] = "Isso mesmo, esta é a vida que eu quero. Uma vida pura e simples é o verdadeiro negócio.",
  [822505833510656] = "Ser comum até certo ponto é também uma forma de ser extraordinário?",
  [822505833510400] = "Você está exagerando demais. Sou apenas um velho mendigo.",
  [822505833510144] = "Ela deve ser protegida pelo favor da Deusa para poder trabalhar de forma constante até a aposentadoria.",
  [822505833509888] = "Lesões no local de trabalho e demissões são comuns para as pessoas comuns aqui, mas a Sra. Bertran trabalhou durante quarenta anos inteiros e sempre conseguiu evitar tais infortúnios. Ela nunca se atrasou ou faltou!",
  [822505833509632] = "Deixe-me dizer, esta Sra. Bedolan é uma trabalhadora lendária escolhida pela Deusa.",
  [822505833509376] = "Com licença, o que significa “confiar na sorte desta velha”?",
  [822505833509120] = "Hmph, deixe-os gritar. Eles podem gritar o quanto quiserem. Os jovens não compreendem a sociedade; eles certamente sentirão um gosto amargo disso.",
  [822505833508864] = "Uma nova maneira de ganhar dinheiro? Suspiro, eu agradeceria aos céus se ele não expulsasse nossos velhos hábitos.",
  [1130369089159168] = "Por que você está com raiva...",
  [822505833508352] = "Estou com dificuldade de ouvir. Sobre o que aquele garoto novo estava gritando?",
  [822505833508096] = "Tsk, se perca. Cuide da sua vida.",
  [822505833507840] = "Quem, quem disse alguma coisa sobre sequestro? Você deve ter ouvido mal.",
  [822505833507584] = "Quem você está planejando sequestrar?",
  [822505833507328] = "Fale baixo! Há muitas pessoas aqui; não deixe ninguém ouvir você.",
  [1130369089383424] = "O que você está olhando?",
  [822505833506816] = "Desculpe, deixe-me pensar um pouco mais.",
  [822505833506560] = "Não é apenas um planejamento discutir com futuros parceiros? Vamos nos tornar as novas estrelas do mundo dos negócios de Tingen juntos!",
  [822505833506304] = "Ninguém se atreveria a fazer parceria com você assim, certo?",
  [822505833506048] = "Hehe, ainda não pensei nisso.",
  [822505833505792] = "Para que tipo de negócio estamos fazendo parceria?",
  [822505833505536] = "Então, você é o parceiro que eu estava esperando?",
  [822505833505280] = "A oportunidade bate à porta apenas uma vez, fale comigo agora sobre como investir em ações. Você não vai perder, não será enganado!",
  [822505833505024] = "Eu, Ricky Newman, trouxe uma nova maneira de ganhar dinheiro em Tingen e convido sinceramente os interessados ​​a fazer parceria comigo para abrir uma loja.",
  [822505833504512] = "Hornacis, continua o mesmo de sempre... Perdi da última vez, mas da próxima trarei novos 'brinquedos' e farei outro 'jogo de engano'.",
  [822505833502720] = "Ei, você está aqui! Vá dizer ao capitão que precisamos esperar até depois da tempestade para zarpar!",
  [822505833502464] = "(Suspiros) Tudo bem, tudo bem, agora tenho que gastar dinheiro para comprar capas de chuva.",
  [822505833502208] = "Ah, como eu disse! Meu capitão, parece que primeiro temos que preparar guarda-chuvas para o navio.",
  [822505833501952] = "Desculpe, {{Sr.|Sra.}}. Preciso concluir os preparativos para zarpar o mais rápido possível, você pode encontrar meu primeiro imediato...",
  [822505833501696] = "<P_Heart> (Ajude-me a adivinhar o clima futuro...) </>",
  [822505833501440] = "Você sabe do que estou falando, {{Sr.|Sra.}}. Use seus instrumentos meteorológicos ou qualquer outra coisa para avisar nosso capitão que não devemos zarpar hoje!",
  [822505833501184] = "Olha esse tempo, parece um dia ensolarado? O capitão ainda está lá verificando se a carga está no navio. Aposto que duas horas depois de zarpar estaremos todos no fundo do mar.",
  [822505833500672] = "Boa tarde, {{PlayerName}}, tive a premonição de que você apareceria.",
  [822505833147136] = "É assim, quando saí em patrulha esta manhã, descobri que nosso reino estava bloqueado. Tentei encontrar uma brecha, mas ainda não consegui voltar à base.",
  [822505833496320] = "O tempo passa tão rápido que dessa vez já é um piscar de olhos.",
  [822505833496064] = "Se você se sentir confuso sobre um local durante o roaming, lembre-se das instruções que indiquei no mapa a qualquer momento; memória clara é o melhor sinal de trânsito.",
  [822505833495808] = "As oportunidades de roaming estão por toda Tingen. Se você quiser economizar esforço, você também pode <P_Yellow> diariamente </> receber <P_Yellow> três missões de roaming aleatórias </> minhas. Após recebê-los, verifique a aba <P_Yellow> Roaming </> no menu Missão.",
  [822505833495552] = "Se você quer realmente entender este lugar, é melhor caminhar mais entre os sinos das igrejas, os gritos do mercado e as conversas da taberna. As histórias estão escondidas no dia a dia das pessoas.",
  [822505833495296] = "A cidade de Tingen está localizada no norte do Reino de Loen, pertencente ao condado de Awwa. Aqui está o rio Hoy que atravessa a cidade e é elogiado pelos poetas, bem como a tranquila e solene Igreja Ortodoxa no Distrito Norte e o movimentado e barulhento mercado portuário no Distrito Sul.",
  [822505833495040] = "Parece que você começou a sentir esta cidade no seu próprio ritmo. Cada canto de Tingen vale a pena saborear, especialmente sob iluminação diferente... você sempre descobrirá novos detalhes.",
  [822505833494784] = "É uma lâmpada na neblina, mas lembre-se: a mão que segura a lâmpada deve ser sempre sua própria pessoa sóbria.",
  [822505833494528] = "Então qual é o significado de adivinhação ?",
  [822505833494272] = "No Mundo Extraordinário, a decisão verdadeiramente segura é sempre o caminho que você escolhe trilhar após múltiplas verificações e julgamento cauteloso.",
  [822505833494016] = "Mas este rio pode sofrer interferência de muitos fatores: o próprio subconsciente do adivinho, a flutuação livre espiritualidade no ambiente, ou mesmo um olhar não intencional de outras existências de alto nível, todos os quais farão com que a superfície da água reflita imagens distorcidas.",
  [822505833493760] = "Uma afirmação mais precisa é— adivinhação mostra o rio de possibilidades com a maior probabilidade.",
  [822505833493504] = "adivinhação pode realmente prever o futuro?",
  [822505833493248] = "Lembre-se dos tabus dos diferentes anfitriões em cada banquete. Não se pode falar de frutos do mar na casa da família Wilson porque o filho mais velho é alérgico a frutos do mar; a família Carlos evita falar sobre o tempo porque os navios mercantes da família sofreram pesadas perdas numa tempestade.",
  [822505833492992] = "Qual é a parte mais cansativa?",
  [822505833492736] = "Como participar de um exame de etiqueta no qual você nunca poderá passar. Na semana passada, repeti “Seu chapéu está realmente chique hoje” sete vezes em três chás.",
  [822505833492480] = "Qual é a sensação de participar continuamente de banquetes durante a temporada social?",
  [822505833492224] = "Mais tarde, a Igreja das Tempestades investigou rigorosamente este assunto. Afinal, tais fenômenos expõem facilmente a Beyonder existência e também podem afetar navios inocentes.",
  [822505833491968] = "Eu ouvi o 'Homem Enforcado' mencionar que uma vez ele testemunhou dois meio Sequência Beyonders lutando no mar por um Artefato Selado, e o resultado realmente fez com que a superfície do mar queimasse por mais de dez minutos.",
  [822505833491712] = "Você viu exemplos relevantes?",
  [822505833491456] = "Indivíduos com baixo Sequência às vezes desencadeiam anomalias de pequena escala e de curto prazo, como fazer as gotas de chuva pairarem ou fazer o vento virar brevemente - mas a maioria são comportamentos inconscientes e são difíceis de sustentar.",
  [822505833491200] = "E quanto aos indivíduos com baixo Sequência?",
  [822505833490944] = "Isso depende do nível Sequência. Altos Sequência Santos ou Anjos podem de fato desencadear fenômenos climáticos anormais em grande escala, mas isso geralmente significa perda de controle ou transbordamento de divindade, o que é um fenômeno bastante perigoso.",
  [822505833490688] = "Beyonders pode influenciar o clima?",
  [822505833490432] = "\"Observe a pessoa à sua esquerda.\" Só descobri mais tarde que ela estava lembrando ao cavalheiro ao lado dela que a fivela da faixa havia se aberto.",
  [822505833490176] = "O que isso significa?",
  [822505833489920] = "Alguns ainda os seguem em ocasiões formais. No jantar diplomático do mês passado, a esposa do Embaixador Faris bateu três vezes no ombro esquerdo com o leque.",
  [822505833489664] = "As pessoas ainda usam essas regras agora?",
  [822505833489408] = "Isso significa 'Por favor, fique longe de mim'. E segurar o leque verticalmente contra o queixo é dizer: 'Estou disposto a falar com você'.",
  [822505833489152] = "E se você agitar o ventilador rapidamente?",
  [822505833488896] = "Na verdade, este é um conjunto de códigos secretos visuais desenvolvidos por senhoras de antigamente, quando era inconveniente falar diretamente em situações sociais. Por exemplo, deslizar lentamente o leque pela bochecha geralmente significa 'Estou muito entediado'.",
  [822505833488640] = "Sra. Audrey, você pode me dizer o significado específico da linguagem dos fãs? Li sobre isso no jornal e estou muito interessado.",
  [822505833488384] = "No ano passado, alguém enviou uma carta de cobrança de dívidas com selo de cera dourada. O destinatário pensou ter descoberto um antigo mapa do tesouro e foi ao local combinado com ferramentas de escavação.",
  [822505833488128] = "E se você usar o errado?",
  [822505833487872] = "A cor do selo de cera representa a urgência. O vermelho é para saudações diárias, o preto é para assuntos importantes e o roxo... geralmente significa um convite de casamento ou um obituário.",
  [822505833487616] = "Existem muitas nuances em escrever cartas entre nobres?",
  [822505833487360] = "O Senhor congelou por três segundos e então disse: 'Parece que esta xícara de chá queria ter você antes de mim.' Agora eles estão noivos.",
  [822505833487104] = "O que aconteceu depois?",
  [822505833486848] = "O mais embaraçoso foi que a jovem acidentalmente derramou chá no terno branco de Lord Charles - e isso foi algo que ele havia personalizado especialmente da Intis para esta reunião.",
  [822505833486592] = "De fato. Na festa do chá de Lady Caroline na semana passada, foi nominalmente para provar o recém-chegado chá preto do Ceilão, mas na realidade foi para procurar um parceiro para sua sobrinha.",
  [822505833486336] = "Ouvi dizer que existem muitas regras para banquetes de encontros entre nobres?",
  [822505833486080] = "Agora o preço dessa pintura subiu para mil e quinhentas libras.",
  [822505833485824] = "Após avaliação, constatou-se que era falso. Mas o que foi ainda mais dramático foi que o próprio pintor estava presente e imediatamente se ofereceu para comprá-lo por mil libras, dizendo que era o “tributo de maior sucesso da história”.",
  [822505833485568] = "E então?",
  [822505833485312] = "Eu costumava ir uma ou duas vezes por ano. Lembro-me de um incidente interessante num leilão: o Barão Barton insistiu que uma certa pintura a óleo era uma obra autêntica de um mestre famoso e gastou oitocentas libras para ganhar a licitação.",
  [822505833485056] = "Você costuma participar de leilões de caridade?",
  [822505833484800] = "Se você for ao Continente Sul, lembre-se de duas coisas: não beba água mineral que borbulha sozinha e, definitivamente, não jogue dados com pessoas usando máscaras coloridas – os dados que eles usam podem ser ossos velhos encharcados em um século de obsessão.",
  [822505833484544] = "Também troquei um amuleto antigo no mercado <P_Heart> (Tirando meia folha de prata do pescoço) </>, e mais tarde descobri que estava ligado a uma forte impressão emocional. Agora eu uso como chupeta espiritualidade.",
  [822505833484288] = "<P_Heart> (Postando a xícara de chá na mesa) </> Sim, enquanto investigava os costumes antigos no Vale Pas, acidentalmente participei do 'Festival da Colheita Silenciosa' local. As máscaras esculpidas em ossos oferecidas pelos aldeões eram muito especiais – depois de vesti-las, era possível ouvir as antigas orações pairando ao vento.",
  [501378376056576] = "Purificação",
  [822505833484032] = "Você parece ter estado no Continente Sul recentemente?",
  [822505833483776] = "Quando passei férias lá no ano passado, acordei todos os dias com uma ilha diferente do lado de fora da minha janela. <P_Heart> (Sorrisos) </> O único problema é que uma vez a tartaruga gigante fugiu com sua namorada e ficamos à deriva por três dias.",
  [822505833483520] = "Recomendo a Ilha Coral no Mar Sônia. Há um dono de casa de família do 'Marinheiro' Caminho lá, e sua casa foi construída nas costas de uma tartaruga gigante em movimento.",
  [822505833483264] = "Primeiro, você deve evitar noites de lua cheia, dias de pico de marés espirituais e grandes períodos de celebração das Igrejas Ortodoxas.",
  [822505833483008] = "Como devem Beyonders organizar suas férias?",
  [822505833482752] = "Comprei um colar de pérolas no mês passado que muda de cor de acordo com meu humor - veio de um joalheiro de meio período do 'Destino' Caminho . <P_Heart> (Piscando de brincadeira) </> Isso foi uma grande ajuda no baile.",
  [822505833482496] = "Alguns Beyonder materiais estão começando a entrar na alta sociedade sob o nome de 'tecidos vintage'. Por exemplo, a seda reguladora de temperatura feita pelo 'Artisan' Caminho é agora chamada de 'artesanato perdido da era Roselle'.",
  [822505833482240] = "<P_Heart> (Olhos brilham levemente) </> Camisas com babados combinadas com coletes estão de volta à moda! Mas o que é realmente interessante é...",
  [822505833481984] = "Que moda é popular em Backlund recentemente?",
  [822505833481728] = "Um amigo meu comprou uma pintura chamada 'Baile da Meia-Noite' e, como resultado, uma pessoa na pintura desaparece todos os dias às 3h. <P_Heart> (Desamparado) </> Agora aquela pintura está pendurada na cabine da senhora 'Eremita'.",
  [822505833481472] = "Isso foi criado por um pintor do 'Mystery Pryer' Caminho quando seu espiritualidade estava cheio. No entanto, tenha cuidado ao comprar essas pinturas...",
  [822505833481216] = "Colecionei alguns trabalhos muito interessantes. Por exemplo, aquela pintura 'Cordeiro Sonhando com o Céu Estrelado'; se você olhar para ele por muito tempo, verá que as nuvens se movem lentamente.",
  [822505833480960] = "Você tem alguma pesquisa sobre pintura?",
  [822505833480704] = "Finalmente, há um segredo: <P_Heart> (Voz baixa) </> para verdadeiros indivíduos com Sequência, suas sombras ocasionalmente... não os ouçam direito.",
  [822505833480448] = "Em segundo lugar, preste atenção a quem nunca toca em alimentos específicos. Por exemplo, aqueles que se recusam firmemente a tocar em bife mal passado podem ser 'vampiros'... desculpe, quero dizer, os Sanguíneos.",
  [822505833480192] = "<P_Heart> (Ajustando os punhos com elegância) </> Primeiro, observe a maneira como eles seguram suas taças de vinho - Beyonders de certos caminhos farão gestos simbólicos inconscientemente.",
  [822505833479936] = "Como você identifica Beyonders em um baile?",
  [822505833479680] = "Ao distribuir pão para as crianças do Distrito Leste com minhas próprias mãos, lembro que não sou apenas uma Tecelã de Sonhos, mas Audrey Hall.",
  [822505833479424] = "Inicialmente, isso também contou com a ajuda do Louco. Mais tarde, descobri... <P_Heart> (Olhos gentis) </> esta é uma das melhores âncoras para manter a humanidade.",
  [822505833479168] = "Senhorita Audrey, ouvi dizer que você é a fundadora da Loen Charity Scholarship Foundation. Como você embarcou no caminho da caridade?",
  [822505833478912] = "Haha, você ficou com medo? Você começou a suar frio? Aprendi esse tom com o Sr. Mundo!",
  [822505833478400] = "Portanto, no Mundo Extraordinário, você deve sempre: 'Cuidado com os Espectadores'.",
  [822505833476864] = "Não, tenho muitas identidades no mundo real. Se quiser me encontrar, você pode ir à Loen Charity Foundation. Quanto à psicoterapia, esta é uma habilidade Extraordinária do 'Espectador' Caminho .",
  [822505833476352] = "Em seguida, estenda a mão e o cristal lhe dirá a resposta.",
  [822505833476096] = "Segure este pêndulo e repita silenciosamente a pergunta que deseja fazer ao seu coração...",
  [822505833475840] = "Ocasionalmente, há situações em que você não consegue obter uma resposta. Nessas ocasiões, talvez seja o destino lhe dizendo: 'Você não pode perguntar isso.'",
  [822505833475584] = "Quanto mais forte for a resposta, mais rápido ela gira.",
  [822505833475328] = "O balanço do cristal no sentido horário simboliza afirmação, enquanto o balanço no sentido anti-horário significa o oposto.",
  [822505833475072] = "Corrente de prata e cristal, o balanço aparentemente aleatório é na verdade a resposta que o destino lhe dá.",
  [822505833474816] = "Olá, convidado perdido, gostaria de experimentar o Pendulum Adivinhação ?",
  [822505833474304] = "Jovem, aproveite os bons momentos e caminhe com firmeza.",
  [822505833474048] = "Tento encontrar coisas para fazer sozinho. Depois de varrer o chão durante anos, a poeira sobe e desce. Estranhamente, meu coração se acalmou lentamente.",
  [822505833473792] = "As pessoas da Igreja da Noite Eterna iam e vinham e limparam este lugar completamente. Agora vejam, o corredor de flores é tão lindo, nem um traço deixado para trás.",
  [822505833473536] = "Sim, naquele dia, há alguns anos, este lugar se transformou em ruínas. Acontece que eu estava fora, mas meu único filho não teve tanta sorte...",
  [822505833473280] = "Acidente?",
  [822505833473024] = "É que depois daquele acidente, algumas coisas nunca mais poderiam voltar.",
  [822505833472768] = "Sim, há muitos anos. Os antigos vizinhos foram-se afastando um a um, mas as flores das glicínias florescem cada vez melhor...",
  [822505833472512] = "Você sempre morou aqui?",
  [822505833472256] = "Estou acostumado com isso. Varrer este trecho todos os dias é como exercitar meus ossos, e posso ver esta rua.",
  [822505833472000] = "Obrigado, está muito limpo aqui.",
  [822505833471488] = "Não entendo, não entendo!",
  [822505833471232] = "Amigo, você está agachado aqui, deve ter visto tudo! Me dê uma dica...",
  [822505833470720] = "Ei! Os nomes estão todos embebidos em álcool! Enfim, é aquele tipo de lugar onde você pode resolver problemas, sabe!",
  [822505833470464] = "Hound... O velho Wright, da Hound Tavern, me disse que as pessoas que conseguem fazer as coisas estão escondidas aqui... O que... que esquadrão mercenário?",
  [822505833469952] = "Tudo bem, fique seguro, pequenino. Que a Deusa da Meia Noite proteja você!",
  [822505833469696] = "<P_Heart> (Animado) </> Squeak! Rangido!",
  [822505833469440] = "Uma criatura com espiritualidade ? Você aparecendo aqui, será que a natureza da convergência Característica de Beyonder está em ação...",
  [822505833469184] = "<P_Heart> (Acena com a cabeça) </> Squeak!",
  [822505833468928] = "<P_Heart> (Meu espiritualidade é tocado de repente. Será que esse esquilo não é um animal comum, mas...) </>",
  [822505833468672] = "Pequena, você realmente sabe disso?",
  [822505833468416] = "<P_Heart> (Ele congela por dois segundos, depois levanta solenemente a pata dianteira direita e bate no peito quatro vezes no sentido horário - um esboço simples, mas preciso, do emblema sagrado da Deusa da Noite Eterna.) </>",
  [822505833468160] = "<P_Heart> (O esquilo empurra a mão com alguma resistência.) </>",
  [822505833467904] = "Guincho, guincho! <P_Heart> (Os olhos do esquilo se iluminam e ele levanta as patas dianteiras para desenhar um círculo tortuoso no ar.) </>",
  [822505833467648] = "Coisinha gananciosa, hoje não tem mais, mas voltarei novamente.",
  [822505833467392] = "<P_Heart> (O esquilo pega as migalhas de pão, enfia-as habilmente nas bochechas e depois move as patas dianteiras para cima e para baixo como se estivesse se curvando para expressar gratidão, antes de continuar a olhar para cima com olhos de expectativa.) </>",
  [822505833467136] = "Ainda há algumas migalhas de pão no meu bolso. Coma, pequenino.",
  [822505833466880] = "Que esquilo bem comportado. Você é um residente da natureza ou um convidado perdido?",
  [822505833466624] = "...É quase igual ao número de clientes. Eu me tornarei o barista mais bem-humorado de toda Tingen.",
  [822505833466368] = "Então quantas pessoas conseguiram rir com sucesso?",
  [822505833466112] = "“Trabalhar para o ‘destino’” – o trocadilho é bastante interessante, não é? Venho preparando essa piada desde que me tornei garçom neste café.",
  [822505833465856] = "...Você acabou de contar uma piada?",
  [822505833465600] = "<P_Heart> (Frustrado) </> Bem, acho que realmente sou uma pessoa sem senso de humor.",
  [822505833464832] = "Olá, novo convidado, como você pode ver, estou trabalhando para 'Fate'...",
  [822505833464576] = "Sempre lhe forneceremos café, chá e uma mente tranquila na Red Moon Street. Você está convidado a voltar e descansar.",
  [822505833464320] = "E um guia e investidor perfeito!",
  [822505833464064] = "Lady Justice é uma verdadeira aristocrata – elegante, nobre, bonita, extremamente poderosa e muito generosa...",
  [822505833463808] = "Mas, novamente, todo o Reino Loen é assim. Espero que você não goste de dias chuvosos.",
  [822505833463552] = "Mas acho que deveria ser chamada de 'Cidade Úmida' ou 'Cidade Chuvosa' porque está sempre chovendo aqui.",
  [822505833463296] = "Tingen também é conhecida como a 'Cidade das Universidades'. Desde que o reino implementou os exames de funcionários, o número de pessoas que vivem aqui e que visitam para turismo tem aumentado.",
  [822505833463040] = "Oferecemos diversos cafés, e atualmente recomendamos o café Fermo, que vem do Vale do Pas, no Continente Sul. Claro, se quiser, também temos um delicioso chá preto e um chá gelado doce.",
  [822505833462784] = "A Sra. Susie sugeriu usar 'Fate' como o nome do café porque a pronúncia desta palavra em Loen parece tão calma quanto um suspiro no final de uma canção de ninar. Bem, a perspectiva dela é sempre única.",
  [822505833462528] = "Olá, novo convidado, bem-vindo ao... ah, bem-vindo ao Café 'Fate'!",
  [822505833462272] = "Eu entendo! Eu tenho inspiração! Eu deveria escrever assim!",
  [822505833462016] = "A coisa mais preciosa para a humanidade? Poderia ser...",
  [822505833461760] = "O mal se esconde entre a multidão; adora destruir tudo nos momentos mais alegres, como uma festa...",
  [822505833461504] = "Gehrman chega a uma cidade movimentada cercada por pessoas ocupadas e veio aqui para...",
  [822505833461248] = "As pessoas vivem vidas pacíficas e felizes na aldeia, mas na realidade, uma conspiração bizarra está se formando aqui...",
  [822505833460992] = "Um enorme tesouro está adormecido na antiga vila...",
  [822505833460736] = "Gehrman aparece em uma pacata vila com seu revólver porque há...",
  [822505833460224] = "Você tem razão. {{PlayerName}}, se você fosse Gehrman Sparrow, qual cena escolheria como palco para sua história?",
  [822505833459968] = "Se você realmente não tem ideias, por que não consultar as sugestões de outras pessoas?",
  [822505833459712] = "Sim, o prazo é depois de amanhã... mas não posso escrever nada... não tenho absolutamente nenhuma inspiração...",
  [822505833459456] = "Sinto muito, eu realmente não tenho essa habilidade. Um prazo? Você é um escritor?",
  [822505833459200] = "{{PlayerName}}, você veio na hora certa. Você tem alguma maneira de eliminar aquela coisa miserável chamada prazo?",
  [822505833458944] = "Senhorita Mágica? Você está... bem? Você precisa de alguma ajuda?",
  [822505833458688] = "Talvez você pudesse tomar um copo de Ranzhi puro malte. Também ouvi piratas gostarem desta bebida, embora nunca tenha visto nenhum pirata vivo.",
  [822505833458432] = "Este é Loen; não há especialidades locais como o Zahar de Bayam aqui.",
  [822505833458176] = "Bartender, outro – me dê um Zarhar. Louvado seja Zarhar, os piratas da cerveja mais amam!",
  [822505833457920] = "Obrigado pelo seu feedback! No futuro, carros como este circularão em todas as ruas de Tingen. Nessa altura, as nossas rodas estarão sempre um passo à frente do crime.",
  [822505833457664] = "O que você acha do novo carro da polícia?",
  [822505833457408] = "Por favor, dirija o novo carro da polícia para dar uma volta e nos dê seus valiosos comentários. Tenha cuidado, não bata em nenhum cidadão.",
  [822505833457152] = "Um distintivo policial totalmente novo – um novato! Precisamos de jovens entusiasmados como você, interessados ​​em novas tecnologias!",
  [822505833456896] = "Ouvi dizer que você está procurando pessoas para fazer um test drive. (Mostrando o distintivo da polícia) Eu gostaria de tentar.",
  [822505833456640] = "Este é o modelo mais recente do carro da polícia a vapor. Olha essas linhas do corpo, que suaves! Começa rápido o suficiente para pegar os ladrões mais escorregadios da área das docas.",
  [822505833456384] = "...Como posso saber se o seu contrato é real ou falso! De qualquer forma... de qualquer forma, a dedução foi muito dura... considere-me azarado!",
  [822505833456128] = "Se você tiver dúvidas, podemos pedir a um artesão terceirizado para estimar o preço agora, ou solicitar arbitragem de acordo com a regulamentação. Por favor, entre e veja os recibos. Ficar na rua discutindo números específicos não ajudará a resolver o problema.",
  [822505833455872] = "Eu entendo como você se sente. Que tal isto: entramos e mostrarei todos os recibos originais, seus registros assinados e os contratos de custos, um por um. Blake, lembro que você fez um ótimo trabalho organizando esses itens, certo?",
  [822505833455616] = "Olhar! Até o seu próprio povo disse que é apenas uma 'marca'! Como vale três soli? É assim que a “caridade dos cinco por cento” é conseguida?",
  [822505833455360] = "Senhor, claro que não... Essa marca é realmente bastante profunda e os reparos requerem materiais e tempo...",
  [822505833455104] = "Verificar? As palavras escritas naquele livro parecem aranhas rastejando! Quem sabe como foi escrito na época! Você apenas aposta no fato de que não sabemos ler bem!",
  [822505833454848] = "Boa tarde, Sr. Em relação aos detalhes do desconto, cada item da lista possui um registro de status que você assinou e confirmou no check-in como referência. Podemos verificar juntos novamente.",
  [822505833454592] = "Olha, uma marca do tamanho de uma unha na parede, e você deduz três soli de mim! O gancho da janela está enferrujado, são mais dois soli! Esse chão quebrado já era velho quando me mudei, e agora você me diz que está excessivamente desgastado?!",
  [822505833454336] = "Mentirosos! É tudo mentira! 'Cinco por cento de caridade'? Pfft!",
  [822505833454080] = "Muito, muito obrigado pela sua compreensão! Você é realmente uma pessoa gentil, assim como o lojista! Que a Deusa da Meia Noite proteja você!",
  [822505833453824] = "Tudo bem, respeito sua opinião, vamos parar com esse assunto por aqui.",
  [822505833453568] = "Que a Deusa da Meia Noite proteja você!",
  [822505833453312] = "Então é assim... você também tem suas dificuldades. Por favor, fique tranquilo.",
  [822505833453056] = "Então, por favor, mantenha esse segredo para mim. Por favor!",
  [822505833452800] = "Bem, é porque minha família passou por algumas mudanças e eu tive que sair para ganhar a vida. Mas tenho medo de conhecer essas pessoas ricas, aquelas que iriam a Backlund para assistir aos bailes; eles podem me reconhecer...",
  [822505833452544] = "Isso é porque, porque...",
  [822505833452288] = "Por que não tentar áreas com pessoas mais ricas? As pessoas lá podem estar mais interessadas.",
  [822505833452032] = "Isso pode ser porque venho do Distrito Oeste de Backlund... Desculpe, quero dizer, a educação que recebi pode ser... um pouco diferente... Me desculpe, não sei como dizer isso...",
  [822505833451776] = "Você não parece um professor daqui.",
  [822505833451520] = "Eu sei... então não cobro pela primeira aula. Só quero provar que posso ensinar bem. Tem que haver... tem que haver um começo.",
  [822505833451264] = "Mas a maioria das pessoas por aqui são famílias comuns da classe trabalhadora; Receio que eles não possam pagar aulas de piano.",
  [822505833451008] = "S-sim! O lojista é um bom homem... Ele disse que ter som é melhor que silêncio; para o negócio, e para mim... é melhor.",
  [822505833450752] = "Você dá aulas aqui?",
  [822505833450496] = "Você... precisa de aulas de piano? Meu preço é muito justo.",
  [822505833450240] = "Por favor, afaste-se do barulho do momento e venha para o meu lado.",
  [822505833449984] = "Chegou o momento marcado, meu ouvinte, e também a testemunha desta história.",
  [822505833449728] = "Ahem, ajudar os chefe a cobrar o aluguel é a nossa missão!",
  [822505833449472] = "Ivan não me deixa conversar no horário de trabalho... pare de falar comigo!",
  [822505833449216] = "Ah... hum.",
  [822505833448960] = "Você e a pessoa ao seu lado são gêmeos?",
  [822505833448704] = "Mas sempre que tenho tempo livre, ou quando estou de mau humor, venho aqui sentar. Aí eu posso me acalmar...",
  [822505833448448] = "Eu cresci e as flores ficaram mais exuberantes. Este local virou mercado e não é mais adequado para leitura.",
  [822505833448192] = "Há alguns anos, essas flores de glicínias não eram tão exuberantes como são agora. O sol era a melhor lâmpada de querosene e terminei muitos, muitos livros aqui.",
  [822505833447936] = "O cenário aqui é muito bom. É muito adequado para sentar, tomar uma xícara de chá tranquilamente e ler algumas páginas de um livro...",
  [822505833447680] = "Espero que você traga novas melodias para condensar novamente a Echo Box. Em troca, minha recompensa também será entregue a você através da Echo Box.",
  [822505833447424] = "Quando você se aproxima da fonte desses ecos, as memórias do passado ressoarão com eles, condensando-se em uma Caixa de Eco concreta. Essas notas dispersas escondem o ritmo do próprio destino – os próprios fragmentos de que preciso para compor meu poema.",
  [822505833447168] = "Atualmente estou rastreando os ecos de uma 'bruxa' do passado. Sua sinfonia do destino se despedaçou em três fragmentos, perdidos por Tingen.",
  [822505833446912] = "Amigo, o apartamento dele é famoso; ele nem deixa você abrir muito a torneira! Se você não tem medo de que os clientes nunca mais voltem a comprar seus produtos, vá em frente e anuncie para ele!",
  [822505833446656] = "Você nem mesmo fará um trabalho que exija dizer uma frase a mais? Não há perda de qualquer maneira!",
  [822505833446400] = "Ele perguntou a você também? Aquele velho quer me dispensar com um copo de cerveja barata. Sonhe!",
  [822505833446144] = "Há um quarto disponível na casa do Frank. Ele me pediu para ajudar a promovê-lo ontem e contar a cada cliente que vier comprar algo sobre essa novidade.",
  [822505833445888] = "Então direi apenas que o que estou guardando é... um cinto que se move sozinho?",
  [822505833445632] = "Já posso prever a cena em que o Sr. Franky vem cobrar de você danos mentais.",
  [822505833445376] = "É uma pequena cobra!",
  [822505833445120] = "Suas preferências são únicas... que tipo de animal de estimação é exatamente?",
  [822505833444864] = "Eu até fantasio com meu animal de estimação se transformando em humano... se tornando parte da família...",
  [822505833444608] = "Não, não, não, eu não fico com esses grandalhões; Gosto daqueles bichinhos pequenos e fofos que não fazem barulho.",
  [822505833444352] = "Ha, gatos e cachorros? Nem pense nisso. Ele calculava tudo, desde pêlos de gato e pegadas até “desgaste de móveis” e “taxas de purificação do ar”. Ele até culparia seu animal de estimação pelo bebê chorando no quarto ao lado.",
  [822505833444096] = "Diga-me, o Sr. Frank permitiria que eu tivesse um animal de estimação?",
  [822505833443840] = "...Você merece ser repreendido.",
  [822505833443584] = "O Sr. Frankie abriu minha porta com um chute e me fez jurar à Deusa que não encontraria ninguém para lutar contra o mal no meio da noite novamente. Caramba!",
  [822505833443328] = "Como resultado?",
  [822505833443072] = "Então chamei algumas pessoas conhecidas no apartamento para jogar cartas e, quando o clima melhorou, rugi algumas vezes e, como resultado...",
  [822505833442816] = "Ontem à noite consegui um novo emprego, movendo tijolos no canteiro de obras até meia-noite antes de ir para casa, mas meu coração ainda estava apenas em lutar contra o mal.",
  [822505833442560] = "Tenho pensado em lutar contra o mal todos os dias recentemente. Penso nisso no trabalho e penso nisso enquanto estou deitado no apartamento.",
  [822505833442304] = "Não se preocupe, o que há de errado?",
  [822505833442048] = "Estou acabado! Estou acabado!",
  [822505833441792] = "Suspiro... não alugue a casa do Frankie, vou te apresentar para outras pessoas.",
  [822505833441536] = "Garantimos que ficaremos tão quietos quanto ratos no canto! Saímos para encontrar trabalho antes do amanhecer todos os dias e nunca faremos barulho...",
  [822505833441280] = "Vim do interior para a cidade em busca de trabalho e preciso urgentemente de um lugar para ficar. Você poderia me ajudar a apresentá-lo...",
  [822505833441024] = "Senhor, acabei de ouvi-lo dizer que existe um lugar chamado Frankie Apartment que precisa de inquilinos, certo?",
  [822505833440768] = "Não, não! A cobrança de aluguel já é chata o suficiente, fique longe de mim!",
  [822505833440512] = "Ajudar os chefe a cobrar o aluguel é a nossa missão!",
  [822505833440256] = "Chefe , você precisa de um guarda-costas? Posso ajudá-lo a cobrar o aluguel!",
  [822505833440000] = "... Bem merecido.",
  [822505833439744] = "Frankie manteve minha bagagem como refém e ameaçou que eu não conseguiria alugar nenhuma casa em Tingen.",
  [822505833439488] = "Você também deve dinheiro?",
  [822505833439232] = "Estúpido!",
  [822505833438976] = "Agora olhe! Jude tirou a máscara e está exigindo dívidas dele, e ele ainda acha que o cara é uma boa pessoa!",
  [822505833438720] = "Aquele Kit idiota! Eu disse a ele há muito tempo para não sair com Jude. Esse cara parece um bandido enviado por Frank!",
  [822505833437696] = "Professor, estou fazendo audição na universidade ao lado; Não sou aluno desta turma.",
  [822505833437184] = "Por favor, limpe minha lápide... deixe meu nome claro. Meu último suspiro ficará grudado em você... por favor, em meu nome, complete esse abraço.",
  [822505833436928] = "Ele é meu pai... só quero abraçá-lo mais uma vez, dizer que estou bem e continuar vivendo...",
  [822505833436672] = "Ajude-me... não posso tocá-lo... Depois que o Lobo Dourado morreu, as vozes em minha cabeça finalmente desapareceram.",
  [822505833436416] = "<P_Yellow> Três itens de Roaming </> foram listados em sua barra <P_Yellow> Missão </>, e os detalhes específicos foram anotados para você. Que sua jornada corra bem e que você tenha descobertas.",
  [822505833436160] = "Claro, se você precisar de mais do que apenas “passeios turísticos”, também tenho alguns “roaming” especiais. Afinal, sob os tijolos brilhantes desta cidade, há sempre alguns cantos... que precisam de passos extras para serem medidos.",
  [822505833435904] = "Bom dia, {Sr.{Sra.|}}. Sou Jacob, guia da cidade certificado pela Prefeitura. Posso planejar a rota turística mais eficiente para você e responder a maioria das suas perguntas sobre esta cidade.",
  [822505833435648] = "Você pode sentir isso? Sempre sinto que... ele, meu filho, está bem aqui.",
  [822505833435392] = "Ah? Espere! Que benefícios Frank lhe deu para ajudá-lo assim! Tratei você como um irmão, e é assim que você me trata!",
  [822505833435136] = "Porque eu sou esse ajudante! Apresse-se e pague a taxa de quebra de contrato!",
  [822505833434880] = "Então arrumei minha bagagem durante a noite e me mudei. Vamos ver como ele consegue usar a bengala para bater na porta... Ei, por que você não está falando?",
  [822505833434624] = "Você não sabe o quão mesquinho aquele velho é. Vendo que consegui emprego na fábrica, ele exigiu aumento do aluguel todo mês. Bah! É mais nojento do que comer peixe-lobo enlatado!",
  [822505833434368] = "O que exatamente Frank fez? Você prefere quebrar o contrato e fugir?",
  [822505833434112] = "S-sério? Então eu tenho que correr rapidamente.",
  [822505833433856] = "Aquele cara, Frank, contratou ajudantes para perseguir aqueles que estão com o aluguel atrasado!",
  [822505833433600] = "Para alugar deve-se ainda procurar uma empresa beneficente de melhorias habitacionais... mas eu, mas não tenho dinheiro para tomar as principais vacinas...",
  [822505833433344] = "Ele é louco! Frankie! Mesmo que os canos do apartamento estalem, as paredes estejam úmidas e mofadas e as portas e janelas não fechem bem, desde que isso não afete a vida básica e a cobrança do aluguel, ele nunca vai lidar com isso!",
  [822505833433088] = "Ufa, ainda bem que fui inteligente e corri cedo. Aquele cara, Martin, queria alugar o apartamento de Frankie.",
  [822505833432832] = "Ele disse Apartamento Frankie, nem mesmo um cachorro iria alugá-lo!",
  [813709740095744] = "Senhora...",
  [813709740130560] = "Como assim?",
  [822505833432576] = "Por que ele de repente decidiu não alugá-lo? O que ele disse para você?",
  [813709740047616] = "Por que?",
  [822505833432320] = "Colegas de quarto na beira da estrada realmente não são confiáveis!",
  [822505833432064] = "Levei-o para ver o apartamento pelo qual havia pago um depósito, mas ele xingou a casa e se virou para sair, dizendo que não iria alugá-la.",
  [822505833431808] = "Você não encontrou um colega de quarto na beira da estrada que estava disposto a dividir um apartamento com você? Onde ele está?",
  [822505833431552] = "Vou dormir nas ruas esta noite!",
  [822505833431296] = "Obrigado pela sua bênção.",
  [822505833431040] = "Exatamente. É como se até o vento que sopra por acaso carregasse uma certa... sensação poética de paz. É hora de voltar, que a Deusa lhe conceda uma noite de sono.",
  [822505833430784] = "A atmosfera nesta área é realmente um pouco diferente.",
  [822505833430528] = "<P_Heart> (Se estiver perto de Blackthorn, talvez poderes misteriosos estejam em jogo.) </>",
  [822505833430272] = "Porém, \"A Noite se Aproxima\"... Heh, talvez não seja inteiramente uma coincidência. Sempre fui um crente devoto da Deusa. Se for dito que recebi algum pequeno favor durante a noite no escuro, isso é razoável.",
  [822505833430016] = "Que estranho, este livro parece sempre passar para este capítulo sozinho. Será que acidentalmente danifiquei a coluna durante uma de minhas leituras?",
  [822505833429760] = "<P_Heart> (sussurrando) </> Capítulo Treze, 'A noite se aproxima'...",
  [822505833429504] = "<P_Heart> O vento sopra os livros sobre a mesa, deixando as páginas abertas no início de determinado capítulo. </>",
  [822505833429248] = "Mais uma rodada? Desta vez com certeza vou firmar minha mira.",
  [822505833428992] = "Talvez sejam veteranos ou policiais; Eu os vi também. No entanto, parece haver também alguns jovens. É difícil dizer...",
  [822505833428736] = "Falando nisso, você notou que tem um lugar especial no segundo andar? As pessoas que vão praticar lá têm movimentos muito profissionais.",
  [822505833428480] = "Não mencione isso. Só de pensar em verificar aquelas malditas contas trimestrais com o gerente amanhã dá vontade de puxar o gatilho. Não atirei o suficiente hoje e minhas velhas costas já estão dizendo que estão doentes.",
  [822505833428224] = "No último set, sua terceira tacada ainda foi muito apressada. Respire, Cole, você tem que manter a calma, como antes de beijar uma garota.",
  [822505833427968] = "Mesmo assim, há um sorriso no canto da boca. Ela realmente é uma pessoa como um pequeno sol.",
  [822505833427712] = "No entanto, ela ocasionalmente vem comprar lírios brancos, embrulhando-os silenciosamente. Perguntei uma vez e ela disse: “Vou visitar uma velha amiga que está sempre dormindo”. Ela deve estar indo para o Cemitério Raphael.",
  [822505833427456] = "Ela sempre vem comprar pequenos buquês das flores mais brilhantes, dizendo que quer colocá-los em sua mesa para “deixar os enfadonhos documentos oficiais absorverem um pouco de sol”. Suas palavras são como passarinhos, leves e numerosas; fica feliz só de ouvir.",
  [822505833427200] = "Ela trabalha aqui perto, acho que em uma... empresa de segurança? Sim, Blackthorn.",
  [822505833426944] = "Você conhece Roselle? Ela é nossa cliente mais feliz! Você ouve a voz dela antes de vê-la: 'Bom dia! Você tem flores como o sol hoje?",
  [822505833426688] = "É verdade! Eu cuido deles todos os dias, então sei o que é melhor. Principalmente as rosas; até seus espinhos são mais afiados que outros. A senhorita Roselle, que vem sempre, sempre diz isso também!",
  [822505833426432] = "Bem-vindo! Ah, você também percebeu, né? Nossas flores desabrocham com mais vigor do que em qualquer outro lugar, até as folhas são excepcionalmente verdes, como se alguém estivesse cuidando especialmente delas!",
  [822505833426176] = "Por favor, perdoe minha empolgação, mas testemunhar a genialidade é sempre algo emocionante. Por favor, torça por ele!",
  [822505833425920] = "Você é realmente... muito apaixonado.",
  [822505833425664] = "Observe seu movimento de giro do remo – o raio de respingo é sempre controlado dentro de 15 polegadas. Eu gostaria de chamá-lo de ‘Jeni Ripple’.",
  [822505833425408] = "Olha essa curva! A forma como o grande dorsal se expande quando ele puxa o remo é simplesmente uma obra de arte.",
  [822505833425152] = "O barco da equipe verde é três quilos mais leve que o nosso, mas a frequência de braçada do jovem mestre foi especialmente projetada!",
  [822505833424896] = "Por favor, fique um minuto. Você já viu aquele barco a remo vermelho? O remador número três é o jovem mestre da minha família, Jeni.",
  [822505833424640] = "Você realmente é uma jovem com um olhar perspicaz.",
  [822505833424384] = "Estou disposto a investir em você! Investir na tradição é mais elegante do que investir em ações emergentes.",
  [822505833424128] = "Então, posso perguntar se você está interessado em...",
  [822505833423616] = "Desde 1315, o nome do patrocinador foi acrescentado ao casco. No momento em que cruzarmos a linha de chegada, compartilharemos a honra.",
  [822505833423360] = "As mudanças estão escondidas nos detalhes. Há setenta anos, mudámos para assentos deslizantes e, em 1313, encomendámos o primeiro barco de madeira de freixo branco...",
  [822505833423104] = "Tenho uma pergunta: será que estes barcos esbeltos permaneceram inalterados durante mais de cem anos?",
  [822505833422848] = "Universidade Tingen? Esse é o nosso maior rival!",
  [822505833422592] = "A propósito, meu pai se formou na Universidade de Tingen.",
  [822505833422336] = "Ouvi meu pai mencionar isso. Ele também participou do clube de remo. Ele sempre disse que a alma da universidade está à beira do rio, não na biblioteca.",
  [822505833422080] = "O remo tem uma história de mais de cem anos na Hoy University. As estatísticas mostram que mais da metade dos graduados são qualificados em remo.",
  [822505833421824] = "Afinal, eu não esperava que ele encontrasse um dono adequado; isso é realmente maravilhoso...",
  [822505833421568] = "Parece que há muito tempo que ninguém visita esta terra; os passageiros que vão para lá são bastante raros. Se você estiver indo para lá, sempre poderá me encontrar para embarcar no trem no futuro.",
  [822505833421312] = "{Sr.{Sra.|}}, olá. Para qual estação você gostaria de ir?",
  [822505833421056] = "Você pode encontrar o condutor do trem ali e pegar o trem para o território do castelo.",
  [822505833420800] = "Perdoe-me por ter pressa em sair e não poder acompanhá-lo. Felizmente, há um mordomo que ocasionalmente cuida das coisas. Contanto que você entregue o contrato a ele, isso naturalmente provará sua identidade como proprietário.",
  [822505833420544] = "Este é um contrato de transferência temporário; você só precisa assinar aqui.",
  [822505833420288] = "Que transferência precipitada, mas agradeça à Deusa pela Sua proteção, permitindo que este território tenha um dono adequado.",
  [822505833420032] = "Realmente? Isso seria maravilhoso. <P_Heart> (parecendo um pouco arrependido) </> Esse terreno sempre careceu de manutenção e nenhuma construção formal foi iniciada. Acho que 1000 soli seriam bastante apropriados.",
  [822505833419776] = "Se você achar que é apropriado, talvez eu possa assumir o controle. Por favor, indique um preço justo.",
  [822505833419520] = "Penso que ele também deve esperar ver este território recuperar a sua vitalidade.",
  [822505833419264] = "Eu posso entender muito bem os sentimentos do dono desta terra...",
  [822505833419008] = "Esta saída é muito apressada e não há tempo para encontrar um novo proprietário para este terreno. Temo que isso seja desperdiçado.",
  [822505833418752] = "O jovem mestre ainda tem um território preferido em Tingen, que pretendia usar para construir um pequeno castelo. É uma pena que a construção nunca tenha começado.",
  [822505833418496] = "Servi o jovem mestre por muito tempo. Ele é o filho mais novo da Família e sempre quer fugir do abrigo da Família e se aventurar por conta própria. Há alguns anos, acompanhei-o a Tingen. Infelizmente...",
  [822505833418240] = "Sim, este {Sr.{Sra.|}}. Estou prestes a voltar para Backlund com o jovem mestre...",
  [822505833417984] = "Olhando para a bagagem que você arrumou, parece que você está saindo de Tingen? Você parece um pouco relutante.",
  [822505833417728] = "Embora eu não saiba o que aconteceu, eu estava apenas me escondendo no banheiro para evitar que rissem de qualquer maneira. Deixe-me ficar aqui por enquanto; deixe-me ser minha própria piada.",
  [822505833417472] = "Senhor, por que você ficou olhando o jornal o tempo todo?",
  [822505833417216] = "Se possível, espero que você não fale sobre essa experiência...",
  [822505833416960] = "Senhor, sinto muito, isso foi um acidente.",
  [822505833416192] = "Basta pagar uma ou duas semanas de juros, cerca de duzentas ou trezentas libras, para obter 10% das ações da empresa de bicicletas.",
  [822505833415936] = "Primeiro, penhor minhas ações da empresa de transporte ao banco por um curto prazo, obter um empréstimo para comprar ações de bicicletas, depois penhorar as ações de bicicletas ao banco e usar o empréstimo para pagar o empréstimo anterior.",
  [822505833414656] = "Na verdade, esta é também a revelação do Sr. Louco; Ele é sempre tão atencioso. Talvez... porque nunca me faltou dinheiro, sempre esqueço o quão importante o dinheiro é para um novo Beyonder .",
  [822505833414400] = "De nada, afinal você precisa de 'capital inicial'.",
  [822505833413888] = "Quanto mais alto Sequência , mais próximo você estará do abismo da divindade e mais difícil será sentir a felicidade comum trazida pela comida. Enquanto você ainda está curioso sobre tudo, vá provar esses doces.",
  [822505833413632] = "Ah, certo! E tem torta Disi. O Sr. Louco já gostou de torta Disi com chá gelado doce; você pode tentar isso também.",
  [822505833413376] = "Se você for para Backlund, haverá mais opções. O pudim de frutas com caramelo, os biscoitos amanteigados com manteiga e o bolo de cenoura do Restaurante Laporte são todos muito bons.",
  [822505833413120] = "Em Tingen gosto muito do bolo de limão da Slin Bakery, e também gosto do “Milky Cocoa Sweet Tea” do Fate Cafe, que é uma criação original da proprietária, Sra.",
  [822505833412864] = "Senhorita Audrey, o que você mais gosta de comer? Você tem alguma recomendação?",
  [822505833412608] = "Ele raramente sai e prefere ficar em casa. No entanto, ele ocasionalmente é voluntário na Igreja da Colheita da Mãe Terra, talvez você possa encontrá-lo lá.",
  [822505833412352] = "(Ele ficou com raiva num acesso de raiva... Estou realmente ansioso para conhecer o Sr. Moon!)",
  [822505833412096] = "Se for o Sr. Moon, ele pode ficar muito bravo quando ouvir você dizer vampiro, e então dizer que está muito bravo, mas provavelmente não fará mais nada.",
  [822505833411840] = "O Clube do Tarô realmente tem um vampiro... um sanguíneo?! Mas como o Sr. Moon é membro do Clube do Tarô , ele não deveria fazer nada fora da linha, certo?",
  [822505833411584] = "Sanguíneo. Se você conhecer o Sr. Moon do Clube do Tarô , você não deve mencionar a palavra vampiro.",
  [822505833411328] = "Eles realmente existem! Então como devo chamá-los?",
  [822505833411072] = "A maioria dos lobisomens é perigosa e, quanto aos vampiros, eles não gostam de ser chamados de vampiros.",
  [822505833410816] = "Sra. Audrey, ouvi dizer que existem lobisomens e vampiros no Mundo Extraordinário?",
  [822505833410560] = "Ok, vou me lembrar disso, elegante Sra. Susie.",
  [822505833410304] = "Eu sou uma senhora de Sequência 5 anos agora!",
  [822505833409280] = "Susie era originalmente uma Golden Retriever com linhagem não tão pura; ela foi um presente grátis quando meu pai comprou um Foxhound. Mas ela é minha família agora, minha assistente.",
  [822505833408768] = "É uma pena não ter conseguido encontrar a localização específica de “Londres” no mapa; pode ser uma pequena cidade desconhecida. Acho que também é uma cidade de esperança que está sempre chovendo.",
  [822505833408512] = "A capital de Loen é Backlund, que as pessoas chamam de a grande “Cidade das Cidades”. Certa vez ouvi um Beyonder que afirmava ser conterrâneo do Imperador Roselle dizer que Backlund é muito parecido com \"Londres\".",
  [822505833408256] = "Loen é uma potência industrial localizada no Continente Norte. Faz fronteira com a República Intis a oeste com Midseashire e a Cordilheira Hornacis, faz fronteira com o Império Feysac ao norte, é adjacente ao Mar Sonia a leste e à Baía Disi ao sul.",
  [822505833408000] = "A história apresenta verdades diferentes devido às diferentes perspectivas das pessoas. Posso falar primeiro sobre a geografia e o clima de Loen.",
  [822505833407744] = "Dona Audrey, eu sei que você é uma nobre, deve saber muito sobre a história de Loen, certo?",
  [822505833406720] = "Sim, o Rei das Amarelas e das Pretas aponta para o Sr.",
  [822505833406208] = "Na verdade, apenas os Deuses Verdadeiros podem usar nomes honoríficos de três partes. Meu nome honorífico e os de outros Clube do Tarô membros tomam emprestado o status de Deus Verdadeiro do Sr.",
  [822505833405440] = "<P_Heart> (Ele realmente sabe se gabar...) </>",
  [822505833405184] = "Quer um pedaço? Apenas 20 centavos!",
  [822505833404928] = "Olha, esses repolhos na minha frente, embora aparentemente simples, escondem Beyonder poderes que você nunca conheceu. Foi só depois de comê-los que ganhei o poder do equilíbrio!",
  [822505833146624] = "Nada, adeus.",
  [822505833404160] = "Uau, isso é realmente... impressionante.",
  [822505833403904] = "Você deve saber que consigo manter o equilíbrio em um barril de madeira colocado horizontalmente.",
  [822505833403648] = "Você entende, certo? Os esquisitos sempre têm algumas peculiaridades estranhas, como uma obsessão fanática por bonecas ou algo assim...",
  [822505833403392] = "Suspiro, a economia está ruim agora. Pelo contrário, lugares onde esquisitos se reúnem assim podem atrair muitos clientes...",
  [822505833403136] = "Por que você está vendendo bonecas no Mercado Subterrâneo?",
  [822505833402880] = "Como eu poderia! Você precisa de uma boneca personalizada? Eu me tranquei para vivenciar a psicologia do produto.",
  [822505833402624] = "Impressionante. Você vai realizar esse ato agora?",
  [822505833402368] = "{Sr.{Sra.|}}, eu costumava ser um mágico, hábil em escapar de jaulas na frente dos olhos de todos.",
  [822505833402112] = "Então os clientes estão aqui apenas para te ajudar a consumir sua cota de cerveja!",
  [822505833401856] = "Já comprei cerveja para um ano; coisas boas são feitas para serem compartilhadas!",
  [822505833401600] = "Tosse tosse, não. Para ser sincero, meu fígado não está muito bom, não deveria mais beber cerveja, mas afinal, faço negócios no Evil Dragon Bar...",
  [822505833401344] = "Qual é a conexão entre os dois?",
  [822505833401088] = "Vendo que você é uma cara nova, se você comprar um livro agora, pagarei do meu próprio bolso para lhe oferecer uma cerveja preta.",
  [822505833400832] = "Mesmo que não o faça, posso ajudá-lo a caçá-lo.",
  [822505833400576] = "Você tem todos os livros?",
  [822505833400320] = "Olá, eu sou José. Joseph sou eu e sou livreiro no Mercado Subterrâneo. Os livros que você quiser, eu encontrarei para você.",
  [822505833400064] = "<P_Heart> (Ele foi definitivamente enganado por um comerciante sem escrúpulos!) </>",
  [822505833399808] = "Como você pode ver, tenho algumas velas na minha frente e estou prestes a acendê-las com a mente!",
  [822505833399552] = "Então você é?",
  [822505833399296] = "Acabei de comer um pedaço de repolho misterioso e senti meu corpo cheio de um poder oculto.",
  [822505833398528] = "Ele nunca dorme, por isso é chamado de 'Não consigo dormir'.",
  [822505833398272] = "Deixe-me adivinhar o nome!",
  [822505833398016] = "Geralmente gosta de chorar e correr, mordendo e mastigando coisas. Você pode dizer pela sua aparência que...",
  [822505833397760] = "Quanto a essa criança, suspiro, isso realmente não me dá paz.",
  [822505833397504] = "Como ele corre tão devagar, vamos chamá-lo de 'Não consigo correr rápido'!",
  [822505833397248] = "Então qual é o seu nome?",
  [822505833396992] = "Embora esta criança pareça animada, na verdade ela corre muito devagar, e é por isso que se senta na cadeira e se recusa a se mover.",
  [822505833396736] = "Parece que não está muito satisfeito com o seu nome.",
  [822505833396480] = "Miau—miau—",
  [822505833396224] = "Esta criança se chama 'Can't Get Enough'. Olha essas listras laranja-avermelhadas, não são rechonchudas e lindas?",
  [822505833395968] = "Vá perguntar por aí, este é o Mercado Subterrâneo! Não é um bazar de bebês!",
  [822505833395712] = "Deixa eu ver... Tratamento eficaz para doenças do ouvido?!",
  [822505833395456] = "Senhor, tenho aqui uma fórmula de ervas que é muito adequada para você, por favor, certifique-se de tomá-la.",
  [822505833395200] = "Uh, mas eu só queria comprar uma mochila de babuíno...",
  [822505833394944] = "Isso mesmo, aquele dono da barraca foi levado pela filha para curtir a vida, e a barraca junto com três gatos foram transferidos para mim.",
  [822505833394688] = "Uh, por que eu me lembro que esse lugar costumava ser uma barraca de mochilas de babuínos de cabelo encaracolado?",
  [822505833394432] = "Ei, quer algumas fórmulas misteriosas? Desde equipamentos experimentais até prescrições, temos de tudo.",
  [822505833394176] = "...Só vou apostar um pouquinho de dinheiro, só um pouquinho, com certeza não vai afetar minha vida, hehe.",
  [822505833393920] = "Se eu fosse como eles, teria caído na armadilha!",
  [822505833393664] = "Olhe para essas pessoas barulhentas, tolamente entregando o pouco dinheiro que lhes resta, pensando que podem ganhar muito dinheiro!",
  [822505833393408] = "Eu absolutamente não quebrarei meu juramento por causa de uma luta de boxe maravilhosa...",
  [822505833393152] = "Tempestade acima, jurei aos meus amigos e familiares que vou parar de jogar...",
  [822505833392896] = "Branco e gordinho, parece que está se cuidando muito bem.",
  [822505833392640] = "Há mais alguma coisa que você gostaria de saber?",
  [822505833392384] = "Espero que a Deusa possa ouvir.",
  [822505833392128] = "A letra desta música foi selecionada de 'Revelations of the Night' e nós reescrevemos a melodia.",
  [822505833391872] = "Durante a Missa da Lua, rezamos pelos mortos e abençoamos os vivos. Que a Deusa proteja Seus crentes e que todos encontrem a paz.",
  [822505833391616] = "A Evernight Goddess Church não tem muitos festivais. O mais importante é o Festival de Inverno, seguido da Missa da Lua durante a lua cheia.",
  [822505833391360] = "Olá, senhor. Estamos ensaiando o Hino da Meia Noite, nos preparando para oferecê-lo à Deusa na próxima Missa Lunar.",
  [822505833391104] = "Crianças, mais alto, um pouco mais alto, deixem a Deusa ouvir o seu canto...",
  [822505833390848] = "Então me ajude a limpar a barraca.",
  [822505833390592] = "Eu, eu não sou um mendigo!",
  [822505833390336] = "Tsk... leve essas sobras de carne de graça.",
  [822505833390080] = "Só estou olhando... Mamãe tossiu de novo ontem à noite e disse, disse que queria tomar sopa de carne...",
  [822505833389824] = "Afaste-se, garoto! Cuidado, ou minha faca pode cortar você!",
  [822505833389568] = "Tanta fome... só posso comer pão preto hoje? Eu quero comer carne.",
  [822505833389312] = "Bom gato!",
  [822505833389056] = "Ficar de pé!",
  [822505833388800] = "Tão inteligente!",
  [822505833388288] = "Este gato parece estar sorrindo. Poderia entender comandos humanos?",
  [822505833388032] = "Eu sou um morador de rua... meu gato não é um gato de rua...",
  [822505833387776] = "Já está configurado? Muito obrigado, deixe-me verificar.",
  [822505833386496] = "Que item você pretende colocar no canto norte da configuração ritual do aluno?",
  [822505833385216] = "Que item você pretende colocar no canto sudeste da configuração ritual do aluno?",
  [822505833384960] = "Você coloca o capacete nele. <P_Heart> (Item perdido—Capacete) </>",
  [822505833384704] = "Você coloca a peça de xadrez nele. <P_Heart> (Item perdido - peça de xadrez) </>",
  [822505833384448] = "Você coloca a boneca nele. <P_Heart> (Item perdido - Boneca) </>",
  [822505833384192] = "Você coloca o sapo nele. <P_Heart> (Item perdido - Sapo) </>",
  [822505833383936] = "Que item você pretende colocar no canto oeste da configuração ritual do aluno?",
  [822505833383680] = "Entendido, vou dar uma lição àqueles pirralhos imprudentes agora mesmo.",
  [822505833383424] = "Onde esses pirralhos problemáticos se esconderam? Depois de pegá-los, garantirei que aprendam algumas coisas sobre regras!",
  [822505833383168] = "(Parece que não preciso me preocupar muito com ele.)",
  [822505833382912] = "Vou encontrar a pequena Alice e chorar bem com ela...",
  [822505833382656] = "Wuu wuu... wuu wuu, nunca esperei que Lena fosse assim...",
  [822505833382400] = "Agora é a sua vez. Para o futuro de Tingen, comece uma grande limpeza!",
  [822505833382144] = "Aqueles pedestres vagando pelas ruas são todos encarnações do desejo – então sinta-se à vontade para fazer tudo! Vire tudo de cabeça para baixo e use meios violentos e malucos para manter esta ordem frágil!",
  [822505833381888] = "Ouça, \"Sinful Tingen\" é o lado negro da cidade, uma manifestação da bagunça que todos mantêm guardados dentro de si. Não parece um esgoto que não consegue ver a luz?",
  [822505833381632] = "Obrigado pela sua gentileza, que a Deusa o proteja!",
  [822505833381376] = "Só estou dizendo olá, policial.",
  [822505833381120] = "{Sr.{Sra.|}}, há algo em que eu possa ajudá-lo?",
  [822505833380864] = "Ah, entendido, entendido! O evento dura o mês todo, fique à vontade para experimentá-lo a qualquer hora! O amarelo é resistente, o azul é rápido, o marrom é silencioso!",
  [822505833380608] = "Não, estou com pressa.",
  [822505833380352] = "{Sr.{Sra.|}}, gostaria de experimentar nosso projeto de conveniência municipal este mês? A avaliação é gratuita durante o período promocional; depois disso, você só precisa inserir 1 centavo na 'Caixa de Oferendas' para desbloquear uma. Devo apresentar esses três modelos para vocês?",
  [822505833380096] = "Não, nobre, senhora... esta maçã, esta maçã... preciso praticar!",
  [822505833379840] = "“Nobre senhora, esta maçã é tão rosada quanto suas bochechas! Por favor, aceite, apenas dois centavos!”",
  [822505833379584] = "Esses cavalheiros podem desprezá-los, mas as damas em vestidos de seda às vezes têm corações moles. Cassie, ensine-o novamente.",
  [822505833379328] = "Mas, mas só trouxemos tabaco, jornais e tortas de abóbora. E se eles não gostarem das minhas coisas...",
  [822505833379072] = "Escute, hoje só fazemos negócios em vagões de segunda classe. Os senhores e senhoras de lá não são ricos, mas não pagam com notas falsas.",
  [822505833378560] = "...Se um ente querido em seu leito de morte esgotasse sua paciência, sua vida e até mesmo seu amor, como você o trataria?",
  [822505833378048] = "Desde que seja um lugar com muito sol, só quero passar o resto da minha vida com tranquilidade e conforto.",
  [822505833377792] = "É raro compartilharmos o mesmo sentimento, Velho Tom. Talvez possamos ir para uma cidade ainda mais longe e mais confortável no futuro.",
  [822505833377536] = "Só de pensar em me estabelecer em uma cidade tão linda... Hehe, meu velho coração recuperou a vitalidade.",
  [822505833377280] = "<P_Heart> (Eles parecem pensar que sou um policial. Não há razão para provocá-los por enquanto.) </>",
  [822505833377024] = "Suspiro, alguns rostos desconhecidos dos distritos externos têm vagado pelas proximidades recentemente. Eu estava pensando em denunciar isso à delegacia esses dias... Neste mundo, ainda temos que contar com pessoas justas como você!",
  [822505833376768] = "Obrigado pelo seu trabalho duro, oficial! Um pequeno empresário como eu depende da boa ordem pública para ganhar a vida. Se precisar de alguma coisa, é só me avisar!",
  [822505833376512] = "Grande tiro, suas pernas parecem tão boas.",
  [822505833376256] = "Olá, camarada.",
  [822505833375744] = "<P_Heart> (Na beira da estrada, perto de uma carruagem alugada, as vozes de passageiros do sexo masculino e feminino podem ser ouvidas fracamente.) </>",
  [822505833375488] = "Hmm... nesse caso... Bartender, verifique, por favor!",
  [822505833375232] = "Eu vou ser uma estrela!",
  [822505833374976] = "Se me virem, talvez se apaixonem pela minha dança e me levem para longe desta pequena cidade para ser uma estrela da música e da dança em Backlund!",
  [822505833374720] = "Porque eu quero me tornar famoso, {{Sr.|Sra.}}. Estou esperando uma carruagem de Backlund cheia de figurões! Estou esperando que eles olhem para mim!",
  [822505833374464] = "Ah, olá! Sinto muito, não posso parar para falar com você agora. O trem está chegando e preciso continuar pulando!",
  [822505833374208] = "Amarre-o a um balão e voe até o topo desta estátua! O que? Você me pergunta se é perigoso? Um Palhaço está sempre acompanhado de perigo! Caso contrário, como eu poderia fazer você cair na gargalhada?",
  [822505833373952] = "Num momento tão maravilhoso, talvez possamos conversar sobre alguns assuntos alegres. Como seu psiquiatra, você pode falar livremente na minha frente.",
  [822505833373696] = "Há poucos dias, um mordomo muito bem vestido veio buscá-lo. Provavelmente foi recolhido por alguma pessoa rica.",
  [822505833373440] = "Eh, eu lembro que tinha uma panela aqui. Para onde foi?",
  [822505833373184] = "Está aqui desde que me matriculei. Parece pertencer a algum idoso; Não sei se ele se formou com sucesso.",
  [822505833372928] = "Este é um projeto final de um aluno da Igreja do Vapor e das Máquinas?",
  [822505833372672] = "Por que há uma panela aqui?",
  [822505833372416] = "Venha, venha, aqui está sua taxa de serviço, e isto... é um tempero que fiz usando a mesma receita. Polvilhe um pouco quando estiver assando carne; é absolutamente delicioso!",
  [822505833371904] = "Muito sucesso. Tenho uma cauda longa e agitada atrás de mim – é pura felicidade!",
  [822505833371392] = "Ninguém os esquecerá; eles guardavam Tingen.",
  [822505833371136] = "Ela também se sacrificou para proteger Tingen. Que ela encontre o sono sob a proteção da Deusa da Noite Eterna.",
  [822505833370880] = "Ela era uma senhora muito alegre e de espírito livre que também adorava brincar. Ouvi dizer que ela tinha um filho fofo.",
  [822505833370624] = "Dona Carol era a capitã antes do último. O capitão Dunn e a Sra. Daly a conheciam muito bem.",
  [822505833370368] = "Ela finalmente avançou para Sequência 5 e se sacrificou na caça a um traidor.",
  [822505833370112] = "Gostei muito das piadas exageradas e constrangedoras da Sra. Daly. Todos nós sentimos falta dela depois que ela foi transferida para a Diocese de Backlund.",
  [822505833369856] = "A Sra. Daly era um gênio Beyonder que avançou para Sequência 7 em apenas dois anos.",
  [822505833369600] = "Hmm... ele também era um pouco estúpido, mas isso só incomodava a Sra. Daly.",
  [822505833369344] = "Ele se importava profundamente com os membros de sua equipe. Sua única falha era que sua memória não era muito boa; seu ditado mais frequente era: 'Espere, tem mais uma coisa'.",
  [822505833369088] = "O capitão Dunn foi o capitão anterior do time Tingen Vigias Noturnos. Ele tinha uma personalidade muito gentil e também era um experiente Beyonder.",
  [822505833368832] = "Para a segurança das pessoas comuns, a verdade sobre Beyonder incidentes não pode ser tornada pública, mas ainda espero que mais pessoas conheçam as suas histórias.",
  [822505833368576] = "Esse Lake Spirit... está tentando abrir uma loja de departamentos?!",
  [822505833368320] = "Ele simplesmente adora essas coisas! Uma vez dado, não gritará no meio da noite. Se você realmente não consegue juntar nada, jogar algumas pedras e tábuas de madeira quebradas também funciona.",
  [822505833368064] = "Uh, bacias de ferro quebradas, cestos de madeira, garrafas de vidro quebradas, latas, esse tipo de coisa?",
  [822505833367808] = "Após o ritual, alguma existência desconhecida fez uma promessa para você? O que exatamente... você está usando para o sacrifício?",
  [822505833367552] = "...Devo confirmar, que mal o Espírito do Lago causa? Isso prejudicou seu corpo ou mente?",
  [822505833367296] = "Ei, isso não é nada raro! Estamos fazendo um sacrifício ao Espírito do Lago do Lago Dourado Outono. Tem um temperamento muito estranho, espero que a oferenda o mantenha quieto por um tempo.",
  [822505833367040] = "...Em plena luz do dia, isso é algo que pode ser dito diretamente!",
  [822505833366784] = "Tenha cuidado, o Ritual de Sacrifício ainda não terminou!",
  [822505833366528] = "Que estranho. Quem construiria uma casa em arco na água?",
  [822505833366272] = "Uma pilha de ruínas está espalhada pela água, com tábuas de madeira e entulho amontoados em uma bagunça, embora o contorno original em arco ainda possa ser vagamente discernido.",
  [822505833366016] = "Boa tarde. Há algo que eu possa fazer por você?",
  [822505833146880] = "Sujeitos, essa situação é muito urgente, e preciso da ajuda de todos. Ministro da Inteligência Militar, explique primeiro a situação.",
  [822505833365248] = "Vejo que você tem um rosto gentil, faça-me um favor como amigo. Pegue uma sacola, ande por aí e me ajude a verificar se todos os gatos do mundo são tão gananciosos? Tenho a sensação de que isso se tornará um bom negócio!",
  [822505833364992] = "Olha só, todos os gatos do cais foram atraídos por mim para cá, não posso afastá-los!",
  [822505833364736] = "Suspiro, é tudo porque minhas habilidades são muito boas! Pesquisei uma nova forma de fazer peixe seco há alguns dias, com a intenção de beber junto, mas o aroma cutucou um ninho de vespas!",
  [822505833364480] = "Isso mesmo! No final, meu gatinho... arrebatou-o e de repente... tudo desapareceu...",
  [822505833364224] = "Você... escondeu tudo num peixe salgado?!",
  [822505833363968] = "Não é uma questão de companhia... Escondi todo o meu dinheiro particular da tosquia de ovelhas no peixe salgado!",
  [822505833363712] = "Eles devem ter te feito companhia por muito tempo... anime-se!",
  [822505833363456] = "Se não consigo encontrá-los, não quero mais viver...",
  [822505833363200] = "Meu peixe salgado... meu gato... para onde eles fugiram...",
  [822505833362944] = "Hmph, espero que seja apenas um boato. Eu não quero verificar isso.",
  [822505833362688] = "Não só isso, ocasionalmente as pessoas dizem que grita... provavelmente é apenas um boato.",
  [822505833362432] = "Ah? Por que está aí... Eu me lembro, muitas coisas semelhantes aconteceram naquele lugar.",
  [822505833362176] = "Você já ouviu falar? Tem gente que fala que o espantalho ali dá voltas e mais voltas, olha, ali mesmo.",
  [822505833361920] = "Esse trem veio de Backlund, está cheio de coisas, com certeza podemos desenterrar algo interessante!",
  [822505833361664] = "Tem de tudo, alianças de casamento, fotos privadas de figurões... até um pedaço da inteligência de Feynapotter!",
  [822505833361408] = "Ha, um invólucro de 1350! Gosto dessa sensação de garimpar ouro!",
  [822505833361152] = "Procuramos coisas deixadas cair pelos passageiros. Cada vez que o trem passa, alguns pequenos gadgets interessantes são jogados pelas janelas!",
  [822505833360896] = "Parece que este babuíno está muito interessado em coisas chamativas...",
  [822505833360640] = "E minhas flores! Estranho, ele nem toca nos sanduíches, só gosta dessas lindas decorações.",
  [822505833360384] = "Guincho, guincho, guincho! Rangido-",
  [822505833360128] = "Abaixe-se! Devolva-me meu chapéu e minha toalha de piquenique!",
  [822505833359872] = "Tenho reunião de grupo semana que vem, com certeza serei elogiado pelo meu mentor, hehe! Parece que não preciso adiar a formatura este ano!",
  [822505833359616] = "Esse é um ponto de inovação... Tenho que me apressar com a pesquisa e descobrir por que as lavouras aqui crescem tão rápido.",
  [822505833359360] = "Você notou? As uvas em Golden Autumn Town estão crescendo rapidamente, quase como uma máquina a vapor com turboalimentador!",
  [822505833359104] = "Tenho que encontrar sua pesquisa, caso contrário ninguém saberá o que ele realmente encontrou.",
  [822505833358592] = "A pessoa inteira é como... um toco de árvore que está enraizando-se loucamente.",
  [822505833358336] = "...Existem algumas coisas extraordinárias neste mundo. O professor é uma pessoa meticulosa, mas quando o vi pela última vez, os pelos e as unhas do corpo já estavam arrastando pelo chão.",
  [822505833358080] = "O nome dele é Porn, professor do Loen Agricultural College. Ele veio fazer pesquisas há meio ano e agora desapareceu junto com seus materiais.",
  [822505833357824] = "Com licença... você viu uma pessoa com cabelo muito comprido perto da treliça?",
  [822505833357568] = "Que gente pequena? Você já é constrangedor o suficiente, ainda bem que estou aqui... mas esse vinho é tão forte assim?",
  [822505833357312] = "Gente pequena... haha, tanta gente pequena...",
  [822505833357056] = "Ei, acorde! Você estudou na Wine Academy por quatro anos, como caiu depois de apenas dois goles!",
  [822505833356800] = "Prove...pensei nisso, vem.",
  [822505833356544] = "Coma, surpresa... hehe, 10 soli, por peça.",
  [822505833356288] = "Uvas, diferentes, gosto?",
  [822505833356032] = "A lã é cortada? Não foi arrancado?",
  [822505833355776] = "Se você gosta tanto de ovelhas, venha até minha casa tosar lã! A lã desse cara precisa ser tosquiada duas vezes por semana...",
  [822505833355520] = "Esta é a primeira vez que vejo uma ovelha... não esperava que fosse tão macia.",
  [822505833355264] = "...Esses caras estão envenenando as abóboras!",
  [822505833355008] = "Hahaha, Charlie vai terminar agora.",
  [822505833354752] = "Aqui, o maior. Mas temos que acrescentar mais esta noite para garantir que quando outros o comprarem em casa e o provarem, eles “terão uma situação”.",
  [822505833354496] = "Em qual abóbora você colocou o laxante? É melhor que ninguém descubra que mexemos nele...",
  [822505833354240] = "Nossa, esse rio parece esconder muitos segredos...",
  [822505833353984] = "Não apenas cascos de tartaruga, também vejo alguns pilares de pedra e madeira quebrada. Parece que havia uma casa aqui!",
  [822505833353728] = "Ah! Outro pedaço de casco de tartaruga quebrado. Poderia haver uma tartaruga muito grande morando aqui!",
  [822505833353472] = "Parece haver algumas coisas estranhas neste rio... vou pescá-las e ver...",
  [822505833353216] = "(Parece que ela está imersa na criação, é melhor não perturbá-la por enquanto.)",
  [822505833352960] = "(Sussurrando alguma coisa...)",
  [822505833352448] = "Olá, você gostaria de um buquê de flores?",
  [822505833352192] = "Então o que tudo isso trará para esses olhares?",
  [822505833351936] = "Quanto mais poderoso você for, mais atenção deverá receber? Boa ideia.",
  [822505833351680] = "Mas não basta, este vasto mundo em si é uma lenda...",
  [822505833351424] = "Faz sentido, figurões deveriam existir em um mundo que é vasto o suficiente.",
  [822505833351168] = "Mas o que fez com que esse lazer mudasse?",
  [822505833350912] = "Dar um pouco de impacto a estes dias de lazer é bastante interessante.",
  [822505833349888] = "Então {{PlayerName}}, se você fosse Gehrman, aquele Gehrman, em que tipo de lugar você gostaria de causar problemas?",
  [822505833349632] = "Se você não tem ideias, por que não pedir a opinião dos outros?",
  [822505833349376] = "Brincadeira, estou preso em um gargalo com meu romance serializado. Senhor Gehrman, cujo nome me deixa com os cabelos em pé, não consigo nem explicar por que ele se aventura...",
  [822505833349120] = "Hm... {{PlayerName}}, quando você veio? Bebendo? Meu prazer.",
  [822505833348864] = "Não consigo escrever... Não tenho nenhuma inspiração... Como exatamente um aventureiro maluco deveria ser escrito para ser maluco o suficiente?",
  [822505833348608] = "Se beber pudesse ajudá-lo a encontrar inspiração, você já seria um gigante literário. Acalme-se por um momento.",
  [822505833348352] = "Barman... outro Martini...",
  [822505833347328] = "Começar a batalha?",
  [822505833347072] = "Por que você deve matar todos eles? Você não obteve o suficiente?",
  [822505833346816] = "Coloquei as coisas em um cofre em xxx, e tudo o que você quer saber está lá dentro.",
  [822505833346560] = "Que tal isso, se você estiver disposto a me deixar ir, eu lhe contarei o segredo de xxx.",
  [822505833346304] = "Não me persiga mais, tenho um motivo pelo qual devo aceitar.",
  [822505833345536] = "Expressando minha gratidão a você novamente!",
  [822505833345280] = "É uma sorte que exista alguém mais elegante do que eles, caso contrário teriam discutido na porta o dia todo.",
  [822505833345024] = "Eles podem estar de mãos dadas e rir em um segundo e começar a puxar o cabelo um do outro no próximo!",
  [822505833344768] = "Muito obrigado, {{Sr.|Sra.}}. Os membros da Tingen Fashion Association são realmente os convidados mais difíceis de receber nesta rua!",
  [822505833344512] = "...Vou comprar mais joias para ficar na moda!",
  [822505833344256] = "Obrigado pelo elogio, mas primeiro vamos liberar a entrada da loja.",
  [822505833344000] = "Você deveria obter um título superior ao deles, que tal 'Fashion Duke'?",
  [822505833343744] = "Eu acho que o senso de estilo desse {{Sr.|Sra.}} não é ruim. Se você está pensando em ingressar na Tingen Fashion Association...",
  [822505833343488] = "Impossível! Como poderia haver alguém em Tingen que entendesse de moda melhor do que eu!",
  [822505833342976] = "Em Tingen, você pode realmente se divertir muito todos os dias.",
  [822505833342208] = "(Sussurrando) Você pode me encontrar sozinho, o senso estético deles é terrível!",
  [822505833341952] = "Nada mal, bem-vindo para nos encontrar para trocar conhecimentos de moda na próxima vez.",
  [822505833341696] = "Vou recomendá-lo à Tingen Fashion Association na próxima vez.",
  [822505833341440] = "E-eu só posso dizer que você mal tem algum senso estético! Da próxima vez, definitivamente não vou deixar você ganhar!",
  [822505833341184] = "Mas você é realmente um bom {{cavalheiro | senhora}}, gostaria de ser meu 76º amante?",
  [822505833340928] = "Ainda não quero reconhecer seu gosto fashion.",
  [822505833340672] = "Não queremos apresentá-lo à Tingen Fashion Association até que você prove que está na moda o suficiente.",
  [822505833340416] = "{{Sr.|Sra.}}, quem você acha que está mais na moda entre nós?",
  [822505833340160] = "Senhora, suas palavras parecem ter outro significado.",
  [822505833339904] = "Coitadinha...",
  [822505833339648] = "Mas as portas da Fashion Association só estão abertas para quem está na moda, e você...",
  [822505833339392] = "{{Sr.|Sra.}}, eu adoraria apresentar nossa associação a você...",
  [822505833339136] = "Você acha que todas as lojas podem obter a aprovação da Tingen Fashion Association?",
  [822505833338880] = "Que problema? Com a nossa chegada, esta joalheria deverá se sentir honrada!",
  [822505833338624] = "Senhoras, ter uma discussão tão intensa logo na entrada da loja pode causar problemas para o dono.",
  [822505833338368] = "Oh, espere, de onde veio essa pobre coisinha? Olha a sua roupa...",
  [822505833338112] = "O que você está fazendo! Você não vê que estamos tendo uma discussão acalorada sobre moda?",
  [822505833337856] = "Senhoras...",
  [822505833337600] = "Eba, eu tenho namorado!",
  [822505833337344] = "Se você precisa sentar aqui, por favor, prove isso para nós.",
  [822505833337088] = "Sinto muito, deixar você sentar aqui viola nossos padrões de moda.",
  [822505833336832] = "De onde veio essa pobre coisinha? Olha essa roupa...",
  [822505833336576] = "A propósito, posso incomodá-lo a perguntar se ele quer mandar uma garrafa do vinho deste ano? Lembro que ele adora beber.",
  [822505833335296] = "Obrigado pelo seu elogio, senhor/senhora!",
  [822505833334784] = "O tempo está tão bom hoje, querido senhor/senhora. Venha experimentar um cacho de uvas; estas podem ser as uvas mais deliciosas do Golden Autumn Lake!",
  [822505833334528] = "Hmph, porém, as abóboras que cultivo são muito melhores que o vinho dele. Se ele quiser, quero dizer, é claro que posso doar alguns generosamente!",
  [822505833334016] = "Ouvi do Sr. Art que ele planeja fermentar a maior parte das uvas em vinho este ano, e ele até me pediu para perguntar se você precisa...",
  [822505833332480] = "Senhor, você está me ligando?",
  [822505833332224] = "Tenho algo para fazer, então vou embora. Você deveria sair cedo também; ficar muito tempo no banheiro não faz bem à saúde.",
  [822505833331968] = "<P_Heart> (A educação não consiste apenas em cultivar a moralidade, mas também em cultivar a sabedoria, o físico e a estética. Talvez eu deva persuadir Rodin.) </>",
  [822505833331712] = "Eu não entendo. Será que a educação na cidade me dará melhores qualidades do que a gentileza?",
  [822505833331456] = "Mas gosto mais de ficar na aldeia. Eu ajudo Bella a estudar e ajudo a vovó a arar os campos. Todo mundo diz que sou muito gentil.",
  [822505833331200] = "...Porque não quero me formar. Após o exame final, tenho que ir morar na cidade. A professora disse que isso é para que eu possa ter uma educação melhor.",
  [822505833330944] = "Aham! Mas estou um pouco curioso, por que você quis causar problemas durante o exame final?",
  [822505833330688] = "O que! Todas as cinco folhas foram encontradas... Ainda bem que não usei os papéis de teste para limpar...",
  [822505833330432] = "Estão todos na entrada da aldeia, o que significa que você pode ir ao banheiro assim que descer do carro... é muito cômodo, talvez eu possa anotar.",
  [822505833330176] = "A <P_Yellow> casa de madeira quebrada </> na entrada da aldeia, e as duas <P_Yellow> casas de palha adjacentes </>, a experiência é particularmente boa, vá rápido!",
  [822505833329920] = "Eu... não posso sair por um tempo! Há muitos lugares na vila onde se pode pegar um banheiro emprestado, lembre-se disso—",
  [822505833329664] = "Finalmente, não tente procurá-los; você definitivamente não sabe o uso dessa coisa. Um lembrete: não levei papel para o banheiro!",
  [822505833329408] = "Tarde demais! Eles foram jogados no <P_Yellow> riacho </> próximo à igreja! Até agora, quem sabe para onde eles foram, hahahaha!",
  [822505833329152] = "...Espere, o professor Lav mandou você buscar alguma coisa?",
  [822505833328896] = "Alguém está aqui! Alguém está usando isso!",
  [822505833328384] = "Diga sim! Diga sim! Diga sim!",
  [822505833328128] = "(Este homem parece estar esperando conseguir o favor de Lena, devo participar da diversão?)",
  [822505833327872] = "Lena! Meu cérebro e meu coração, todos os órgãos do meu corpo! Todos estão dizendo: eu te amo!",
  [822505833327616] = "Lena, isso é tudo meu coração, por favor, minha amante, minha deusa, dê uma boa olhada no meu amor!",
  [822505833327360] = "Suspiro, irei verificar a casa de Rodin mais tarde. Os exames finais das crianças não podem terminar de forma tão desleixada.",
  [822505833327104] = "Mas olhando na direção, ele deveria ter ido para casa. A família dele tem uma <P_Yellow> empresa de vinificação </> no mercado, basta seguir a <P_Yellow> barragem do rio </> e você estará lá.",
  [822505833326848] = "Ele disse que ficou sem papel higiênico, então roubou as provas de toda a turma! Ele continuou gritando algo sobre 'só limpar uma vez'. Eu não consegui impedi-lo mesmo quando gritei!",
  [822505833326592] = "...Desculpe, perdi a compostura. Acabei de recolher as provas finais dos alunos e aquele pirralho - <P_Yellow> Rodin </> - de repente deu um pulo, gritando que precisava ir ao banheiro.",
  [822505833326336] = "É você quem está esquecido e esqueceu.",
  [822505833326080] = "Jack, quando o velho ficou doente? Como é que eu não sei?",
  [822505833325824] = "Mas depois disso, o vovô ficou doente, e aquele é o médico do lado de fora.",
  [822505833325568] = "Meu pai morreu na guerra, há alguns anos, devido a uma fratura cominutiva no crânio. Mas, felizmente, meu pai morreu na hora e não sofreu muito.",
  [822505833325312] = "Estou apenas relatando fatos, vovó.",
  [822505833325056] = "Jack! Como você pode dizer isso do seu avô?",
  [822505833324800] = "Quem está fora da clínica é meu avô, ele desenvolveu a doença de Alzheimer depois da guerra. Andar de um lado para o outro na porta é uma das manifestações de seu comprometimento cognitivo, não se importe.",
  [822505833324544] = "Aquele ao meu lado? Ela é minha avó. Não olhe para ela como um pouco esquecida agora que está velha; ela foi uma excelente médica quando era jovem.",
  [822505833324288] = "Só posso lhe dar remédios sem receita. Os medicamentos prescritos só podem ser comprados após a consulta do meu tio.",
  [822505833324032] = "Se você quiser comprar remédio, me diga. As consultas exigem filas e a enfermaria para visitação de pacientes fica no lado oposto.",
  [822505833323776] = "{{Sr.|Sra.}}, por favor, fique tranquilo, as habilidades médicas do meu tio também não são ruins. Ele está na sala de consulta.",
  [822505833323520] = "Ah! Ah... sim, esqueci.",
  [822505833323264] = "Vovó, quem está de plantão agora é o tio...",
  [822505833323008] = "Você está perguntando sobre meu velho? Ele saiu para uma visita domiciliar. Não se preocupe, meu filho mais velho está de plantão, você pode confiar nele.",
  [822505833322752] = "{{Sr.|Sra.}}, por favor, fique tranquilo, minha avó não consegue se lembrar da localização do armário de remédios. Se houver algum remédio que você precise comprar, por favor me avise.",
  [822505833322496] = "{{PlayerName}}{{Sr.|Sra.}} certo, gravei para você aqui, por favor, sente-se na cadeira em frente e espere.",
  [822505833322240] = "Ah... hum? Nossa, meus ouvidos estão um pouco embotados e eu não ouvi claramente, {{Jovem|Mocinha}}, você poderia dizer de novo?",
  [822505833321984] = "Ah, tudo bem, vou registrar você agora... {{Jovem|Mocinha}}, qual é o seu nome? Onde você está se sentindo mal?",
  [822505833321728] = "{{Jovem|Mocinha}}, você está aqui para uma consulta médica ou para comprar remédios?",
  [822505833321472] = "Graças a você, meu filho se recuperou. Depois de passar pelo Deus da Morte, ele não joga mais e agora pensa em revitalizar o negócio da família!",
  [822505833321216] = "É você! Gentil {{Sr.|Sra.}}",
  [822505833320960] = "Obrigado, sinto que aprendi muito de novo... Está ficando tarde, vou para casa primeiro.",
  [822505833320704] = "<P_Heart> (Será que preciso atuar como Vidente?) </>",
  [822505833320448] = "<P_Heart> (Mas o Imperador Roselle disse em seu diário que a chave para a poção não é dominar e cavar, mas digerir e agir...) </>",
  [822505833320192] = "O significado simbólico da poção está em seu nome. Como 'Vidente', você pode pensar mais sobre o significado simbólico deste nome.",
  [822505833319936] = "Você já é um Beyonder agora, mas como realmente dominar o poder da poção ainda exige que você mesmo se aprofunde em seu significado simbólico. Neste processo, você deve ter cuidado para evitar o risco de perda de controle.",
  [822505833319680] = "Depois de se tornar mais proficiente, você poderá ver mais. Uma habilidade muito útil, certo?",
  [822505833319424] = "Em outras palavras, além de poder ver diretamente alguns espíritos, fantasmas e espíritos vingativos com Visão Espiritual , você também pode ver o 'Corpo Etérico' e julgar a saúde e as emoções da outra parte através dos diferentes estados da aura.",
  [822505833319168] = "A camada mais externa é o 'Corpo Etérico', que é uma manifestação de sua energia vital e estado físico. A cor da aura que você vê é a manifestação externa do Corpo Etérico.",
  [822505833318912] = "Mais adiante está o 'Corpo Mental', que começa a se combinar com o corpo físico a partir daqui. Envolve a mente e é uma apresentação abrangente de raciocínio, pensamento, percepção e capacidade de compreender as coisas.",
  [822505833318656] = "Fora do Corpo espiritual está o 'Corpo do Mundo Astral'. É a forma como o primeiro se comunica com o Mundo Espiritual e o Mundo Astral, e também está relacionado à vontade e às emoções. Adivinhação e muitas outras magias são realizadas através do Corpo do Mundo Astral.",
  [822505833318400] = "O núcleo é chamado de 'Corpo espiritual ', que é o mais fundamental de todos espiritualidade . Para um Espreitador de Mistérios, todos os caminhos da meditação e do aumento do poder apontam para isso.",
  [822505833318144] = "As cores vistas por Visão Espiritual representam sua aura. O ocultismo geralmente divide a parte não física de cada pessoa em quatro camadas.",
  [822505833317888] = "Muito ansioso para aprender, nada mal.",
  [822505833317632] = "Hum? Por que você ainda não foi embora?",
  [822505833317376] = "Vá cuidar do seu negócio primeiro; haverá muitas oportunidades para fazer perguntas mais tarde.",
  [822505833317120] = "Heh, eles eventualmente serão enviados para a Catedral Sagrada.",
  [822505833316864] = "Está dividido em diversas áreas, armazenando fórmulas de poções de certas Sequências e diversos materiais mágicos, e detendo temporariamente hereges, xenomorfos, cultistas e membros de organizações secretas...",
  [822505833316608] = "Isso parece muito impressionante.",
  [822505833316352] = "Não aborde isso casualmente, ou você será contaminado pelo infortúnio.",
  [822505833316096] = "Ela é guardada por membros oficiais rotativos da Vigias Noturnos , e há pelo menos dois 'Guardiões' dentro da igreja, além de inúmeras armadilhas.",
  [822505833315840] = "O Portão Chanis vem do nome do Arcebispo Chanis, o fundador do sistema moderno Vigia Noturno. Existe um no porão da igreja central em todas as grandes cidades.",
  [822505833315584] = "O que está por trás do Portão Chanis? É muito incomum um porão ter uma porta tão grande.",
  [822505833315328] = "Sim, somos responsáveis ​​por eventos relacionados aos crentes da Deusa da Noite Eterna em Tingen. Organizações semelhantes incluem a Igreja Mandated Punishers of the Storm e a Machinery Hivemind da Steam and Machinery Church.",
  [822505833315072] = "Ainda somos policiais?",
  [822505833314816] = "Na verdade, temos outro sinal: o Sétimo Grupo do Departamento de Operações Especiais do Departamento de Polícia do Condado de Awwa, no Reino de Loen.",
  [822505833314560] = "Pegue, por que não? Contanto que não afete os assuntos diários, ganhar dinheiro é considerado um subsídio extra e os membros da equipe ficam muito felizes com isso.",
  [822505833314304] = "Eu não esperava que Vigias Noturnos usasse uma placa de uma empresa de segurança para encobrir. E se alguém realmente confiar um missão ?",
  [822505833314048] = "Algo mais?",
  [822505833313792] = "Gentil transeunte, por favor ajude um pobre velho.",
  [822505833313536] = "Tudo bem! Por favor, espere um momento, a corrida emocionante está prestes a começar!",
  [822505833313280] = "Porcos fortes, vacas firmes, cães obedientes, coelhos ágeis! Não há nada que você não possa imaginar que não tenhamos! Venha, escolha um!",
  [822505833313024] = "Sorte {{Sr.|Sra.}}! Você entrou no grande evento anual, o cenário das corridas de animais! Que tal? Quer fazer uma aposta!",
  [822505833312768] = "{{Sr.|Sra.}}, venha ver a mais recente obra-prima da Igreja do Deus do Vapor e das Máquinas - 'Walker'!",
  [822505833312512] = "O perfume é a transformação da imaginação. As impressões dos locais característicos de Tingen foram condensadas por mim em garrafas. Você gostaria de experimentá-los?",
  [822505833312256] = "Olá, permita-me apresentar-lhe a versão perfumada do mapa Tingen!",
  [822505833311744] = "<P_Heart> (Um aluno parece muito estranho, deixe-me chegar mais perto e observar...) </>",
  [822505833311488] = "Você quer iniciar o Desafio de Honra?",
  [822505833310976] = "\"O amante de rosto redondo é...\", olá, {{Sr.|Sra.}}. Aprendemos uma música nova! Você está interessado?",
  [822505833310720] = "{{Sr.|Sra.}}, há algo que você queira?",
  [822505833310464] = "Eu entendo, obrigado, Sr. Leonard.",
  [822505833310208] = "No entanto, preciso lembrá-lo de uma coisa. Se você encontrar Beyonder incidentes, lembre-se de relatá-los à Igreja a tempo; é para o seu próprio bem.",
  [822505833309952] = "Além disso, já investiguei este lugar; não é uma organização de culto, então você pode ter certeza de estar ativo aqui.",
  [822505833309696] = "Fora do Vigias Noturnos , você também precisa de algumas de suas próprias \"fontes de informação\" e \"círculos de conhecidos\", que podem ajudá-lo a melhorar no caminho Beyonder.",
  [822505833309440] = "Embora a identidade de um oficial Beyonder seja útil, alguns canais e notícias só podem ser obtidos em locais como este.",
  [822505833309184] = "Sr. Leonard, você não é um oficial Beyonder? Por que você está aparecendo neste tipo de local de encontro secreto para Beyonders não oficial?",
  [822505833308928] = "Você está aqui. Presumo que você já tenha visto aqueles estranhos objetos flutuantes; a Igreja os chama de “Objeto do Fenômeno”. \n Se você coletou alguns, pode entregá-los para mim.",
  [822505833307136] = "Esqueça-os, eles não acabam sendo apagados por nós de qualquer maneira!",
  [822505833306880] = "Irmã Martha, eles estão espalhando flores no baile, sabem que as roupas deles também estão encharcadas na nossa bacia grande?",
  [822505833306624] = "Suspiro... Betty, olhe. Este tecido é tão bom, mas essas manchas são tão difíceis de lavar. Você não acha que eles ficam igualmente sujos quando suam?",
  [822505833306368] = "Eu acho que eles estão espalhando ouro como pétalas?",
  [822505833306112] = "Só pelas flores do baile de uma noite? Deusa... eles conseguem dormir à noite?",
  [822505833305856] = "Com os atuais preços dos grãos... é suficiente para todos em nosso beco comerem até se fartar, cada refeição... pois... pela Deusa, não terminaríamos isso em anos!",
  [822505833305600] = "Cinquenta libras! Cinquenta libras! Eu... eu não consigo nem contar tão alto... Betty, seu cérebro é rápido, quantos centavos equivalem a cinquenta libras? Por quanto tempo alimentaria todos nesta rua?",
  [822505833305344] = "Flores? Eles parecem bons, mas para que servem? Um centavo por flores é muito dinheiro! Quanto poderia custar? Vinte centavos no máximo, certo?",
  [822505833305088] = "Dizendo que alguma nobre senhora... jogou uma bola? Quanto ela gastou só com flores?",
  [822505833304832] = "Pela Deusa! Marta! Betty! Você ouviu pessoas lendo jornal na taverna esta manhã?",
  [822505833304576] = "Obrigado pela sua bênção, Excelência.",
  [822505833304320] = "Foi isso que o Imperador Roselle disse?",
  [822505833304064] = "Você colhe o que planta.",
  [822505833303808] = "Bênçãos para você também.",
  [822505833303552] = "Não só isso, até parece agradável quando peida, caso contrário, por que seria chamado de 'Fart Beauty'? Que porco mágico...",
  [822505833303296] = "E qual é o porco “Pérola” que ele mencionou? \"Porco Cantante\"... Só ouvi falar de galos que cantam. Existem porcos que podem cantar?",
  [822505833303040] = "Não sei onde fica aquele Império Tren; Eu nunca ouvi falar disso.",
  [822505833302784] = "Se você não tiver ratos vivos, saia rapidamente e não cause problemas!",
  [822505833302272] = "Claro que não! <P_Heart> (Sussurrando) </> Se não fosse o Hound Bar pagando mais, eu não me incomodaria com isso...",
  [822505833302016] = "Entrega? Para onde? Não seria um restaurante, seria?",
  [822505833301760] = "Futuro? Quem sabe. Mas enquanto estivermos unidos, não há nada a temer.",
  [822505833301504] = "Você é realmente admirável. Então, e quanto ao seu futuro?",
  [822505833301248] = "Na Lower Street, não somos miseráveis, somos guerreiros – guerreiros que lutam pela sobrevivência.",
  [822505833300992] = "Difícil? Claro que é difícil, mas isso nos fortalece. Temos as nossas próprias regras, o nosso próprio território e até o nosso próprio “negócio”.",
  [822505833300736] = "Mas você ainda é tão jovem, a vida deve ser muito difícil, certo?",
  [822505833300480] = "Foi tão frustrante assistir, reembolso! Exijo um reembolso!",
  [822505833300224] = "Você estava claramente interpretando um homem de verdade, mas foi considerado um covarde. Se eu fosse humilhado, não seria tão fácil conversar comigo!",
  [822505833299968] = "Por favor, acalme-se, senhor. O que você acha das falas agora?",
  [822505833299712] = "<P_Heart> (O espírito de Tia flutua animadamente na frente da fornalha) </>",
  [822505833299456] = "<P_Heart> (O espírito do supervisor olha fixamente para a fábrica têxtil) </>",
  [822505833299200] = "O console do incinerador precisa de combustível para funcionar.",
  [822505833298944] = "Parece que precisa de combustível para começar. Pode ser usado para destruir esses sapatos de dança?",
  [822505833298688] = "O incinerador frio, silenciosamente no centro da oficina.",
  [822505833298432] = "Concluído, esta é a sua recompensa.",
  [822505833298176] = "O selo está quebrado! Então vamos entrar juntos no mundo da música!",
  [822505833297664] = "Existem alguns materiais para Ritual Magic. Mystery Pryer... o que exatamente ela estava tentando fazer quando perdeu o controle?",
  [822505833297408] = "Este é o último trecho. Pule naquele barco e chegue ao outro lado.",
  [822505833297152] = "A segunda seção está ficando mais difícil; cairá na escuridão de vez em quando.",
  [822505833296896] = "Caminhe ao longo do telhado da casa; se você cair na água, você perde.",
  [822505833296640] = "Quer brincar de amarelinha?",
  [822505833296384] = "Eu realmente não entendo onde ele conseguiu dinheiro para instalar um vaso sanitário dourado. Minha irmã, que trabalha na casa de outro vereador, diz que seu patrão vive de maneira muito simples.",
  [822505833296128] = "Hubert geralmente valoriza seu banheiro e, quando vamos limpar, também recebemos ordens de sermos cautelosos.",
  [822505833295872] = "Você está aqui para me perguntar sobre o banheiro, certo?",
  [822505833295360] = "Oficial, ugh, diga-me secretamente, ele está escondendo ouro no banheiro?",
  [822505833295104] = "Jogando lixo? Ugh, eu sabia, eu sabia que era estranho o Sr. Hubert entrar no banheiro na hora certa todas as noites!",
  [822505833294848] = "Senhor, alguém já jogou lixo no vaso sanitário?",
  [822505833294592] = "Se você realmente quer se envolver... Vejo que você está muito interessado, você tem ligações com aqueles policiais? Vá encontrá-los, mas não me arraste para isso.",
  [822505833294336] = "Independentemente disso, não sugiro que você se envolva.",
  [822505833294080] = "Polícia especial? Acho que sei o que aconteceu.",
  [822505833293824] = "Este mundo... está ficando cada vez mais difícil de entender. Você não acha?",
  [822505833293568] = "Todo mundo está dizendo que é porque mexeram em algo que não deveriam. Até aqueles “polícias especiais” vestidos de preto já vieram várias vezes, mas não há explicação.",
  [822505833293312] = "O que aconteceu lá?",
  [822505833293056] = "Você sabe sobre aquele caso no cais recentemente? Tsk... é melhor não andar sozinho por aí à noite ultimamente.",
  [822505833292800] = "(Vários olhares frios fazem sua nuca arrepiar. Você quer abrir o baú do tesouro?)",
  [822505833292544] = "A nota musical está aqui",
  [822505833292288] = "A corrupção dos sonhos foi eliminada, você pode sair do trabalho.",
  [822505833292032] = "Por que de repente ficou com raiva... um temperamento tão estranho!",
  [822505833291776] = "(Irritado) Miau!",
  [822505833291520] = "Por que os olhos deste gato parecem ter tamanhos diferentes?",
  [822505833291264] = "<P_Heart> (Tão frio e indiferente...) </>",
  [822505833290752] = "<P_Heart> (Parece que alguns gatinhos estão desenvolvendo um relacionamento interessante, lembro que o gato era preto...) </>",
  [822505833290496] = "Espere, por que tem algum... pelo preto?",
  [822505833290240] = "Uma gatinha tão bem comportada!",
  [822505833289728] = "Os dois gatinhos são tão fofos...",
  [822505833289472] = "Bem-vindo de volta, Senhor! Você pode construir e decorar o castelo livremente, participar da produção em oficinas e do comércio no mercado ou iniciar o comércio ferroviário. Sob sua liderança, o castelo está sendo construído cada vez melhor.",
  [822505833288960] = "Sobreviva por 120 segundos para abrir a porta para o próximo nível",
  [822505833288704] = "Seu arrulhar é único.",
  [822505833288448] = "Hehe, esses três pombos foram criados por uma galinha desde pequenos!",
  [822505833288192] = "Faça chuva ou faça sol! Criança, você também está interessado?",
  [822505833287936] = "Senhora, você vem alimentar os pombos todos os dias?",
  [822505833287680] = "Shh... ela foi para casa, ela foi para casa pela chaminé vermelha!",
  [822505833287424] = "Quando aquela garota fugiu, um dos sapatos dela ficou preso na lareira...",
  [822505833287168] = "Nenhum deles parece certo...",
  [822505833286912] = "Benson, o que você acha?",
  [822505833286400] = "Ouça, está vindo de novo! Rápido... preciso bloquear a porta!",
  [822505833286144] = "Conto com você, eu... não tenho mais forças...",
  [818107786904320] = "O que você tem?",
  [818107786771712] = "Seu espiritualidade é realmente afiado, para poder me encontrar escondido. \n Por que não brincamos de esconde-esconde? Encontre todos os baús de tesouro próximos e você poderá abrir meu tesouro.",
  [818107786594048] = "Hmph, você foi enviado pelos vizinhos para roubar abóboras! Não será tão fácil me vencer no Festival da Colheita!",
  [822505833285376] = "E tenta arrombar a porta de vez em quando!",
  [822505833285120] = "Escute, este quarto não está limpo; 'isso' está fora.",
  [1143563228290048] = "No entanto, sua sugestão tem algum valor. Vou propor isso a eles.",
  [822505833284608] = "Você também está preso aqui...",
  [822505833284352] = "Nós cinco nos tornamos amigos por causa deste livro e combinamos por carta nos encontrarmos aqui – um cavalheiro com o pseudônimo de Lula ainda não chegou.",
  [1143563228823552] = "Quanto ao motivo pelo qual ela consegue falar, é decorrente de... um pequeno erro, um pequeno erro que todos os donos de cães cometem: esquecer que seu cachorro pode abrir portas.",
  [1143563228822528] = "Um nome honorífico de três linhas não é apenas um nome; está mais próximo de um olhar de divindade, de um feitiço de convocação.",
  [822505833283584] = "Você quer dizer \"O Grande Aventureiro\"?",
  [822505833283328] = "Parece que este {{Sr.|Sra.}} está ouvindo nossa discussão há muito tempo. Você também é um leitor fiel de Miss Fors?",
  [822505833283072] = "Claro! Foi tão emocionante. Não esperava que o velho rico, que dizem que só gosta de dinheiro e belezas, fosse tão ágil a ponto de escapar da polícia!",
  [822505833282816] = "Você leu o capítulo atualizado na semana passada? A história do homem rico se unindo a seu amigo aventureiro para roubar informações no banquete.",
  [822505833282560] = "Você pode me chamar de bobo aqui. Na verdade, meu pseudônimo Hot Cocoa é o nome do meu cachorrinho.",
  [822505833282304] = "Olá a todos, eu sou o Hot Cocoa.",
  [822505833282048] = "A senhora que acabou de chegar ainda não se apresentou. Vamos conhecê-la.",
  [822505833281792] = "Ainda sente falta do Sr. Lula? Ele disse em sua carta que chegaria atrasado; vamos esperar mais um pouco.",
  [822505833281536] = "Ei, não me chute!",
  [822505833281280] = "<P_Heart> (Olhar...) </>",
  [822505833280768] = "<P_Heart> (Parece que não acredito nada...) </>",
  [822505833280256] = "Você deve adicionar molho de soja ao pudim de tofu!",
  [822505833280000] = "Você deve adicionar açúcar ao pudim de tofu!",
  [822505833279744] = "Para família! Para o futuro!",
  [822505833279488] = "O sentido da vida é ir ao cais e comer batatas fritas!",
  [822505833279232] = "<P_Heart> (Parece que eles estão discutindo algo aqui; deixe-me chegar mais perto e ouvir.) </>",
  [822505833278976] = "Uau, au!",
  [822505833278720] = "Você está respondendo minha pergunta? Que inteligente!",
  [822505833278208] = "O lojista também não está lá?",
  [822505833277696] = "Não está aberto?",
  [822505833277440] = "Pobre criança, deve estar com muita fome agora, vamos procurar outro lugar. A propósito, o gatinho ainda nos reconhece, dois clientes habituais?",
  [822505833277184] = "Já olhei em volta, não vi nem um único pelo de gato.",
  [822505833276928] = "Ei... isso tudo é passado, vamos mudar de assunto - para onde foi aquela linda gatinha branca que mendigava comida no restaurante?",
  [822505833276672] = "Oh, eu paguei por aquela refeição. Você era apenas um garoto pobre naquela época, irmão!",
  [822505833276416] = "É uma pena; este restaurante é uma prova da amizade entre o Sr. Ojerik e eu. Nos conhecemos em uma mesa de jantar!",
  [822505833276160] = "Boa sorte para o amigo lá dentro.",
  [822505833275904] = "Saia agora! Pegue sua bagagem suja e saia!",
  [822505833275648] = "Obrigado, Sr. Franky.",
  [822505833275392] = "<P_Heart> (Benson costuma dizer que o QI do Sr. Frank não é tão bom quanto o de um babuíno de cabelos cacheados, e ele facilmente o convenceu a instalar canos de gás, para o bem dos meus estudos...) </>",
  [822505833275136] = "Seu quarto tem até cano de gás instalado, mas não aumentei o aluguel. Você nunca encontrará um senhorio mais generoso do que eu!",
  [822505833274880] = "Tenho um apartamento de alta classe aqui, o que é raro na Iron Cross Street.",
  [822505833274624] = "<P_Heart> (O salário semanal de Benson é de apenas 1 libra e 10 xelins; o dinheiro realmente não dura muito... hmm, devo trabalhar e ganhar dinheiro o mais rápido possível.) </>",
  [822505833274368] = "O aluguel de um apartamento de dois quartos é de 5 soli e 6 pence por semana, acredite, este é o apartamento com melhor custo-benefício de toda Tingen!",
  [822505833274112] = "Algo mais?",
  [822505833273856] = "Olá, Klein. Você paga o aluguel em dia e é uma pessoa decente. O que você quer comigo?",
  [822505833146112] = "<P_Heart> (sussurrando) </> Você é realmente uma pessoa com grande talento diplomático; O julgamento que Lange faz das pessoas é verdadeiramente preciso.",
  [822505833273088] = "<P_Heart> (Isso é... uma banda?) </>",
  [822505833272832] = "No entanto, ela é muito bonita e gentil. Artistas como todos nós gostam de coisas bonitas, não é? Costumo convidá-la para visitar o estúdio!",
  [822505833272576] = "Você quer dizer Reno? Ela realmente é uma garota muito introvertida. Você vai entender quando for falar com ela, hahaha.",
  [822505833272320] = "Existem esboços, aquarelas, pinturas a óleo e assim por diante. Qual tipo você gostaria de experimentar?",
  [822505833272064] = "Os trabalhos aqui concluídos podem ser emoldurados e levados para casa para presentear familiares e amigos. Se você estiver interessado, corra e pegue um pincel.",
  [822505833271808] = "Meu estúdio recebe todos que querem fazer amigos! Se você é um cliente animado e alegre, todos os grandes pintores do ateliê vão gostar de você!",
  [822505833271552] = "Estou pintando a gata da Rhine, ela é dona da floricultura do outro lado da rua, é tão fofa quanto o gato, né?",
  [822505833271296] = "Se você for, poderia levar uma flor para a senhorita Leona para mim? Agradeça a ela por sua hospitalidade na semana passada.",
  [822505833271040] = "Na verdade, se você quiser fazer amigos, o estúdio de arte do outro lado da rua é mais adequado.",
  [822505833270784] = "...Comigo? Uh... desculpe, estou um pouco nervoso.",
  [822505833270528] = "Desculpe, eu realmente não sei como apresentar essas coisinhas lindas para você, fique à vontade para dar uma olhada, espero que gostem.",
  [999388423920384] = "Uau!",
  [822505833270016] = "Olá, o que você precisa?",
  [822505833269760] = "Há mais alguma coisa que eu possa ver?",
  [822505833269504] = "E-oitenta mil? Hmm... ainda é um pouco caro.",
  [822505833269248] = "Oitenta mil libras, nobre senhora.",
  [822505833268992] = "É realmente de tirar o fôlego, é...",
  [822505833268736] = "O que você acha?",
  [822505833268480] = "A safira de 25 quilates no centro é tão pura quanto as lágrimas derramadas pelas estrelas.",
  [822505833268224] = "Fabricadas pelo melhor joalheiro de Backlund ao longo de três anos, cada pedra preciosa foi rigorosamente selecionada.",
  [822505833267968] = "<P_Heart> (Segurando com cuidado) </> Este é o tesouro da nossa loja — Lágrimas das Estrelas!",
  [822505833267712] = "Seu gosto é realmente impecável!",
  [822505833267456] = "Porém, sou muito grato ao Sr. Austin por me acolher. Você não imaginaria que antes disso eu era um malandro que passava o dia inteiro vagando pelas ruas roubando dinheiro.",
  [822505833267200] = "Meu? Ah... minha história não é muito interessante; Provavelmente passarei minha vida chata aqui.",
  [822505833266944] = "A propósito, não se esqueça de pedir ao Sr. Austin para assinar um voucher de consumo – você pode usar este voucher para aproveitar um desconto de 20% no restaurante da esquina!",
  [822505833266688] = "Se você é um jovem estudante ou funcionário do governo, também pode vir aqui todo fim de semana para pegar emprestado um quarto silencioso para estudar.",
  [822505833266432] = "Se estiver com pouco dinheiro, você também pode, como alguns clientes regulares, trocar uma noite de estadia por um delicioso pão caseiro ou lindos livros de colecionador.",
  [822505833266176] = "Tal como diz a nota sobre a mesa, oferecemos-lhe chá preto suave e almofadas macias.",
  [822505833265920] = "Se você estiver disposto, converse mais com ele, mesmo que ele não consiga responder com a voz.",
  [822505833265664] = "Austin é um herói corajoso que já guardou o Reino Loen na linha de frente. Depois de retornar a Tingen, ele ainda pode oferecer um lugar acolhedor e encantador para os viajantes.",
  [822505833265408] = "Olá, {{Sr.|Sra.}}, o Very Fun Hotel lhe dá as boas-vindas!",
  [822505833265152] = "Claro, claro, querido, quero comer o pão de maçã assado com queijo que você faz.",
  [822505833264896] = "De qualquer forma, você concordou, linda cantora, Srta. Edwina, agora Sra. Saris, pode jantar comigo hoje?",
  [822505833264640] = "E aí você me convidou para jantar, ah, eu devia estar bêbado quando aceitei sua confissão!",
  [822505833264384] = "Hahaha, claro, meu querido, antigamente eu confiava nisso para conquistá-lo – naquela época você era a estrela mais brilhante da ópera!",
  [822505833264128] = "Você ainda é muito bom em dizer coisas doces, Sr. Saris.",
  [822505833263872] = "Como foi aquele poema do Imperador Roselle? \"Muitos amaram sua linda juventude, mas quando você envelhece, ainda amo as rugas do seu rosto\"...",
  [822505833263616] = "Não, meu querido, você é dois meses inteiro mais novo que eu, quem é inútil sou eu, o velho!",
  [822505833263360] = "Oh, desculpe, meus olhos não estão mais muito bons, estou muito velho...",
  [822505833263104] = "Isso é um pardal, minha querida, voou para o telhado em frente.",
  [822505833262848] = "Uma mosca passou voando pelos meus olhos.",
  [822505833262592] = "Alguns dizem que o proprietário fez fortuna, mudou-se para Backlund e abriu uma loja maior. Outros dizem que o proprietário perdeu todo o seu dinheiro lutando contra o mal em um bar e que o restaurante sofreu com isso.",
  [822505833262336] = "Diga-me as duas coisas, amigo, você sabe que gosto de ouvir histórias.",
  [822505833262080] = "Ela se mudou ou fechou, qual versão você quer ouvir?",
  [822505833261824] = "Ei, onde foi esse restaurante?",
  [822505833261568] = "...Mas olha essa gatinha branca, quer dizer, ela é bem bonita, né? Que tal eu adotá-la?",
  [822505833261312] = "Hmm... talvez você tenha razão, vou até a cozinha e encontro sobras de pão para ela.",
  [822505833261056] = "A gatinha só quer que você dê algo para ela comer, ela parece muito magra.",
  [822505833260800] = "Hmm... você está certo. Obrigado pela sua sugestão, espero que meu pequeno Ang possa se dar bem com seu novo amigo.",
  [822505833260544] = "É uma boa ideia, senhor. Não se preocupe, nada que você não gostaria de ver deveria acontecer entre um gato e um cachorro.",
  [822505833260288] = "Isso... sério? Devo levá-lo para tomar sol?",
  [822505833260032] = "Senhor, talvez o pequeno Unger só queira fazer um novo amigo.",
  [822505833259776] = "É o cachorro que eu tenho – na verdade, ele está em período de acasalamento. Isto é verdadeiramente terrível; Nunca permitirei que a nobre família Ang se associe com estranhos, muito menos com um gato!",
  [822505833259520] = "Pequeno Unger?",
  [822505833259264] = "Principalmente meu lindo Ang, ele sai correndo porta afora assim que ouve o miado de um gato.",
  [822505833259008] = "Esta gata está miando na minha porta há três dias! Minha família inteira está tão perturbada com isso que não conseguimos dormir.",
  [822505833258752] = "Lindas cores e nomes mágicos fazem o vinho ser vendido por mais; nosso chefe depende de embalagens para atrair pessoas ricas.",
  [822505833258496] = "É tão exagerado?",
  [822505833258240] = "{{Sr.|Sra.}}, você não parece uma pessoa rica. Já vou avisando, o preço de uma taça de vinho aqui pode muito bem te deixar sem uma única peça de roupa!",
  [822505833257984] = "É claro que não aceitamos pessoas comuns sem dinheiro.",
  [822505833257728] = "Marketing, é tudo marketing, {{Sr.|Sra.}}, entendeu? Só assim atrairá aqueles duques e senhoras que não conheceram muito o mundo para virem comprar vinho.",
  [822505833257472] = "Ah, senhor! Na verdade, você deveria ir para os fundos deste prédio; o clube Adivinhação atende melhor às suas necessidades e - contratar um adivinho custa apenas alguns centavos.",
  [822505833257216] = "Mas, está escrito na sua placa! Eu só quero provar o vinho da profecia...",
  [822505833256960] = "Não existe tal coisa, senhor, é apenas um nome.",
  [822505833256704] = "Se eu beber este vinho, posso sonhar com o que está para acontecer? Estou disposto a gastar minhas economias para comprar um copo. Quero entrar nos meus sonhos e ver se a linda dona Hebe vai se tornar minha esposa!",
  [822505833256448] = "Ah, sim, senhor, temos um vinho branco sofisticado chamado \"Future Dream\". Se precisar, fique à vontade para entrar e provar.",
  [822505833256192] = "Ouvi dizer que aqui há vinho que permite sonhar com o futuro?",
  [822505833255936] = "Nossa, estou velho, estou velho... não consigo ouvir claramente...",
  [822505833255680] = "Estou velho. Não sei. Não fui eu. Eu vou te ensinar, ande duas ruas, depois vire à esquerda, depois vire à direita, depois siga em frente, vá lá fazer reclamação...",
  [822505833255424] = "Você escreveu tantos relatórios exagerados?!",
  [822505833255168] = "{{《Jovem encontra secretamente o xerife》|《Xerife encontra secretamente uma mulher misteriosa》}}? 'Quebra! Estudante universitário preso'? 'Restaurante Carnivore Raids à noite, tremores sentidos em prédio residencial'?",
  [822505833254912] = "O que? Tínhamos alguma conexão antes? Eu escrevi sobre você? O que você vai fazer?",
  [822505833254656] = "Não posso falar com você se não houver nada acontecendo?",
  [822505833254400] = "Eu só queria conhecer você.",
  [822505833254144] = "Vale a pena ler os jornais e revistas que mencionei. Amigo, tempo é conhecimento!",
  [822505833253888] = "No entanto, os trens a vapor também podem trazer jornais e revistas de outros lugares, como o Backlund Daily. Revistas familiares, resenhas de histórias e o Tussock Times também são bons.",
  [822505833253632] = "Claro, o mais interessante é o Intis Post, mas infelizmente Tingen não tem muitos. Suspiro, sinto muita falta dos dias antes da aposentadoria, tudo era tão interessante...",
  [822505833253376] = "Cada jornal tem características próprias, é muito difícil escolher. Você pode ler grandes notícias imediatamente no Morning Post; em comparação, o Homem Honesto é mais para o lazer.",
  [822505833253120] = "<P_Heart> (Esta cadeira não cabe tantas pessoas!) </>",
  [822505833252864] = "Haha, você veio à pessoa certa. Diante de você está um homem com vinte anos de experiência em livros e jornais, ex-editor do Post, ex-editor do Tingen Honest Reporter e atual escritor freelance.",
  [822505833252608] = "Com licença, você tem algum jornal recomendado?",
  [822505833252352] = "Aconteceu alguma coisa? Você me conhece?",
  [822505833252096] = "<P_Heart> (Imerso em seu próprio mundo...) </>",
  [822505833251840] = "Ah, estou pronto para receber o amor...",
  [822505833251584] = "Amor! Claro que é amor! Assim como cantam os bardos nas ruas, o amor desceu.",
  [822505833251328] = "Desculpe, {{Sr.|Sra.}}, estou muito feliz!",
  [822505833251072] = "Cantando - cantando na chuva -",
  [822505833250304] = "Ah... desculpe. Mas devo honestamente recusar você. Caso contrário, isso pode causar problemas para nós dois.",
  [822505833250048] = "Não creio que os Loeneses sejam diferentes dos Intisianos... tornar-se um ator de teatro famoso muito cedo traz tantos problemas, mas só quero terminar meus estudos em paz.",
  [822505833249792] = "Por favor, me perdoe, desde que me mudei para Tingen, encontrei muitas coisas assim.",
  [822505833249536] = "Ah... desculpe.",
  [822505833249280] = "Mas receio ter de decepcioná-lo; quanto a um encontro, minha resposta é não.",
  [822505833249024] = "Não é a primeira vez que encontro esse tipo de coisa...",
  [822505833248768] = "{{Sr.|Sra.}}, acho que não nos conhecemos.",
  [822505833248512] = "Eu disse – é realmente assim que parece depois da expansão? Como diabos trabalham esses trabalhadores ferroviários!",
  [822505833248256] = "Oh criança, claro que está aqui, nesta estação de trem lotada!",
  [822505833248000] = "Se meu irmão não tivesse confiscado temporariamente minha carruagem particular, quem iria querer pegar um trem público?",
  [822505833247744] = "Olha aquela sala de espera lotada, sinto o cheiro do suor nojento dos meninos do Distrito Leste!",
  [822505833247488] = "Você é muito inteligente, criança, e parece limpo e arrumado, o que é reconfortante.",
  [822505833247232] = "Eu sei, senhora, é a estação ferroviária.",
  [822505833246976] = "Você sabe onde vi as pessoas mais pobres da minha vida?",
  [822505833246464] = "Quero ser a pessoa mais rica de toda Tingen!",
  [822505833246208] = "Eu quero ser rico!",
  [822505833245440] = "Chá, professora...",
  [822505833245184] = "***, eu disse que só estou dando um tempo, posso terminar para você no prazo estipulado! <P_Heart> (cospe nos seus pés) </>",
  [822505833244928] = "Você subiu até aqui arriscando sua vida, mas está com muito medo de se mover. Você não ganhará nenhum dinheiro.",
  [822505833244672] = "Então não carreguei este tripé em vão!",
  [822505833244416] = "Talvez... mas a realidade só dá a todos uma chance de compor uma cena. Contanto que uma foto capture um determinado momento...",
  [822505833244160] = "Não tem assunto específico... Olha, você notou a mudança de luz e sombra do outro lado do rio? É difícil para um pincel reproduzir mudanças tão instantâneas.",
  [822505833243904] = "Quem é o protagonista em sua lente?",
  [822505833243648] = "Hmm, você está interessado na arte da fotografia?",
  [822505833243392] = "Olá, você está tirando fotos?",
  [822505833243136] = "Não, isso mesmo.",
  [822505833242880] = "***, alguns centavos cairão do céu se eu não trabalhar? Esse tipo de trabalho rende muito mais que os que estão no terreno!",
  [822505833242624] = "Se você tem tanto medo de altura, por que subiu?",
  [822505833242368] = "Sim, sim. Sou eu, estou com muito, muito medo, a professora mandou, tirar, dar um tempo.",
  [822505833242112] = "Qual é o problema? Deixe-me dizer, não estou relaxando.",
  [822505833241856] = "Só de pensar nisso você sabe como é legal!",
  [822505833241600] = "É o mais legal! Imagine só, pular do topo da igreja com uma enorme lua vermelha atrás de você!",
  [822505833241344] = "Claro que é porque...",
  [822505833241088] = "E você deve vivenciar isso durante a Lua Vermelha!",
  [822505833240832] = "Salto da Lua Vermelha, é como uma águia voando alto, pode deixar você experimentar a sensação de verdadeira liberdade!",
  [822505833240320] = "Não hesite, não recue, mantenha a fé no seu coração. É por isso que também o chamo de “Salto da Lua Vermelha”.",
  [822505833239040] = "Ouvi dizer que a Sra. Audrey e o Sr. Leonard foram quem deram o nome.",
  [822505833238784] = "O nome deste gato é 'Sweet Iced Tea'?",
  [822505833238528] = "<P_Heart> (Um nome está gravado na etiqueta: \"Sweet Iced Tea\") </>",
  [822505833238272] = "<P_Heart> (Faça a mão na sua mão) </> Miau ~",
  [822505833238016] = "Quem é o gatinho mais fofo do mundo?",
  [822505833237760] = "Eu sei, querido, você me ama, né! Eu também te amo!",
  [822505833237248] = "Oh meu Deus! Está me seduzindo!",
  [822505833236992] = "Espero que o pombo não se transforme num espírito vingativo depois de ser cozinhado num prato...",
  [822505833236736] = "Eu fui chef na minha vida passada? Minha especialidade era pombo assado? Então estou sendo punido por não poder me transformar em pombo, mas em vez disso alimentar pombos aqui?!",
  [822505833236480] = "Poderia ser porque...",
  [822505833236224] = "Por que não posso ser um pombo?",
  [822505833235968] = "E você não precisa se preocupar em estar com fome; alguém vem alimentá-lo todos os dias.",
  [822505833235712] = "Você não precisa se preocupar com aluguel, você pode morar em qualquer lugar...",
  [822505833235456] = "Veja como você está feliz, não precisa pensar em nada, nem se preocupar.",
  [822505833235200] = "Ok, muito obrigado!",
  [822505833234944] = "Ele deveria ser aquele entre Vigias Noturnos que sabe mais sobre o passado do Capitão Dunn.",
  [822505833146368] = "O que você disse? Eu não ouvi você claramente agora.",
  [822505833234176] = "Obrigado pela sua gentileza. Cemitério Rafael, ele está lá.",
  [822505833233920] = "Talvez eu possa oferecer um buquê de flores para ele.",
  [822505833233664] = "Eu sei, ele se sacrificou para proteger Tingen.",
  [822505833233408] = "Talvez você também tenha ouvido o nome dele.",
  [822505833232896] = "Posso perguntar quem é o veterano que você mencionou?",
  [822505833232640] = "Sim, 'Não fique nervoso, estamos protegendo Tingen'.",
  [822505833232384] = "Sim, ele foi um ótimo guia. Ele nos ensinou muito.",
  [822505833232128] = "Claro que estava, mas tinha um bom veterano com quem aprender.",
  [822505833231872] = "Então, o capitão fica nervoso quando sai em missão pela primeira vez?",
  [822505833231616] = "Está tudo bem, é normal ficar nervoso na primeira vez. Você vai se acostumar mais tarde.",
  [822505833231360] = "Não fique nervoso, é apenas uma patrulha de rotina.",
  [822505833231104] = "Isso é assassinato!",
  [822505833230848] = "Eles os fazem rastejar em canos para limpar as cinzas de carvão.",
  [822505833230592] = "As crianças trabalhadoras têm dedos finos, por isso os proprietários das fábricas as contratam para limpar os fiapos de algodão presos nos fusos.",
  [822505833230336] = "Também faltam crianças trabalhadoras!",
  [822505833230080] = "Os capitalistas substituem as válvulas de segurança por núcleos de cobre baratos e usam o dinheiro poupado para contratar mais trabalhadores.",
  [822505833229824] = "As famílias têm que assinar um termo de responsabilidade apenas para entrar nas ruínas em busca de corpos!",
  [822505833229568] = "Você acha que eles vão compensar honestamente? Olha a notícia de hoje!",
  [822505833229312] = "O manual de trabalho menciona que a fábrica compensará lesões relacionadas ao trabalho.",
  [822505833229056] = "As crianças sacrificadas são tratadas apenas como “desgaste laboral”!",
  [822505833228544] = "Hun... Hunter... esta... esta senhora... está... está... fazendo sentido!",
  [822505833228288] = "Ferro bom aguenta martelo, vá visitar a fábrica com mais frequência, garoto!",
  [822505833228032] = "...Sua boca é mais dura que ferro.",
  [822505833227776] = "Apenas recitar poesia é inútil.",
  [822505833227520] = "Algemas? O banco em que você está sentado, a estrada pavimentada em que você anda... qual deles não foi martelado por um trabalhador com um martelo e uma chave inglesa?",
  [822505833227264] = "Os poetas só usam a linguagem para revelar a verdade, assim como as engrenagens simbolizam os grilhões da indústria.",
  [822505833227008] = "Tome cuidado! Este poeta... você já usou um martelo?",
  [822505833226752] = "Senhora, esta máquina é sua?",
  [822505833226496] = "Obrigado pelo elogio, Daly.",
  [822505833226240] = "Hun... Hunter... você... você disse isso tão... tão bem!",
  [822505833225984] = "<P_Heart> (Hmm? Tem duas pessoas ali apontando para ele </> <P_Yellow> sussurrando </> <P_Heart> , estou um pouco curioso.) </>",
  [822505833225728] = "<P_Heart> (Esse cara parece ter esbarrado em um vaso de flores na beira da estrada... Ele parece todo atordoado.) </>",
  [822505833225472] = "<P_Heart> (O estado dela é muito ruim; ela não consegue mais se comunicar normalmente... As notas que o Mago me emprestou registram a habilidade de 'Hipnose' e 'Leitura de Mente', posso tentar isso...) </>",
  [822505833225216] = "A melodia, a melodia não para... uma maldição... é uma maldição...",
  [822505833224960] = "Olá, posso perguntar o que aconteceu?",
  [822505833224704] = "Dor... minha cabeça dói tanto... uauuu... o som, o som voltou...",
  [822505833224448] = "<P_Heart> (De qualquer forma, vamos ignorar esse sujeito tonto por enquanto. Os outros dois estão quase acabando e eu ainda não terminei de ouvir a fofoca...) </>",
  [822505833224192] = "<P_Heart> (Olhando como ele está rindo enquanto caminha, não é de admirar que ele tenha esbarrado em um vaso de flores na beira da estrada.) </>",
  [822505833223936] = "<P_Heart> (Eu ouvi as duas pessoas ao meu lado dizerem que o nome dele é Sam? E algo sobre... um filho ilegítimo... herança... uma amante?) </>",
  [822505833223680] = "Por que tem uma garota deitada no chão... acorde...",
  [822505833221632] = "Teste de salto de opção",
  [822505833221376] = "Opção sem teste de salto de ação",
  [822505833221120] = "Espero que ela ainda me reconheça quando nos encontrarmos...",
  [822505833220864] = "Nunca esperei que, depois de todos esses anos, ela se tornasse uma corajosa aventureira, enquanto eu nunca sequer saí de Tingen.",
  [822505833220608] = "Minha amiga Joan acabou de terminar uma viagem. Escrevemos um para o outro há muito tempo para visitar nosso ex-professor na Hoy University.",
  [822505833220352] = "Estou esperando meu amigo. Estou tão ansioso para vê-la!",
  [822505833220096] = "<P_Heart> (Chuva no meio do caminho... que nome estranho.) </>",
  [822505833219584] = "{{Sr.|Sra.}}, você gostaria de comprar um guarda-chuva?",
  [822505833219328] = "{{Sr.|Sra.}}, é melhor sair daqui antes que o próximo trem chegue—as pessoas que descem vão espremer você como sardinha em lata!",
  [822505833219072] = "Ah, meus queridos... sempre haverá mais salário, mas uma jornada tão esperada como essa não nos esperará para sempre.",
  [822505833218816] = "Trabalhamos muito para economizar esse dinheiro! Por que não podemos ser mais frugais...",
  [822505833218560] = "Mas duas passagens de segunda classe custam trinta libras! Isso é tanto quanto meu salário por duas semanas!",
  [822505833218304] = "Você não gostaria de ficar na terceira classe, Mina. Esses assentos estão lotados e imundos.",
  [822505833218048] = "Joseph, eu disse que só precisávamos de passagens de terceira classe. Por que esta é uma passagem de segunda classe?",
  [822505833217792] = "<P_Heart> (Suspiro... Parece que esta jovem entendeu mal alguma coisa.) </>",
  [822505833217536] = "Não seja tímido, {{Sr.|Sra.}}. Há muitas pessoas como você que não têm dinheiro suficiente para comprar uma passagem.",
  [822505833217280] = "<P_Heart> (Sentindo-se um pouco estranho, você inconscientemente dá tapinhas nos bolsos.) </>",
  [822505833217024] = "Ah, certo, lembre-se de levar seu documento de identificação para foto ao embarcar; este é um novo regulamento emitido pelo Reino.",
  [822505833216768] = "Para onde você está indo? Se você estiver disposto a tentar, há muitas rotas novas que acabaram de ser abertas aqui.",
  [822505833216512] = "Olá, {{Sr.|Sra.}}! Gostaria de comprar um ingresso?",
  [822505833216256] = "Bem-vindo a Tingen, {{Sr.|Sra.}}! Você gostaria de pegar uma carruagem? Pode chegar a qualquer lugar em Tingen, e ainda oferecemos uma visita guiada gratuita!",
  [822505833216000] = "<P_Heart> (Poder misterioso... parece que preciso relatar isso ao capitão...) </>",
  [822505833215744] = "...Não, não, se ele realmente ouvir alguém falando sobre isso, nós dois teremos que pegar um trem e correr para salvar nossas vidas amanhã!",
  [822505833215488] = "Ah, você quer dizer... faz muito tempo que não há notícias dele do mar. Talvez esse poder misterioso esteja relacionado a ele.",
  [822505833215232] = "Mas falando em aventureiros do mar... o único que consigo pensar é aquele escrito em \"O Grande Aventureiro\".",
  [822505833214976] = "...É realmente tão mágico?",
  [822505833214720] = "É um tubo feito de metal. Quem o vê cai imediatamente em alucinações e ouve sussurros obscuros e ininteligíveis. Há rumores de que está relacionado ao texto do diário do Imperador Roselle.",
  [822505833214464] = "Um objeto misterioso...?",
  [822505833214208] = "Você já ouviu falar? Um aventureiro apareceu no Evil Dragon Bar e está carregando um objeto misterioso do mar.",
  [822505833213952] = "Afinal, o conhecimento é uma coisa maravilhosa!",
  [822505833213696] = "Honestamente, comparado a isso, estou ansioso para me tornar um verdadeiro estudante universitário mais...",
  [822505833213440] = "Isso certamente seria bom...",
  [822505833213184] = "Ei, seria melhor trazer de volta um cavalheiro bonito, não acha?",
  [822505833212928] = "Eu realmente espero poder ter uma aventura na Backlund University.",
  [822505833212672] = "Claro que vou lembrar, você também deve compartilhar coisas interessantes sobre a Hoy University comigo.",
  [822505833212416] = "Lilith, lembre-se de nos escrever quando chegar a Backlund.",
  [822505833212160] = "Últimas notícias de Tingen!",
  [822505833211904] = "{{Sr.|Sra.}}, o Tingen Morning Post para um linar, pegue uma cópia!",
  [822505833211648] = "Eu realmente espero que meu gato volte para casa logo!",
  [822505833211392] = "Você está certo, talvez... acho que deveria esperar um pouco mais.",
  [822505833211136] = "Não se preocupe, senhorita. Talvez... os gatos também tenham coisas que devem fazer.",
  [822505833210880] = "Gosta de leite doce; talvez um pequeno presente possa ajudá-lo a encontrá-lo...",
  [822505833210624] = "Muito obrigado, gentil {{Sr.|Sra.}}, se você ver, por favor não se esqueça de me dizer.",
  [822505833210368] = "Suspiro... como vou encontrar meu gato?",
  [822505833210112] = "Mas desapareceu há uma semana e alguém o viu correr para a estação ferroviária.",
  [822505833209856] = "É um gato preto muito espiritual. No passado, não importava para onde fugisse, sempre voltava para casa antes do pôr do sol...",
  [822505833209600] = "Com certeza você vai encontrar, senhorita, boa sorte.",
  [822505833209344] = "...Para ser mais preciso, estou esperando que ele retorne.",
  [822505833209088] = "Olá, você viu meu gato? Eu estive procurando por isso em todos os lugares.",
  [822505833208832] = "Observando as pessoas indo e vindo por aqui, o clima fica muito mais alegre!",
  [822505833208576] = "Este é um progresso gratificante, certo?",
  [822505833208320] = "Agora, você pode viajar diretamente de Tingen para as montanhas do norte e para o porto do sul, e o número de trens com destino a Backlund dobrou.",
  [822505833208064] = "A ferrovia é a medalha da cidade; Sou apenas uma parte desta medalha, e a Estação Ferroviária de Tingen deveria incluir o nome de cada cidadão de Tingen.",
  [822505833207808] = "Ah... não, claro que não se chama assim, haha.",
  [822505833207552] = "Ah, certo, eles também prepararam um desconto vitalício no ingresso como recompensa para mim.",
  [822505833207296] = "Recentemente fiz uma doação para a construção ferroviária em Tingen e agora existem vários trens novos que levam a outras cidades de Loen.",
  [822505833207040] = "Está tudo bem, querido! Por que você não leva Walter até lá para comprar um jornal? Tudo bem, vá agora!",
  [822505833206784] = "Pai, mãe, o que aconteceu?",
  [822505833206528] = "O noivo da Selina ainda está por perto, fale baixo, vou dar uma olhada daqui a pouco.",
  [822505833206272] = "Inferno, do que você está falando? Ele fez uma enorme fortuna em Intis; Ainda carrego essa carta comigo!",
  [822505833206016] = "Não, quero dizer que aquele porteiro sujo se parece exatamente com Bill!",
  [822505833205760] = "Venha até mim se precisar de serviços de guia turístico!",
  [822505833204992] = "Posso ver que este é o seu desejo interior. Estou disposto a dar alguns descontos para quem tem vontade de aprender. Por apenas cinco centavos, vou levá-lo para um passeio por toda Tingen.",
  [822505833204736] = "Comecei o discurso de vendas com muito entusiasmo...",
  [822505833204480] = "Ou você pode pagar um centavo primeiro para experimentar a explicação do Night Memorial Monument. Adicione outro centavo e você poderá obter serviços fotográficos. Que tal, que negócio com bom custo-benefício, qual você quer?",
  [822505833204224] = "Como você quer tanto saber, estou disposto a dar alguns descontos para quem tem vontade de aprender. Por apenas cinco centavos, vou levá-lo para um passeio por toda Tingen.",
  [822505833203968] = "A luz do conhecimento, acho que você deve querer saber sobre as atrações de Tingen!",
  [822505833203712] = "Olá, {{Sr.|Sra.}}, vejo a luz da sede de conhecimento brilhando em seu rosto!",
  [822505833203456] = "No nosso Intis, o romance é o mais popular. Sua curiosidade me faz perceber que o povo de Loen também aprecia seu charme!",
  [822505833203200] = "Ouça, uma cotovia feliz, apaixonada por uma senhora... que linda e triste história de amor.",
  [822505833202944] = "Sobre o amor, {{Sr.|Sra.}}, o amor é um dos temas eternos da poesia!",
  [822505833202688] = "Então, nunca paro de criar. Acho que enquanto eu escrever o suficiente, alguém acabará por apreciar a minha poesia!",
  [822505833202432] = "No entanto, o Imperador Roselle disse que, contanto que você tente combinar palavras várias vezes, um babuíno de cabelos cacheados também pode escrever grandes poesias.",
  [822505833202176] = "Oh! Obrigado pela sua avaliação; isso me dá muita confiança. Muitas vezes sinto melancolia porque os poetas do passado escreveram muitas obras-primas.",
  [822505833201920] = "Estou surpreso comigo mesmo; meu coração não derreteu imediatamente devido ao desejo.",
  [822505833201664] = "Suspirar! E estou com tanta inveja. Todas as criaturas que vejo estão tão felizes,",
  [822505833201408] = "Esquecer-se de si mesmo e cair, na corrida pela felicidade do coração.",
  [822505833201152] = "Quando vejo a cotovia abrindo as asas e voando alegremente em direção ao sol.",
  [822505833200896] = "Tempestade acima! O que você consertou definitivamente não é apenas um moinho de vento...",
  [822505833200640] = "O vento... traz revelação e tira a poeira.",
  [822505833200384] = "Paixão! Paixão! E mais paixão!",
  [822505833200128] = "Bruxinha, tão sexy e charmosa quanto uma gatinha!",
  [822505833199872] = "Quero muito ver a atuação da Bruxinha!",
  [822505833199616] = "Apresse-se e que seja quinta-feira!",
  [822505833199360] = "Além disso, há um bêbado de coração partido ali. A carteira está apenas esperando; o que você está esperando?",
  [822505833199104] = "As táticas de negócios também são uma parte muito importante!",
  [822505833198848] = "Mas o que isso tem a ver com ser a gangue mais forte...",
  [822505833198592] = "Já investiguei claramente; essa pessoa vende o peixe com batatas fritas mais delicioso da região.",
  [822505833198336] = "Mas você não disse que iríamos investigar a distribuição das forças portuárias, depois ocupar o território e finalmente nos tornar a gangue mais forte?",
  [822505833198080] = "Escute-me. Nossa ação hoje é pegar umas batatas fritas.",
  [822505833197824] = "Haha, só de pensar nas expressões dos rostos desses caras, não consigo reprimir minha empolgação.",
  [822505833197568] = "Claro, estou praticando as palavras do Imperador Roselle. Trinta anos são suficientes para que o rio do destino flua de leste a oeste; não subestimem os jovens pobres!",
  [822505833197312] = "Depois, converse um pouco com seus pais na taverna.",
  [822505833197056] = "Depois, vou ao mercado para ‘encontrar’ suas mães e, inadvertidamente, revelar minha situação atual.",
  [822505833196800] = "Primeiro, vá ficar na porta daqueles conhecidos, hehe, deixe-os com mais ciúmes possível.",
  [822505833196544] = "Com esse dinheiro, é o suficiente para eu viver uma vida boa por um tempo.",
  [822505833196288] = "O Sul é realmente um ótimo lugar para fazer fortuna,",
  [822505833196032] = "Haha, tempestade acima, estou de volta!",
  [822505833195776] = "Cinco centavos também está bom! Amigo! Não vá!",
  [822505833195520] = "Já vi a cena de ganhar dinheiro; só falta o seu investimento!",
  [822505833195264] = "Uma pequena lesão não impedirá meu sucesso.",
  [822505833195008] = "<P_Heart> (Ele realmente não sabe como se arrepender...) </>",
  [822505833194752] = "Em seguida, vá com tudo! Recuperar tudo o que perdi.",
  [822505833194496] = "Então, ganhe algumas rodadas para testar as águas.",
  [822505833194240] = "Primeiro, evite os cães do cassino e entre disfarçado.",
  [822505833193984] = "Empreste-me cinquenta, não, cinco libras, e eu lhe darei um lucro de 100%!",
  [822505833193728] = "Tenho a premonição de que com certeza serei capaz de mudar as coisas desta vez.",
  [822505833193472] = "Porém, olhando para o mar, senti a revelação da tempestade.",
  [822505833193216] = "<P_Heart> (Então era apenas um jogador...) </>",
  [822505833192960] = "Só estou lamentando que eles tenham conseguido resistir à tentação do cassino.",
  [822505833192704] = "Oh não. Isso porque fui espancado por dever dinheiro.",
  [822505833192448] = "Talvez você não saiba, mas minhas pernas ficaram gravemente feridas e doem sempre que chove por causa da umidade.",
  [822505833192192] = "Suspiro, forasteiros, suspiro, imigrantes.",
  [822505833191936] = "Eu também costumava ser um figurão, até que um acidente aconteceu há dois anos.",
  [822505833191680] = "Hehe, isso realmente deixa a gente nostálgico. Isso me lembra da minha idade de ouro.",
  [822505833191424] = "Risco e oportunidade, riqueza e beleza...",
  [822505833191168] = "Vê aquele navio? Esse é o que vai para Bayam.",
  [822505833190912] = "Hmm, vou escrever a resenha assim!",
  [822505833190656] = "No entanto, para a sobremesa de uma senhora, talvez seja o ideal.",
  [822505833190400] = "Em comparação com os produtos de outra padaria, a relação custo-desempenho dos biscoitos aqui é um pouco menor.",
  [822505833190144] = "Quero contar à mamãe as novidades da pequena Sarah; ela definitivamente ficará feliz.",
  [822505833189888] = "É claro que uma família não deve ficar separada por muito tempo! Estamos trabalhando duro!",
  [822505833189632] = "Obrigado! Quero contar à mamãe as novidades da pequena Sarah; ela definitivamente ficará feliz.",
  [822505833189376] = "Estou cheio de esperança em tudo no futuro e acredito que em breve poderemos nos encontrar em Backlund.",
  [822505833189120] = "Estou indo bem. Este mês, o professor Momont até elogiou pessoalmente meu trabalho.",
  [822505833188864] = "...Não é o que pensávamos; o fundo da bolsa aqui é suficiente para cobrir todas as minhas despesas.",
  [822505833188608] = "<P_Heart> (Orgulhosamente) </> Depois lerei a carta da pequena Sarah.",
  [822505833188352] = "Graças à Deusa, ela passou tranquilamente e se matriculou... Falei demais?",
  [822505833188096] = "Suas notas são muito boas e ela tem muita esperança. A professora sugeriu que ela fizesse o exame para a Backlund Technical University.",
  [822505833187840] = "Haha, é uma carta enviada pela minha irmã mais nova, Sarah.",
  [822505833187584] = "Uh, minha querida, acho que não consigo descer.",
  [822505833187328] = "Graças à Deusa! Estou indo agora.",
  [822505833187072] = "...Não vamos falar sobre isso por enquanto, desça rápido, uh, eu te perdôo.",
  [822505833186816] = "Este é o momento em que o destino zomba de mim, mas meu amor permanece sincero.",
  [822505833186560] = "Mas eu não estou em casa!",
  [822505833186304] = "Para você, seja um muro alto ou um abismo, estou disposto a atravessá-lo.",
  [822505833186048] = "Queria clamar pela sua aparição; olha, isso fica bem em frente à sua janela.",
  [822505833185792] = "Ah, não se preocupe, foi o amor que me trouxe aqui.",
  [822505833185536] = "Quero dizer, isso vai me deixar continuar pensando em você.",
  [822505833185280] = "Não esqueça de trazer as histórias de aventura; não se esqueça, com certeza.",
  [822505833185024] = "Minha querida, eu vou.",
  [822505833184768] = "Quando você chegar, lembre-se de me enviar sua carta.",
  [822505833184512] = "Ah... Jessie, sempre sentirei sua falta.",
  [822505833184256] = "Você sabe, não posso ficar aqui sozinho.",
  [822505833184000] = "O voo mais próximo é daqui a três dias.",
  [822505833183744] = "Meu pai decidiu ir para Desi Bay; o médico sugeriu que ele se recuperasse ali por um período de tempo.",
  [822505833183488] = "Elvin definitivamente vai gostar.",
  [822505833183232] = "Hmm... para o buquê grátis, eu gostaria deste porta-flores.",
  [822505833182976] = "Você tem um ótimo olho, senhor! São apenas 6 centavos no total e há um buquê grátis. Qual você gostaria?",
  [822505833182720] = "Deixa eu pensar... esse buquê de rosas vermelhas é para Tasha, e as brancas são para Dana.",
  [822505833182464] = "O preço depende da variedade que você escolher, senhor.",
  [822505833182208] = "Então, você quer entrar conosco, soldado?",
  [822505833181952] = "Crise evitada! Obrigado! Você realmente é um adulto razoável!",
  [822505833181696] = "O que dissemos foi apenas por preocupação com a segurança da casa!",
  [822505833181440] = "Veja, esta fechadura está em tão mau estado por causa da chuva que acabei de dizer que parece fácil de abrir; Eu não quis dizer que iria abri-lo.",
  [822505833181184] = "Oh não! {{Ele|Ela}} ouviu você dizer que a fechadura é fácil de abrir!",
  [822505833180928] = "{{Este belo cavalheiro, você ouviu errado. | Esta nobre senhora, você ouviu errado.}}",
  [822505833180672] = "Shh, shh, do que você tem medo?",
  [822505833180416] = "Não, não é o que você pensa!",
  [822505833180160] = "Esta fechadura também parece muito fácil de abrir...",
  [822505833179904] = "Todos nós já vimos isso; por tantos dias, ninguém morou nesta casa.",
  [822505833179648] = "Mas há uma placa aqui que diz: 'Proibida invasão, os infratores serão severamente punidos'...",
  [822505833179392] = "Quando devemos entrar e brincar?",
  [822505833179136] = "Olá, aconteceu algo?",
  [822505833178880] = "<P_Heart> (Sussurrando) </> 'Cachorro de rua' é a palavra mais odiada; você nunca deve mencionar cães na frente dele!",
  [822505833178368] = "Ainda me lembro de como era quando estava morrendo de fome e comendo ratos; que pobre cachorrinho vadio...",
  [822505833178112] = "Por que outro motivo seria chamado de Gato? Antes de Ryan adotar o gato, sua barraca de carne frita sempre era visitada por ratos.",
  [822505833177856] = "Cat é tão popular quanto Ryan; é realmente ótimo para pegar ratos.",
  [822505833177600] = "{{Sr.|Sra.}}, olha como se chama? Chama-se Gato!",
  [822505833177344] = "O que é muito engraçado?",
  [822505833177088] = "Obrigado pela sua ajuda, {{Sr.|Sra.}}. Este é um pequeno sinal de agradecimento. Aguardo com expectativa o nosso próximo encontro.",
  [822505833176832] = "Hmm, eles também têm bordões facilmente identificáveis, elogiando uns aos outros como <P_Yellow> bem-humorados, espirituosos e engraçados </> .",
  [822505833176576] = "Isso não parece uma tarefa difícil.",
  [822505833176320] = "Espero que você possa me ajudar a descobrir mais humor nesta cidade, e eu lhe darei a recompensa correspondente.",
  [822505833176064] = "Hmm... esse tipo de humor alternativo também pode ser considerado uma forma de arte da conversação.",
  [822505833175808] = "Ao mesmo tempo, isto me permite aprender mais sobre a arte da conversação humana.",
  [822505833175552] = "Fui contratado para coletar algumas conversas humanas interessantes para fornecer inspiração para a escrita de um determinado autor.",
  [822505833175296] = "Eu gostaria de perguntar a você, no âmbito da linguagem humana, essa conversa agora pode ser considerada interessante?",
  [822505833175040] = "Você pode me chamar de “Poirot”.",
  [822505833174784] = "Um gato falante... você é um verdadeiro espectador?",
  [822505833174528] = "Olá, {{Sr.|Sra.}}.",
  [822505833174272] = "Triss, vamos ficar longe dele!",
  [822505833174016] = "Devemos contar ao policial?",
  [822505833173760] = "Ele está com a Gangue do Chapéu? Ele é um ladrão?",
  [822505833173504] = "Sim, essa pessoa está agindo de forma sorrateira.",
  [822505833173248] = "Aike, posso vê-lo aqui todos os dias.",
  [822505833172992] = "Entendido, vou realizar o seu desejo!",
  [822505833172736] = "<P_Heart> (Explique resumidamente a intenção, omitida por enquanto) </>",
  [822505833172480] = "Olá, você precisa de ajuda?",
  [822505833172224] = "<P_Heart> (Devo ir falar com ela...) </>",
  [822505833171968] = "Não me interpretem mal, não tenho medo de injeções.",
  [822505833171712] = "Acho que vou dar outra olhada.",
  [822505833171200] = "Você ouviu os gritos do paciente? Esta clínica está muito errada.",
  [822505833170944] = "Isso não é nada importante.",
  [822505833170688] = "Um amigo me pediu para vir aqui dar uma olhada.",
  [822505833170432] = "Acabei de ouvir que existe uma clínica que cura doenças instantaneamente.",
  [822505833170176] = "Diga-me, o que você está olhando?",
  [822505833168896] = "Para onde você gostaria de ir?",
  [822505833168640] = "Ok, senhor, darei uma resposta à tarde — talvez eu precise encontrar um médium espírita para perguntar pessoalmente o que meu marido pensa.",
  [822505833168384] = "Você sabe... rumores de assombrações e cadáveres vivos no cemitério não são incomuns.",
  [822505833168128] = "Isso significa que se seu marido sair do caixão no meio da noite, a equipe administrativa será responsável por convocar sua alma de volta, sem que você precise se preocupar.",
  [822505833167872] = "O preço... é 1 libra a mais que o terreno vizinho, senhora. Não tenha tanta pressa de balançar a cabeça. A compra do nosso terreno também inclui o 'Seguro de Descanso da Alma' da nossa empresa -",
  [822505833167616] = "Oh, meu piedoso marido certamente não será incomodado. Então, qual é o preço desse terreno?",
  [822505833167360] = "Senhora, este cemitério é um dos melhores lugares do Cemitério Rafael, voltado para o sul, próximo à Catedral de Santa Selena, e você pode ouvir o coral cantando - claro, se seu marido não se importar em ser acordado de vez em quando.",
  [822505833167104] = "Tudo bem, por favor, segure firme!",
  [822505833166592] = "Tudo bem, segure firme.",
  [822505833166336] = "Vá para a rua Champagne.",
  [822505833166080] = "<P_Heart> (Vamos chegar perto da empresa para testar as águas primeiro.) </>",
  [822505833165824] = "<P_Heart> (Perto da Blackthorn Security Company... preciso pedir ajuda ao Vigias Noturnos, mas isso pode me expor.) </>",
  [822505833165568] = "<P_Heart> (Não é possível levar o espreitador até o apartamento; isso arrastaria Melissa e os outros para o perigo!) </>",
  [822505833164544] = "Obrigado, {{Sr.|Sra.}}. O juramento médico não diz “conte as moedas antes de contar o pulso”. Independentemente disso, defenderei a ética de um médico até o fim.",
  [822505833164288] = "Você é um bom médico.",
  [822505833164032] = "Sempre acreditei que o médico pesa os batimentos cardíacos e não as notas na bolsa. Mas algumas pessoas não entendem isso, e não estou disposto a chafurdar na lama com elas.",
  [822505833163776] = "Não aguentei mais e relatei ao jornal. Claro, o resultado foi: minha licença médica foi revogada.",
  [822505833163520] = "No ano passado, o chefe do departamento de farmácia diluiu o remédio que eu havia preparado para pacientes com febre – só para economizar dinheiro e comprar um casaco de vison para sua amante.",
  [822505833163264] = "Seguir as ordens do médico é a melhor forma de me agradecer, senhora.",
  [822505833163008] = "Ah, senhor, simplesmente não sei como lhe agradecer...",
  [822505833162752] = "Vou prescrever-lhe uma receita e o preço será um quinto do que custa no hospital.",
  [822505833162496] = "Olhando para a cor das suas unhas e gengivas, você foi afetado pelo chumbo... você deve deixar este ambiente perigoso.",
  [822505833162240] = "Dê-me sua mão, não tenha medo – trabalhei como médico no Hospital Saint Aestin em Backlund por três anos.",
  [822505833161472] = "Isso não serve! Pretendo ainda aproveitar o entusiasmo dos alunos e realizar mais algumas aulas à noite!",
  [822505833161216] = "Gostaria de tirar um tempo para descansar?",
  [822505833160960] = "Mas tendo dito isso... embora eu goste de ensinar, estou envelhecendo, e estar ocupado de manhã à noite assim é realmente mais do que posso suportar.",
  [822505833160704] = "É uma honra contribuir um pouco para o desenvolvimento da história.",
  [822505833160448] = "Falando nisso, o crédito é todo seu. Graças ao seu lembrete na época, consegui escrever \"Coisas na Idade do Ferro\" e \"Imperador Salomão\", e é por isso que tenho meu sucesso atual.",
  [822505833160192] = "Claro, são aqueles estudantes e leitores excessivamente entusiasmados! Da minha porta ao prédio de ensino, eles estão por toda parte. Até no banheiro, alguém bate na porta para me perguntar sobre a história da Quarta Época.",
  [822505833159936] = "Estou correndo para a aula, realmente não tenho tempo... hmm? Então é você, você me assustou.",
  [822505833159680] = "Olá, {PlayerName}, gostaria de algo?",
  [822505833159168] = "Se você comprá-lo, ele terá dinheiro para me pagar.",
  [822505833158912] = "Esse cara me deve uma quantia enorme de dinheiro. Olha esses quadros aí na porta, foram todos estragados por ele!",
  [822505833158656] = "As dívidas devem ser pagas, claro que é legal.",
  [822505833158400] = "Isso é legal?",
  [822505833158144] = "Você quer comprar esse marinheiro, meu jovem?",
  [822505833157888] = "Deixe esse negociante de arte lidar comigo como quiser, não vou pagar de qualquer maneira!",
  [822505833157632] = "É isso. Não tenho dinheiro e, claro, não quero pagar essa dívida.",
  [822505833157376] = "E então acidentalmente os quebrou.",
  [822505833157120] = "Hum, aconteceu.",
  [822505833156864] = "Acontece que eu queria tocar algumas pinturas com minhas próprias mãos...",
  [822505833156608] = "Não, não, não, por acaso não peguei nada.",
  [822505833156352] = "A palavra “aconteceu” é muito sutil.",
  [822505833156096] = "Sou muito inocente, passei por esta galeria uma noite...",
  [822505833155840] = "Se você quiser ouvir, são 3 centavos por vez, preciso ganhar o dinheiro do resgate.",
  [822505833155584] = "Deve dinheiro?",
  [822505833155328] = "Porque devo dinheiro a esse cara.",
  [822505833155072] = "Por que você está trancado lá dentro?",
  [822505833154816] = "Deusa, nesta forma? Você realmente sabe brincar.",
  [822505833154560] = "Eu me pergunto como Alfie e os outros estão agora...",
  [822505833154304] = "O tempo de espera pela chegada do navio é sempre tão curto que é hora de voltar a trabalhar.",
  [822505833154048] = "Obrigado a todos os generosos membros do público, haverá outra apresentação aqui amanhã!",
  [822505833153792] = "<P_Heart> (desdém) </> Miau... miau!",
  [822505833153536] = "Gato cinza de carvão, olha, outro conhecedor hipócrita chegou.",
  [822505833153280] = "Gato cinza de carvão, gato cinza de carvão, você fica feliz até com um chapéu quebrado como ninho! Gato cinza de carvão, gato cinza de carvão, <P_Heart> (Voz quebrada) </> isso não é culpa sua!",
  [822505833153024] = "Gato cinza de carvão, gato cinza de carvão, você é o mais arrogante da Rua Cruz de Ferro! Você roubou todas as sobras da igreja e até arranhou a bunda do patrulheiro!",
  [822505833152768] = "Um bêbado o xingou por bloquear o caminho, ele chicoteou o rabo e deu uma cambalhota - \"Ei! Velho, as pernas da sua calça já estão rasgadas como um esfregão!\"",
  [822505833152512] = "O lampião de querosene balança na entrada estreita do beco, ele se agacha na sarjeta, roendo as espinhas de peixe frito da noite anterior, os bigodes manchados de óleo preto.",
  [822505833152256] = "Não! Meu coração vai quebrar se eu não ver Fur Ball por um dia. Vá colocar mais avisos.",
  [822505833152000] = "E já contratamos um detetive para encontrá-lo, então com certeza teremos resultados em breve.",
  [822505833151744] = "Senhora, você deveria diminuir a recompensa. Recentemente, muitas pessoas têm agarrado qualquer gato de rua que se pareça com uma bola de pêlo e tentado reivindicar a recompensa.",
  [822505833151488] = "Oh, nosso bom primo! Ele está de volta?",
  [822505833151232] = "Alfie, eu vi o Bill!",
  [822505833150976] = "Existe apenas para proteger sua saúde.",
  [822505833150720] = "Genuíno? Ah, isso é uma raridade – mais raro do que os talheres antigos da nossa família.",
  [822505833150464] = "Mas, mas ele é genuinamente bom para mim...",
  [822505833150208] = "Tipo? Honesto? Minha querida, essas qualidades são tão baratas quanto o ar nos círculos nobres – e nunca nos falta ar.",
  [822505833149952] = "Mãe, por favor, não diga isso, Seth é muito especial. Ele é gentil, honesto e...",
  [822505833149696] = "Minha querida filha, ouvi dizer que você se apaixonou por um plebeu de Feysac? Esta é realmente uma \"surpresa\".",
  [822505833149440] = "Tudo bem, então esta reunião de emergência acabou. Aguardaremos as suas boas notícias, Rei, Ministro dos Negócios Estrangeiros.",
  [822505833149184] = "Houve alguns pequenos episódios, mas este é um assunto particular meu. Para o futuro do Reino Errante, Ministro das Relações Exteriores, irei negociar com você.",
  [822505833148928] = "Eh... espere, Lange, você os conhece?",
  [822505833148672] = "Sim, eles usam nomes relacionados a têxteis. Apenas o líder deles tem um nome decente, chamado Hunter.",
  [822505833148416] = "Hat Gang... isso é Agulha de Ferro e Fio de Seda e os outros?",
  [822505833148160] = "Reporte ao Rei, há outra força aqui chamada “Gangue do Chapéu”, que também é composta por um grupo de órfãos como nós. Talvez possamos pedir ajuda a eles!",
  [822505833147904] = "A coisa mais urgente agora é encontrar um lugar para ficarmos esta noite. Ministro das Relações Exteriores, o senhor conhece esta área do mercado de Tingen, tem alguma boa ideia?",
  [822505833627904] = "Quando danço, meus olhos observam as pessoas – quem quer que eu olhe não será capaz de me esquecer esta noite.",
  [822505833666816] = "Obrigado! Embora sua música fosse... embora isso...",
  [822505833500416] = "Uh... ufa...",
  [804913646963200] = "O que você quer dizer?",
  [822505833365760] = "Isso é ótimo! O Sr. Barista tem muitos doces por lá; fique à vontade para fazer sua escolha. A propósito, por favor, diga ao Sr. Barista que o chá preto precisa ser reabastecido.",
  [822505833404672] = "Essas plantas, algumas vêm do perigoso fundo do Mar Sonia, outras das terras nevadas da fronteira de Feysac... Claro, os mais vendidos ainda são a Grama Perfumada da Noite e a Flor do Sono Profundo amadas pela Deusa.",
  [822505833234688] = "Ele era um herói. Se você quiser saber mais sobre ele, pergunte ao Sr. Leonard.",
  [822505833273600] = "Bom dia, Sr. Franky.",
  [822505833103616] = "Olá, senhor, espero não tê-lo incomodado.",
  [822505833142528] = "...Então pagarei 9 centavos!",
  [822505832974080] = "Carne! Carne! Carne de rato!",
  [822505833011456] = "Não tem problema, se houver uma chance da próxima vez, você pode discutir poesia comigo novamente.",
  [822505833076992] = "Dobby é o cachorrinho mais ágil; ele pode até derrotar facilmente gatos selvagens.",
  [822505833145856] = "Que da próxima vez possamos comemorar nossos aniversários juntos! Hunter, espero que você possa levar esta mensagem a todos da Hat Gang.",
  [822505833145600] = "Ahem, todo mundo tem conceitos diferentes. Lange sempre nos ensina a não roubar; na verdade, também entendo que, como órfão, às vezes roubar é o último recurso.",
  [822505833145344] = "Seria ainda melhor se ele pudesse parar de dar sermões aos meus membros com aquela atitude altiva e poderosa de “bom cidadão”.",
  [822505833145088] = "Lange realmente admira muito você. Quero dizer, nosso rei também acha que você é um bom líder. Não há necessidade de nossas duas organizações órfãs serem tão hostis, certo?",
  [822505833144832] = "Isso é natural. Espero que no futuro, além dos interesses, possamos também desenvolver alguma amizade, Hunter.",
  [822505833144576] = "Não é nada. Não se esqueça, o outro preço para permanecer no território é que você terá que ceder uma parte dos lucros das tarefas à nossa Hat Gang.",
  [822505833144320] = "Enquanto ajudava você a fazer tecidos, também aprendi a fazer chapéus. O presente deste ano para o Ministro Administrativo é um chapéu que fiz!",
  [822505833144064] = "Hoje vim devolvê-lo. Retornamos com sucesso ao nosso próprio reino e também quero agradecer novamente aos membros da Hat Gang em minha capacidade pessoal—",
  [822505833143808] = "Obrigado por ajudar e emprestar temporariamente ao nosso Reino Errante um lugar para ficar. Hunter, você é um bom líder!",
  [862018189977856] = "Espaço reservado",
  [822505833143296] = "Há uma taxa de introdução? Esse...",
  [822505833143040] = "Ei, não seja tão precipitado... há mais uma condição - este trabalho exige primeiro uma \"taxa de introdução\" de 3 soli.",
  [822505833142784] = "Olhe para mim, 8 centavos são suficientes para mim!",
  [822505833142016] = "Escutem, o turno da fornalha essa semana é de 12 horas por dia, 1 soli por dia, quem quer fazer isso?",
  [822505833141760] = "Fase quatro, afirmar que talvez devêssemos ter feito algo antes de chover, mas agora é tarde demais.",
  [822505833141504] = "Fase três, afirmar que talvez devêssemos agir, mas, caramba, começou a chover há dias.",
  [822505833141248] = "A segunda etapa é afirmar que pode haver corrupção inesperada, mas que não devemos agir precipitadamente.",
  [822505833140992] = "Fase um, afirmar que não há nada de errado com o rio Tussock.",
  [822505833140736] = "Qual é a sua ideia?",
  [822505833140480] = "Este problema é bastante complicado. Claro, devemos fazer alguma coisa.",
  [822505833140224] = "Senhor, recentemente houve reclamações públicas de que o \"tratamento de esgoto do Rio Tussock\" não está de acordo com os padrões.",
  [822505833139968] = "<P_Heart> (felizmente) </> Desejo-lhe riqueza também, {{Sr.|Sra.}}!",
  [822505833139712] = "{{Sr.|Sra.}}, vejo que você também está vestido com bastante elegância, por que não vamos ficar ricos juntos?",
  [822505833139456] = "Eu preparei especialmente essa roupa; nas palavras dos moradores de Bayam, este é o símbolo de uma pessoa civilizada!",
  [822505833139200] = "{{Sr.|Sra.}}, ali, o pessoal de Loen tem muito a dizer. Contanto que você use um terno formal, cartola, gravata borboleta e carregue uma bengala, as pessoas ao seu redor serão submissas a você.",
  [822505833138944] = "Isso mesmo! Mesmo que eu não consiga me tornar a pessoa mais rica, em Bayam a vida pelo menos não será pior do que é agora!",
  [822505833138688] = "Parece ótimo, então você vai lá para ficar rico?",
  [822505833138432] = "Esse é o fulcro do domínio colonial do nosso Reino Loen no Mar Sonia, uma das principais cidades! É a terra do tesouro que flui com leite e mel prometidos pelos deuses!",
  [822505833138176] = "Isso mesmo, a “Generosidade”! Levando à \"Cidade da Generosidade\", Bayam!",
  [822505833137920] = "Não vou pegar um navio, senhor. Mas parece que você vai embarcar naquele navio chamado “Generosidade”?",
  [822505833137664] = "{{Sr.|Sra.}}, você também está esperando pela “Generosidade”?",
  [822505833137152] = "O Salto da Fé, é como uma águia voando alto, a sensação da verdadeira liberdade!",
  [822505833136896] = "Isso mesmo! {{Sr.|Sra.}}, você também entende o mistério disso?",
  [822505833136640] = "Não hesite, não recue, mantenha a fé em seu coração. É por isso que também o chamo de “Salto de Fé”.",
  [822505833136384] = "Há algo que preciso prestar atenção?",
  [822505833136128] = "Primeiro, mantenha o corpo reto, depois acompanhe-o com um giro no ar e caia de costas no palheiro.",
  [822505833135872] = "Não precisa se preocupar, tem um monte de feno lá embaixo... quer experimentar? A sensação de saltar é fantástica!",
  [822505833135616] = "Ei, irmão, por que você sempre pula do telhado da igreja? Isso já dura duas semanas inteiras! Tenha cuidado, não quebre a perna!",
  [822505833135360] = "Suspiro, vamos nos concentrar apenas em extrair carvão; quanto mais você escava, mais difícil fica.",
  [822505833135104] = "Pelo menos eles não precisam ser como nós, tendo que contar migalhas até para criar um rato.",
  [822505833134848] = "Esses nobres senhores... eles têm tantas amantes que devem gastar muito dinheiro todo mês, certo?",
  [822505833134592] = "Ei, você sabe por que ele foi expulso? Ele confundiu os nomes de suas amantes!",
  [822505833134336] = "Golden Tindle Borough estava muito animado ontem; um nobre cavalheiro foi expulso de casa pela amante, com apenas uma toalha no corpo todo!",
  [822505833134080] = "Vá embora, vá embora!",
  [822505833133824] = "Shh! Shh! Não fale com Lília!",
  [822505833133568] = "Cale-se! Espalhe boatos novamente e eu vou demitir você! A temperatura do forno número três caiu novamente – quem vai ajustar a válvula de pressão?",
  [822505833133312] = "Não só isso, meu irmão disse que sempre houve barulhos estranhos atrás da fábrica recentemente, como... ossos rangendo!",
  [822505833133056] = "Quando o dedo de Hunter foi esmagado, aquele grito foi mais alto que o som do cano de vapor vazando...",
  [822505833132800] = "Essa fumaça preta queima mais os pulmões do que a bebida forte. Dois pobres coitados tossindo sangue foram levados semana passada, todo mundo viu.",
  [822505833132544] = "Hora de mudança de turno, a escória do forno número três ainda não foi eliminada! Quem quer cobrir o turno? Um centavo extra por hora!",
  [822505833132288] = "Então, quando eu economizar algum dinheiro, comprarei um para Mary e para mim. Embora isso signifique que terei que beber três meses menos cerveja de centeio...",
  [822505833132032] = "Quem sabe, mas é melhor que nada. Todos os trabalhadores do Distrito Norte usam esses amuletos e o índice de acidentes lá é realmente menor.",
  [822505833131776] = "Essa coisa realmente funciona? Não seria uma artimanha inventada por esses charlatões para roubar dinheiro, seria?",
  [822505833131520] = "Estou brincando. No entanto, ouvi dizer que a Catedral de Vapor tem encantos especiais que podem proteger os trabalhadores de ferimentos acidentais.",
  [822505833131264] = "Ei, amigo, não pense em coisas tão sombrias.",
  [822505833131008] = "Se realmente explodisse, quanta pensão você acha que o dono da fábrica daria às nossas viúvas? Seria suficiente comprar uma lápide decente?",
  [822505833130496] = "Acabou, volte... espero te ver na próxima vez.",
  [822505833129984] = "Obrigado pela sua contribuição para a manutenção da higiene pública em Tingen. Os centavos e a medalha são para recompensar seus esforços. A parte seguinte não precisa ser lida...",
  [822505833129728] = "<P_Heart> (Limpa a garganta) </> Aham! Respeitado, entusiasmado, matador de ratos de Tingen... não, Embaixador de Higiene de Tingen... permita-me expressar minha gratidão a você em nome da Companhia de Cooperação de Higiene.",
  [822505833129472] = "Aham... um assassino maduro não precisa da orientação de um lampião a gás... hmm? Esta página não... espere...",
  [822505833129216] = "E seu coelhinho? Urso? Uh, pato? De qualquer forma, não importa o que seja, a vovó consertou para você, exatamente como antes.",
  [822505833128960] = "Lola, olha, bolo de morango, creme duplo!",
  [822505833128704] = "Veja este cabo de martelo com absorção de choque patenteado; garante que, depois de esmagar continuamente as conspirações do inimigo, não afetará a elegância de você segurar sua xícara de chá da tarde!",
  [822505833128448] = "Um olho excepcional! Esta é uma das nossas armas mais vendidas; até os nobres são cativados pelo seu poder e aparência.",
  [822505833128192] = "Compre agora e você também poderá obter serviços de gravura decorativa; seja um brasão ou iniciais de família, pode ser personalizado!",
  [822505833127936] = "Um lindo machado de batalha que pode demonstrar status e força; pode ser usado para lidar com inimigos crescidos e também pode ajudá-lo a manter seu jardim arrumado.",
  [822505833127680] = "Uma escolha atemporal! A arma mais pura, uma excelente forma de convencer as pessoas com a razão! Em qual arma contundente você está interessado?",
  [822505833127424] = "Uma escolha que combina com o seu nobre gosto! Esta arma usa o mais recente design patenteado de espingarda em espiral – ela pode abater patos selvagens e enviar inimigos para encontrar a Deusa da Noite Meia a 800 metros de distância!",
  [822505833127168] = "Elogie seu olho pela qualidade! Esta é a melhor escolha para uma arma linda e poderosa em nossa loja! Prometemos que sua taxa de falha de ignição é 23% menor que a densidade do cabelo do vereador John!",
  [822505833126912] = "A compra agora também vem com um pano de limpeza de armas de alta qualidade – que também pode ser personalizado em uma luva de duelo.",
  [822505833126656] = "Claro, claro, esta é a arma mais requintada e formidável da nossa loja, ajudando você a resolver aqueles problemas deselegantes da maneira mais elegante.",
  [822505833126400] = "Uma arma de fogo suficientemente precisa é ideal para um {{Sr.|Sra.}} elegante como você. Qual você gostaria de ver?",
  [822505833126144] = "Você tem alguma arma que lhe interesse? Terei a honra de apresentá-los a você!",
  [822505833125888] = "Ah, vamos brindar à glória que pode estar embutida em sua peruca! Saúde!",
  [822505833125632] = "Cara, beba essa bebida como se fosse champanhe. Ouvi dizer que o gerente da fábrica usou o salário semanal que retirava de nós para comprar para sua amada esposa um luxuoso prendedor de cabelo.",
  [822505833125376] = "<P_Heart> (imitando um tom aristocrático) </> \"Meu caro, o sabor deste champanhe é verdadeiramente único; o aroma suave de frutas cítricas e cristalizadas é misturado com a quantidade certa de salgado.\"",
  [822505833125120] = "Velho Johnny, seu relógio de bolso diz que são apenas três horas? O suor que derramei é suficiente para encher a torre de champanhe do prefeito!",
  [822505833124864] = "Independentemente disso, ainda quero tentar.",
  [822505833124608] = "Claro, quem não gostaria de nascer em uma mansão? O mundo exterior não é tão fácil.",
  [822505833124352] = "Obrigado pelo seu apoio, {{Sr.|Sra.}}.",
  [822505833124096] = "Concordo com a ideia da jovem; ela tem o direito de escolher sua própria vida.",
  [822505833123840] = "Esforça-se para viver uma vida com fins de semana? Ah, Deusa. Talvez você devesse perguntar quantas pessoas em Tingen desejam se tornar uma nobre dama como você?",
  [822505833123584] = "Dançar com aquele jovem mestre sapo? Não, eu o odeio. Neste outono, apresentarei um relatório à Universidade de Tingen e me esforçarei para mudar minha vida.",
  [822505833123328] = "Tudo bem, devemos voltar para a mansão. A família de Lord Howard estará presente no banquete desta noite, então deixe a empregada escolher um lindo vestido para você...",
  [822505833123072] = "Fim de semana? O que é um fim de semana? Não estamos administrando uma lavanderia.",
  [822505833122816] = "Se você voltasse no fim de semana, não pensaria assim.",
  [822505833122560] = "Ah, é difícil imaginar que uma joalheria pudesse acomodar tanta gente...",
  [822505833122304] = "Esta floricultura vende flores frescas e também vende piedade.",
  [822505833121792] = "Atrás da janela, as Flores Adormecidas florescem silenciosamente.",
  [822505833121536] = "Por que eles chamariam de \"Chá Gelado Doce\"?",
  [822505833121280] = "Ouvi dizer que o nome do gato é \"Sweet Iced Tea\" e a pessoa que o nomeou parece ser a Srta. Audrey e o Sr. Leonard.",
  [822505833121024] = "<P_Heart> (O gatinho olha elegantemente e se espreguiça confortavelmente.) </> Miau.",
  [822505833120768] = "Por que um gatinho não pode ser um anjo! Fofo é Justiça!",
  [822505833120256] = "Várias pessoas da Igreja já vieram me perguntar quem é o meu Anjo... Por que estão tão nervosos?",
  [822505833120000] = "Há também uma loja de xales que lançou vales de consumo conjunto. Felizmente, antes da inauguração desta loja de departamentos, ainda temos muito tempo para calcular o plano de compras mais econômico...",
  [822505833119744] = "Obrigado pelo lembrete, deixe-me ver: compras de necessidades diárias acima de 2 soli se qualificam para troca de alimentos, e os membros podem trocar recibos de compras por grãos de café no mesmo dia por compras de tecidos, por ordem de chegada...",
  [822505833119488] = "Seis horas? Nunca saí do portão da fábrica às seis horas!",
  [822505833119232] = "Não tenha pressa. Ouvi dizer que o desconto “Graça da Deusa” só entra em vigor depois das seis horas, e as necessidades diárias podem ter um desconto extra de 10%!",
  [822505833118976] = "Ouvi dizer que depois que a loja de departamentos Harold abrir, eles terão um evento de desconto especial depois das 15h da primeira sexta-feira.",
  [822505833118720] = "<P_Heart> (animadamente) </> O-obrigado por sua generosidade, senhorita! Prepararemos tudo para você imediatamente!",
  [822505833118464] = "<P_Heart> (Sorri levemente) </> O design deste colar é impressionante. Nesse caso, por favor, embale este colar e todas as novidades da temporada e envie-os para a Mansão do Visconde – quanto à conta, por favor, entregue-a diretamente para minha empregada cuidar.",
  [822505833118208] = "Custa... oitocentas libras?! <P_Heart> (Este preço equivale a quinze anos de salário de um trabalhador comum!) </>",
  [822505833117952] = "Ah, claro, se você estiver interessado, você pode conhecer nosso colar “Louvor da Noite Silenciosa”, com tema da noite e das estrelas, representando a proteção da Deusa, adornado com dezenas de pedras preciosas com corte artesanal incomparável—",
  [822505833117696] = "Realmente vale a pena esperar por isso. Personalize-o como uma coleira; Acho que meu cachorrinho precisa de um presente de aniversário tão elegante.",
  [822505833117440] = "Olhos afiados! Esta pedra preciosa é da mina de diamantes de sangue do Continente Sul e agora custa apenas quinhentas libras de ouro! E também aceitamos personalização da aparência das joias; você pode transformá-lo no estilo que desejar.",
  [822505833117184] = "<P_Heart> (Olha ao redor, o olhar faz uma pequena pausa) </> Esta joia de rubi...",
  [822505833116928] = "<P_Heart> (radiante) </> Seu gosto e porte são incomparáveis!",
  [822505833116672] = "<P_Heart> (Agradavelmente surpreso) </> Quer dizer que joias tão requintadas e únicas custam apenas duzentas libras de ouro agora? Por favor, embrulhe-os juntos – se houver estilos semelhantes, embrulhe um conjunto para mim também.",
  [822505833116416] = "<P_Heart> (Um pouco atordoado, acena rapidamente com a cabeça) </> S-sim, claro! Seu gosto extraordinário é admirável. Além disso, há um conjunto de novos brincos de jade aqui. Durante o evento especial 'Noite Silenciosa', você pode comprá-los por duzentas libras de ouro...",
  [822505833116160] = "<P_Heart> (Sorrisos) </> Este é realmente um preço muito razoável. Por favor, embrulhe para mim.",
  [822505833115904] = "Distinta senhorita, seja bem-vinda. Por favor, permita-me apresentar este colar de pedras preciosas que custa trezentas libras de ouro. Veja, o fogo desta pedra principal—",
  [822505833115648] = "Haha... você sabe, levou apenas duas semanas para consertar o canal de drenagem da piscina de hipopótamos do zoológico no ano passado, mas a proposta de descarga de esgoto para áreas residenciais humanas tem sido discutida há cinco anos...",
  [822505833115392] = "Há também uma proposta de aumento de 40% no orçamento porque a empreiteira afirmou que são necessários processos especiais para lidar com resíduos de perfumes no bairro aristocrático.",
  [822505833115136] = "Por exemplo, sugerindo que o Comitê de Engenharia de Tingen instale filtros de latão nas saídas de esgoto para interceptar os brincos de pérolas perdidos pelas mulheres.",
  [822505833114880] = "Oh? Que tipo de notas \"mágicas\" existem?",
  [822505833114624] = "Olá, {{Sr.|Sra.}}. Como você pode ver, estou pesquisando um projeto de lei mágico sobre tratamento de esgoto.",
  [822505833114368] = "Parece que você está em apuros.",
  [822505833114112] = "Ah, não é de admirar que eles sempre declarem generosamente que essas máquinas são “dispositivos de fé” – acontece que é porque esses dispositivos podem render algumas libras de ouro!",
  [822505833113856] = "Falando nisso... na semana passada, o \"Homem Honesto de Tingen\" relatou o que um colunista que \"se torna honesto depois de ficar bêbado\" disse depois de beber. Ele disse que a conta do inspetor de qualidade recebe diversas “taxas de consultoria técnica” todos os meses...",
  [822505833113600] = "Talvez devêssemos realizar uma inspeção surpresa nas contas da empresa de inspeção de qualidade.",
  [822505833113344] = "Ha! Não é à toa que o representante da empresa de inspeção de qualidade chamou o orçamento de segurança de 'alimentar as máquinas com comida vegetariana'... Receio que a seguir eles proponham alimentar as caldeiras com tortas para reduzir acidentes!",
  [822505833113088] = "<P_Heart> (Lê em voz alta) </> Um homem honesto que participou do leilão de caridade revelou que o relógio de bolso da empresa de inspeção de qualidade chefe é suficiente para ser trocado por vinte conjuntos de válvulas de segurança!",
  [1139094851802368] = "O que?",
  [822505833112576] = "<P_Heart> (Voz baixa) </> Alguns conselheiros sugeriram confiar este assunto à Igreja da Deusa da Noite Eterna para investigação... Você sabe, eles são muito bons em lidar com coisas como espíritos malignos assombrando lugares.",
  [822505833112320] = "Você está dizendo que há uma história oculta por trás disso?",
  [822505833112064] = "Você sabe, todas as caldeiras envolvidas passaram na inspeção de 'Grau Premium' da empresa de inspeção de qualidade no início do ano.",
  [822505833111808] = "Mas todos os relatórios de investigação dizem “incapaz de reproduzir a falha”. Você não acha que isso é suspeito?",
  [822505833111552] = "O \"Homem Honesto de Tingen\" diz que nossas normas de segurança são como as barbas falsas de um teatro de ópera: parecem boas, mas são inúteis.",
  [822505833111296] = "Houve nada menos que sete acidentes com falhas em máquinas de fábrica nos últimos seis meses.",
  [822505833111040] = "Uh... na verdade, acho que muitas coisas não precisam ser explicadas, mas, adeus.",
  [822505833110784] = "<P_Heart> (Assim como ela se desculpou por sentar em um banco público.) </>",
  [822505833110528] = "<P_Heart> (Esta mãe caiu em um longo silêncio, aparentemente pensando em como dizer algo que o mundo inteiro pudesse entender e concordar.) </>",
  [822505833110272] = "Talvez eu deva encontrar uma maneira de deixar isso mais claro, ou devo explicar mais...",
  [822505833110016] = "Ah... me desculpe por causar problemas.",
  [822505833109760] = "Obrigado pela sua compreensão, Excelência, e desejo-lhe felicidades.",
  [822505833109504] = "Além disso, por favor, não diga a ela que sei que ela está lendo romances. Este é o seu segredinho, e espero que ela mesma me conte.",
  [822505833109248] = "Mesmo que esses cursos sejam difíceis e ela não goste deles, ela trabalhará muito pelo bem desta família. Não posso privá-la de mais hobbies.",
  [822505833108992] = "Cici gosta de ler... embora não tenha nada a ver com concurso para funcionário público, ela é uma boa criança.",
  [822505833108736] = "Afinal, sou a mãe dela, Excelência.",
  [822505833108480] = "Então você sabe o que ela está fazendo.",
  [822505833108224] = "Você a viu? Minha filha quieta e bem-comportada, talvez ela esteja escondida em algum lugar lendo um romance agora.",
  [822505833107968] = "Obrigado pela sua companhia, Excelência.",
  [822505833107712] = "Hehe... então preciso trabalhar mais... ou quando a Cici se tornar funcionária pública, encontraremos um lugar que nos receba para morar.",
  [822505833107456] = "Trabalharei mais... ou quando Cici se tornar funcionária pública, encontraremos um lugar que nos receba para morar.",
  [822505833107200] = "Olha, aqui até os donos das barracas não precisam ficar olhando para as barracas o tempo todo, o que antes era inimaginável.",
  [822505833106944] = "Na verdade, ganhamos muito, um ambiente tranquilo, seguro, uma atmosfera que aspira trabalhar na Prefeitura...",
  [822505833106688] = "Obrigado pelo seu conforto, Excelência.",
  [822505833106432] = "Além disso, você já fez concessões.",
  [822505833106176] = "Você pagou por esta casa o mesmo aluguel que seus vizinhos. Você é o mesmo; você não precisa se sentir culpado pela grosseria de outras pessoas.",
  [822505833105920] = "Pfft... Parece que você ainda é uma criança; Cici também costumava ser tão fofa.",
  [822505833105664] = "Cici tem aulas noturnas, e o passeio de carruagem de ida e volta para casa também atrapalha o descanso... Isso nem era problema antes de se mudar, mas agora Cici precisa caminhar até outra rua para pegar a carruagem.",
  [822505833105408] = "E os senhores e senhoras aqui não nos recebem muito bem... Isso também é de se esperar. Não temos roupas boas, há muita bagunça em casa e não temos dinheiro extra para comprar doces para os convidados.",
  [822505833105152] = "Espero que Cici possa ter um ambiente tranquilo para estudar gramática, matemática e direito... <P_Heart> (Suspiros) </> Cada um é muito difícil e o mercado é muito barulhento.",
  [822505833104896] = "Sim, há duas semanas gastei todas as minhas economias para me mudar do 'Mercado de Alface e Carne' para cá.",
  [822505833104640] = "Você acabou de se mudar para cá? É normal estar um pouco desacostumado.",
  [822505833104384] = "<P_Heart> (Suspira suavemente) </> Já comecei a hesitar se mudar para cá foi uma boa escolha... Espero que isso não afete Cici.",
  [822505833104128] = "Ah... você é uma boa pessoa, gentil e generoso.",
  [822505833103872] = "Este é um espaço público... Acredito que qualquer pessoa pode ser ativa aqui, não existe 'perturbador'.",
  [822505833103104] = "Toda vez, tenho medo de nunca mais conseguir rastejar de volta...",
  [822505833102848] = "Sim, uau, meu pai só me manda varrer chaminés.",
  [822505833102592] = "Sua mãe deve ter te amado muito.",
  [822505833102336] = "Ficarei aqui até o amanhecer...",
  [822505833102080] = "Papai é muito ruim comigo e muito ruim com mamãe. Quando mamãe foi embora, foi o bispo Godfrey quem ajudou a enterrá-la aqui...",
  [822505833101824] = "Quando sinto falta da minha mãe, venho aqui...",
  [822505833101568] = "Eu, eu não consigo dormir, sinto falta da minha mãe...",
  [822505833101312] = "O que você está fazendo aqui?",
  [822505833101056] = "Ouvi dizer que eles estão indo muito bem em Backlund e estou feliz por eles. É uma pena o Sr. Klein...",
  [822505833100800] = "O Sr. Klein me ensinou a fazer muitos pratos especiais, o que fez com que até o exigente barão os elogiasse incessantemente; O Sr. Benson me forneceu uma carta de recomendação como funcionário público; e a senhorita Melissa tem me escrito, me incentivando a seguir minha carreira.",
  [822505833100544] = "Você os conhece? Graças ao tempo que passei como empregada doméstica na casa dos Moretti, consegui me tornar chef de um barão!",
  [822505833100288] = "Definitivamente!",
  [822505833100032] = "Crianças, lembrem-se, embora não possamos pagar por essas refeições agora, um dia estaremos sentados lá.",
  [822505833099776] = "Tudo bem, tudo bem, vamos praticar com toalhas quando chegarmos em casa.",
  [822505833099520] = "Eu também quero aprender, mãe, me ensina!",
  [822505833099264] = "Mamãe já aprendeu a usar guardanapo.",
  [822505833099008] = "Quando papai se tornar capataz, poderei trazer você aqui para comer! Claro, temos que aprender com antecedência para não sermos ridicularizados por esses senhores e senhoras.",
  [822505833098752] = "Pai, por que viemos ver os outros comerem todos os dias?",
  [822505833098496] = "Hmph, você vai se arrepender!",
  [822505833098240] = "Comparado aos seus juros mensais de 15%, prefiro confiar no banco.",
  [822505833097984] = "Amigável? Eles só se preocupam com garantias. Olha, posso te emprestar dinheiro aqui sem qualquer garantia.",
  [822505833097728] = "Sr. Morrison, agradeço sua gentileza. Mas as coisas são diferentes agora; Sua Majestade Covington II ordenou que os bancos fossem muito mais amigáveis ​​com os pequenos comerciantes.",
  [822505833097472] = "Ouvi dizer que você precisa de uma quantia em dinheiro para expandir sua mercearia. Esses bancários arrogantes só vão fazer você fugir à toa, por que não...",
  [822505833097216] = "Você não é o mesmo? Não restam muitas pessoas gentis como nós.",
  [822505833096960] = "Nossa, você ainda é tão gentil e misericordioso.",
  [822505833096704] = "Lembrado por você, devo também preparar pão branco para o tutor. A criança está com tanta fome que seu rosto fica pálido e ela engole em seco toda vez que vê nosso chá da tarde.",
  [822505833096448] = "A melhor parte é que os estudantes universitários sempre fingem ser pessoas decentes. Veja, eles usam casacos remendados, mas ainda precisam endireitar as costas, fingindo ser cavalheiros.",
  [822505833096192] = "Eles são simplesmente uma pechincha! E eles são especialmente diligentes; se as notas da criança não forem boas, eles até tomam a iniciativa de oferecer o reembolso. Deusa abençoe!",
  [822505833095680] = "Minha querida, você sabe? Recentemente descobri uma boa ideia: convidar aqueles estudantes pobres da Universidade de Tingen para serem tutores.",
  [822505833095424] = "Os admiradores da atriz principal, Srta. Mountbatten, podem não ter dinheiro para comprar uma passagem de terceira classe, mas para roubar um pôster solitário? A agilidade deles faria com que os guardas da Prefeitura se sentissem inferiores!",
  [822505833095168] = "Os pôsteres de \"The Betrayer's Ring\" estão desaparecendo tão rápido quanto uma bicicleta destrancada!",
  [822505833094912] = "Porque o bêbado que está se gabando aí é o meu velho, e tenho que evitar que ele caia!",
  [822505833094656] = "Por que eu não iria embora? Tempestade acima, espero que você possa fazer bom uso desses seus lindos olhos.",
  [822505833094400] = "Se você não quer ser atingido repentinamente por uma garrafa de vinho na cabeça, aconselho que fique longe daqui.",
  [822505833094144] = "Riel... não deixou nada para trás.",
  [822505833093888] = "Entendo muito bem os sentimentos deles e os invejo por ainda conseguirem encontrar lembranças de pessoas importantes.",
  [822505833093632] = "Aqueles que estão vivos muitas vezes precisam de algo para comemorar aqueles que já faleceram.",
  [822505833093376] = "Como você pode ver, o final não é perfeito... então ele me confiou para usar as lembranças da garota e a aliança que ele preparou para fazer um anel totalmente novo, para homenagear para sempre seu falecido amante.",
  [822505833093120] = "É o cabelo de sua falecida noiva. Aquela corajosa garota morreu na Guerra de Feysac, e meu cliente a procura há muitos anos.",
  [822505833092864] = "O material é na verdade... cabelo?",
  [822505833092608] = "Desculpe... esse não está à venda; é uma peça personalizada para um cavalheiro.",
  [822505833092352] = "Eles fazem mais uso de artesanato moderno e complexo, e as formas são mais nítidas e exclusivas. Engrenagens, geometria e estrelas farão você parecer nobre e moderno, e o preço também é muito amigável.",
  [822505833092096] = "Se você é uma pessoa moderna, pode dar uma olhada nas joias à esquerda.",
  [822505833091840] = "Eles são todos em um estilo clássico e lindo, com ouro, pérolas e diamantes formando buquês, borboletas e Ouroboros representando a eternidade. São peças de joalharia muito decentes e com uma presença forte.",
  [822505833091584] = "Se você é uma pessoa romântica, pode dar uma olhada nos colares e pentes de cabelo à direita.",
  [822505833091328] = "Se você quiser um estilo mais especial, ficarei feliz em criar um para você.",
  [822505833091072] = "Olá, o que você gostaria? Um colar? Um broche? Você também pode apenas dar uma olhada.",
  [822505833090816] = "Hum? Parece... cabelo humano?",
  [822505833090560] = "Cabelos dourados pálidos entrelaçados em flores, envolvendo uma pérola redonda e quente, como um buquê de confissão dado a um amante.",
  [822505833090304] = "Tendo como pano de fundo pedras preciosas brilhando com um brilho caro, o anel na minha frente é muito especial.",
  [822505833090048] = "...Quem exatamente está comprando?",
  [822505833089792] = "<P_Heart> (Inconscientemente olha para a lista de preços) </> Terno de alta qualidade... 7 libras, 9 libras, 6 libras 8 sol...",
  [822505833089536] = "Quanto?! Tão caro? Está na moeda Loen?",
  [822505833089280] = "Uma camisa impecável e rígida que exala uma sensação de decência, ao preço de 9 libras e 15 centavos.",
  [822505833089024] = "Feito em seda, com estilo elegante e refinado, ao preço de 6 soli.",
  [822505833088768] = "Que cruel! Para realmente mandar as crianças para a escola!",
  [822505833088512] = "Ouvi dizer que a Loen Charity Foundation veio de Backlund; eles podem patrocinar crianças para continuarem seus estudos.",
  [822505833088256] = "Já é hora de descansar, companheiro. Ei, o que é essa Fundação de Caridade Loen?",
  [822505833088000] = "Pare de procurar, ainda faltam dois carrinhos de cartazes para afixar!",
  [822505833087744] = "O cachorrinho não diz nada, apenas continua dormindo.",
  [822505833087488] = "Você seleciona cuidadosamente meio quilo de carne e, cheio de ansiedade, enfia o dinheiro debaixo da barriga do cachorro.",
  [822505833087232] = "Tempestade acima... esse era na verdade o desejo do meu marido. Hum... sou apenas a esposa dele, só preciso apoiá-lo.",
  [822505833086976] = "<P_Heart> (Você percebe que a luz surgindo em seus olhos gradualmente se acalma.) </>",
  [822505833086464] = "Justamente por isso a senhora investiu em muitas joalherias como Miss Alice.",
  [822505833086208] = "Somente ficando mais barato poderá ser comprado por mais pessoas. Desde que um número suficiente de pessoas compre, poderemos definir o que está na moda – que vale muito mais do que as matérias-primas.",
  [822505833085952] = "De jeito nenhum, minha querida, as joias precisam ser mais baratas.",
  [822505833085696] = "A acumulação de riqueza está ultrapassada; ele deve ficar em segurança em um cofre. De agora em diante o artesanato está na moda, e a dona Alice sempre teve faro para isso.",
  [822505833085440] = "No passado, apenas a nobreza poderia definir um design excelente, mesmo que fosse muito pesado e monótono – um empilhamento manual de grandes quantidades de ouro, pérolas e corais...",
  [822505833085184] = "Embora eles não parecessem felizes quando se mudaram... Acho que todos que saem da Rua Daffodil se sentem relutantes.",
  [822505833084928] = "Isso sempre me lembra a família Moretti – eles eram meus vizinhos naquela época. O filho mais velho daquela família fez o primeiro exame para funcionário público e agora mudou-se para Backlund.",
  [822505833084672] = "A oportunidade não falhará com aqueles que estão preparados. No momento em que foi inaugurado o concurso para funcionários públicos, o conhecimento passou a ser o melhor auxílio para o cidadão comum.",
  [822505833084416] = "...Vamos esquecer completamente essa guerra, Anna.",
  [822505833084160] = "A senhora disse uma vez que aqueles que aproveitaram a oportunidade se mudaram para lugares mais ricos, North Borough, ou Backlund, e aqueles que não o fizeram... desculpe, a senhora não disse isso.",
  [822505833083904] = "É um lugar aconchegante, mas a maioria dos meus vizinhos daquela época se mudou. É uma pena...",
  [822505833083648] = "A loja de roupas do Sr. Walter, o Café da Srta. Sanga, minha antiga casa... ah, tudo na Rua Daffodil é tão nostálgico...",
  [822505833083392] = "Mesmo depois de se mudar para as vilas mais ricas de North Borough, a senhora ainda volta com frequência.",
  [822505833083136] = "Obrigado pelo elogio. Os designs de joias da senhorita Alice são excelentes o suficiente.",
  [822505833082880] = "Você tem um bom olho.",
  [822505833082624] = "Meu irmão é bom em... ah, ah, meu irmão é ainda melhor em fazer vestidos do que minha mãe! Vestidos de meninas, vestidos de irmãs mais velhas e até chapéus, luvas e corpetes de senhora!",
  [822505833082368] = "Na verdade, mamãe pode fazer os estilos mais comuns. Basta descrever o que você quer e mamãe pode fazer isso. Ela cobra apenas pelo tecido e um pouco de mão de obra!",
  [822505833082112] = "Mamãe sabe fazer roupas decentes para adultos, como ternos para cavalheiros, muito adequados para trabalhar na Prefeitura ou no Distrito Universitário.",
  [822505833081856] = "Meu? Ficarei feliz em atendê-lo, mas, por favor, espere até eu ficar um pouco mais velho – pelo menos até poder manusear a tesoura e o ferro.",
  [822505833081600] = "Ah, certo, não fale com ele casualmente e definitivamente não discuta com ele; ele ficará tão ansioso que chorará.",
  [822505833081344] = "Mas mamãe diz que ele será um ótimo alfaiate. Você está procurando a mamãe para fazer suas roupas, ou meu irmão?",
  [822505833081088] = "Você quer dizer Credo? Ele é meu irmão mais velho, o tipo de irmão que só consegue falar normalmente quando está falando com tecido.",
  [822505833080832] = "Olá! Esta é a Hat Shop de Maria e o Anjo, mas por favor tome cuidado e não assuste os passarinhos.",
  [822505833080576] = "...Então, desculpe, eu... eu não... bem, eu não sou bom em receber... não se importe comigo.",
  [809242973970432] = "Como é, como é? Como foi o feedback sobre minha nova receita?",
  [809242974011392] = "Espero que minha aprendiz possa retornar em breve.",
  [822505833080320] = "F-para chapéus e roupas personalizadas, por favor procure minha mãe... ou minha irmã mais nova.",
  [822505833080064] = "Esta é... a loja de chapéus de Mary e o Anjo...",
  [822505833079808] = "Olá...",
  [822505833079552] = "Talvez esta floricultura venda não apenas flores frescas, mas também piedade.",
  [822505833079296] = "Eles estão rodeados de hortelã, rosas e limões, cuidadosamente embrulhados em buquês - do tamanho certo para levar para a igreja Vigias Noturnos'.",
  [822505833079040] = "Pela janela limpa, você vê as Flores Adormecidas desabrochando serenamente.",
  [822505833078528] = "Claro, meu senhor, caso contrário, por que eu alugaria meu velho amigo?",
  [822505833078272] = "Ainda estou esperando para pagar o aluguel, senhor. Mesmo se eu estivesse sentado na porta da Associação de Melhoria de Habitação da Classe Trabalhadora agora, eles ainda me fariam dormir na rua se eu não tivesse dinheiro!",
  [822505833078016] = "...Isso é uma taverna! Não posso me dar outra chance de gastar dinheiro!",
  [1139165181885696] = "Senhor, onde você está indo?",
  [822505833077504] = "Dolby é meu bom amigo, é obediente e forte, um bom caçador.",
  [822505833077248] = "Está para alugar! Alugue - não está à venda!",
  [822505833076480] = "Você é uma pessoa gentil e educada, viverá uma vida boa.",
  [822505833076224] = "Não se preocupe, meu senhor, sua voz quando fala comigo é tão leve quanto uma folha caindo.",
  [822505833075968] = "Só um momento, só mais um pouco, está bem. Vou trabalhar duro. Quando eu me tornar funcionário público, mamãe não terá que trabalhar tanto...",
  [822505833075712] = "Mas preciso fazer aulas de reforço de gramática, direito e matemática... isso custa uma quantia significativa de dinheiro, além de toda a minha energia.",
  [822505833075456] = "Custa algumas taxas de inscrição e exames, meu senhor.",
  [822505833075200] = "Exame para funcionário público? Custa muito dinheiro?",
  [822505833074944] = "<P_Heart> (Sorriu envergonhado) </> Minha mãe não me permite mais comprar romances; todo o dinheiro em casa precisa ser preparado para o exame unificado de funcionários públicos.",
  [822505833074688] = "\"O Morro dos Ventos Uivantes\", tem uma leitura bizarra e romântica, muito cativante... mas este já é um livro muito antigo da Sra. Fors.",
  [822505833074432] = "...Oh, por favor, me perdoe, não percebi sua chegada. Vou ocupar este espaço por mais algum tempo.",
  [822505833073664] = "Volte, eu não gosto de piadas.",
  [822505833073408] = "...Heh, você não cheira como um rato.",
  [822505833073152] = "Coloque-os na gaiola ali, por favor.",
  [822505833072896] = "Eu sinto o cheiro, o cheiro do pecado, da lascívia e da peste...",
  [822505833072640] = "Tosse, quem é?",
  [822505833072384] = "<P_Heart> (As batidas pararam e, depois de três respirações, um som abafado veio de trás da porta bem fechada.) </>",
  [822505833072128] = "O que você está olhando! Não olhe para mim! Wuu... não olhe mais para mim...",
  [822505833071872] = "Wuu wuu... ele é funcionário da Prefeitura! Um grande tiro! Wuu wuu... como posso me comparar a ele...",
  [822505833071616] = "Oh... ela foi embora... ela ainda foi embora...",
  [822505833071360] = "Eles exalam simultaneamente o cheiro de roupa seca ao sol, o cheiro de álcool e a atmosfera de vida entrelaçada com lágrimas e saliva.",
  [822505833071104] = "Gabardinas e cobertores comuns, tão comuns que aparecem em quase todos os lares de Tingen.",
  [822505833070848] = "Claro, ele deveria se tornar um carpinteiro como eu. Afinal, a madeira sempre pode ser transformada em alguma coisa, enquanto a Lower Street já está além da economia.",
  [822505833070592] = "Parece que você não aprova?",
  [822505833070336] = "Assim como o filho de um peixeiro nove em cada dez vai se tornar peixeiro, o pobre Mountbatten também quer ser policial.",
  [822505833070080] = "Ah, você deve ter ouvido falar do pai dele - <P_Yellow> Beach Mumbaton </>, o policial responsável pelo patrulhamento da Lower Street.",
  [822505833069824] = "Por favor me perdoe; meu filho está em uma idade travessa e vou discipliná-lo assim como consertaria seu pai.",
  [822505833069568] = "<P_Heart> (Este é um artefato selado? Ou há uma intervenção de Beyonder fatores? Ou talvez haja uma maneira especial de desligá-lo... Em qualquer caso, não há como afetar esta fornalha teimosa por enquanto; voltarei mais tarde.) </>",
  [822505833069312] = "O fogão apagou-se por um momento e depois acendeu-se novamente.",
  [822505833069056] = "Uma chaleira barulhenta, explodindo de vapor devido à feroz batalha entre a água e o fogo.",
  [822505833068800] = "Você sente que perdeu alguma coisa.",
  [822505833068544] = "Acordando na lama, os dois homens com quem você bebeu não foram encontrados em lugar nenhum.",
  [822505833068288] = "Você ficou muito bêbado.",
  [822505833068032] = "Saúde...",
  [822505833067776] = "Saúde! Para o nosso encontro!",
  [822505833067520] = "<P_Heart> (Pisca para você) </> Certo? Bom jovem.",
  [822505833067264] = "Vir! Vamos tomar outra bebida! Jogue fora todas as suas preocupações, hoje é um dia que vale a pena comemorar!",
  [822505833067008] = "É também o aniversário de um ano de nosso encontro!",
  [822505833066752] = "Ah... obrigado pelo seu conforto. Na verdade, hoje é o aniversário de um ano em que deixei minha antiga casa no Continente Sul e vim para Loen.",
  [822505833066496] = "Por favor, não fique triste, contanto que você queira, você sempre pode voltar.",
  [822505833066240] = "Que a tempestade esteja acima, meu amigo está com saudades de casa...",
  [822505833065984] = "Wuu... minha cidade natal do outro lado do mar... wuu...",
  [822505833065728] = "Oh... minha saudade do Continente Sul, minha cidade natal do outro lado do mar...",
  [822505833065472] = "Ah – o vinho amargo de Hagati, o gosto das lágrimas e do suor de uma donzela –",
  [822505833065216] = "Irmão, venha tomar um gole, vinho amargo das pastagens Hagati, o sabor é tão refrescante quanto ser abraçado por libras de ouro!",
  [822505833064960] = "Oh, minha casa no Continente Sul, sinto falta dela a cada momento.",
  [822505833064704] = "Claro, olhe para minha pele morena, ouça meu sotaque antigo.",
  [822505833064448] = "Senhor, você é do continente sul?",
  [822505833064192] = "Foi absolutamente fantástico lá – selvas transbordando de especiarias, terras que vomitavam ouro, garotas gostosas e meu amigo moreno aqui na minha frente!",
  [822505833063936] = "Jovem, talvez você já tenha ouvido falar do Continente Sul?",
  [822505833063680] = "Haha! Jovem gentil e entusiasmado, tome um drink com esse velho e esse amigo que veio de longe!",
  [822505833063424] = "É você, é você, além do você deslumbrante, para quem mais posso ligar?",
  [822505833063168] = "Isso porque... ah, como eu poderia saber sobre esses assuntos caipiras? Eu só me importo com quantos centavos posso conseguir, meu senhor.",
  [822505833062912] = "O que os vendedores ambulantes de bebidas querem com isso?",
  [822505833062656] = "Se você está apenas querendo ganhar algum dinheiro rápido para comprar bebidas, pode levar aquela bexiga de porco para lá; os vendedores estrangeiros de bebidas alcoólicas na Lower Street ficam muito felizes em comprar produtos a granel.",
  [822505833062400] = "Na verdade, tecidos como esse podem ser vendidos para quem conserta velas nas docas, mas o pedaço que você tem na mão é branco, então coletar um lote para vender a uma fábrica de papel teria um preço melhor.",
  [822505833062144] = "Meu senhor, você não parece fazer isso com frequência.",
  [822505833061888] = "<P_Heart> (Olhando para o lixo brilhante) </> Hmm... esqueça essa maldita curiosidade.",
  [822505833061632] = "Uh... na verdade, não estou aqui para roubar seu negócio.",
  [822505833061376] = "Claro... a fábrica de papel exigirá que você colete um pouco mais. <P_Heart> (Ela virou de lado para bloquear a bolsa atrás dela) </>",
  [822505833061120] = "Meu senhor... se quiser, você pode vendê-lo para a fábrica de papel no sul, para não ter que pagar a taxa de intermediário ao Rei do Lixo.",
  [822505833060864] = "Você casualmente pegou um pedaço de pano que parecia relativamente limpo, sem pensar onde descartá-lo.",
  [822505833060608] = "Tudo bem, agora todo esse lixo é meu!",
  [822505833060352] = "<P_Heart> (Ela lambeu os lábios sem jeito, seus pés sujos se movendo para frente e para trás. Depois de hesitar por um longo tempo, ela finalmente saiu.) </>",
  [822505833060096] = "Não me incomode, estou pensando.",
  [822505833059840] = "...Uh, Vossa Excelência, talvez você...",
  [822505833059584] = "Até o lixo tem sua hierarquia, e seu olhar perspicaz rapidamente coloca etiquetas de preço nele.",
  [822505833059328] = "Ela franziu os lábios, seu olhar muito vigilante. Ela não se atrevia a competir com você pelas coisas aqui, mas também não suportava desistir delas.",
  [822505833059072] = "A diferença é que eles raramente veem um cliente como você – a velha que está por perto, que não consegue deixar de olhar para você, é seu cliente regular.",
  [822505833058816] = "Velas do tamanho de uma unha, trapos manchados com líquido viscoso, latas vazias e bexigas de porco... as mercadorias aqui são tão deslumbrantes quanto em uma loja.",
  [822505833058560] = "Lutar contra o mal é muito divertido.",
  [822505833058304] = "Quantas vezes perdido? Quantas vezes ganhou? Ninguém se lembra. Você parecia ter lutado até o fim do mundo, o fim do universo.",
  [822505833058048] = "A barulhenta mesa de jogo ficou em silêncio por um momento, depois tornou-se barulhenta novamente, e você jogou as cartas para frente com força com a força de vontade que usou para se libertar do casulo vermelho.",
  [822505833057792] = "Deixe-me cuidar disso.",
  [822505833057536] = "<P_Heart> (Alerta) </> O que você quer?",
  [822505833057280] = "Você não aguentou e finalmente se aproximou e ficou atrás dele.",
  [822505833057024] = "O jogo de cartas foi longo, tão longo quanto a tristeza que emanava do homem que havia perdido quinze partidas seguidas.",
  [822505833056768] = "Você se sentou ao lado do cachorrinho, e ele te olhou confuso, permanecendo educadamente ao seu lado. Vocês dois, quietos, ficaram em oposição à barulhenta mesa de jogo.",
  [822505833056512] = "Tenha simpatia por esse homem que está perdendo o dia todo, estranho, esse é o raro momento de folga dele! Hahaha!",
  [822505833056256] = "Ei, seu pirralho aí, fique quieto enquanto brinca com o cachorro! Não posso mais me dar ao luxo de perder!",
  [822505833056000] = "Não fale em cuidar das crianças – rápido, rápido, tenho que ir para casa em cinco minutos, ainda dá tempo para mais uma rodada antes disso!",
  [822505833055744] = "Outra rodada? Ou você vai voltar para cuidar das crianças?",
  [822505833055488] = "Cachorro nasce para latir... você perdeu, amigo, não leve a raiva de cuidar de um bebê para cima do cachorro.",
  [822505833055232] = "Ei, Hunter, controle seu cachorro, ele é tão barulhento quanto um bebê recém-nascido!",
  [822505833054976] = "O cachorrinho soltou uma série de latidos bastante indelicados.",
  [822505833054720] = "Uau ~ Uau au ~",
  [822505833054464] = "Choramingar-",
  [822505833053952] = "<P_Heart> (Um cachorrinho comum, vestindo um casaco preto e branco, olhando para você com expectativa) </> Uau—",
  [822505833053696] = "Já estou farto! Quer sejam ostras frescas, ostras transformadas em dinheiro ou um marido que cheira a ostras!",
  [822505833053440] = "Deusa, um dia eu me mudarei para um lugar limpo no bairro Norte e contratarei dez... não, pelo menos vinte empregados da Rua Daffodil para limpar e patrulhar de manhã até a noite, e absolutamente não permitirei que nenhuma ostra invada minha vida!",
  [822505833053184] = "Quando aqueles bêbados da Lower Street começarem a trabalhar com soluços, o fedor de ostras e o exército de gatos e ratos terão inundado minha pobre casa.",
  [822505833052928] = "Limpadores? Você quer dizer os faxineiros?",
  [822505833052672] = "Por que não deixar o lixo para os faxineiros como outros donos de barracas?",
  [822505833052416] = "Deusa, por que diabos eu tenho que viver essa vida nojenta!",
  [822505833052160] = "Vender ostras durante o dia, limpar ostras à noite, transportar ostras à noite, ostras, ostras, é tudo ostras!",
  [822505833051904] = "Deve haver livros relevantes na biblioteca, vamos dar uma olhada!",
  [822505833051648] = "“Teste de Capacidade Administrativa” é a abreviatura de concurso público. Suspiro, nem sei o que essa matéria testa...",
  [822505833051392] = "O que é um 'Exame para Função Pública'?",
  [822505833051136] = "Ainda não terminei de memorizar gramática e literatura clássica e só resolvi metade dos problemas de matemática e lógica. Ouvi dizer que este ano será adicionado um “Teste de Aptidão Administrativa”, estou enlouquecendo!",
  [822505833050880] = "As inscrições para o exame unificado de servidores públicos deste ano já começaram, você está pronto?",
  [822505833050624] = "<P_Heart> (Suspiro...) </> Mamãe te ama muito, isso não é suficiente? Vou te fazer companhia até a mamãe sair.",
  [822505833050368] = "Jimmy, {{Sr.|Sra.}}... Mamãe trabalha como empregada doméstica durante o dia e tem que sair para dançar com roupas muito frias à noite. Ela disse que me enviaria para ser aprendiz quando economizasse dinheiro suficiente. Mas... mas a polícia disse que mamãe fez algo ruim... mamãe é uma pessoa má?",
  [822505833050112] = "Qual o seu nome?",
  [822505833049856] = "Mamãe disse que precisava falar com o policial e que sairia logo. Mas já faz muito tempo...",
  [822505833049600] = "Pequeno, você está esperando sua mãe?",
  [822505833049344] = "Então, além das plantas que eles preferem, os deuses ainda têm preferências por metais...",
  [822505833049088] = "Haha, isso certamente seria atraente.",
  [822505833048832] = "Vocês, crentes da Deusa, têm sorte, pois joias de prata são tão decentes de usar. Acredito no Deus do Vapor e das Máquinas, Seu metal simbólico é o bronze... Não posso sair com uma armadura de bronze completa, posso?",
  [822505833048576] = "Olha, minha bolsa feita sob medida. Ele usa prata pura para incrustar estrelas, então carregá-lo comigo é como ser abençoado pela Deusa.",
  [822505833048320] = "Shh! Você ousa dizer isso...",
  [822505833048064] = "A batalha foi vencida, <P_Heart> (Limpa o rosto) </> mas é uma pena que nossos companheiros não tiveram tanta sorte. Só sobramos nós dois de todo o time. Se o Cardeal tivesse chegado um pouco antes...",
  [822505833047808] = "Felizmente, o bispo desceu; assim que ele pisou no convés, a direção do vento mudou e a artilharia parou de funcionar mal, atingindo tudo o que visava, foi realmente divino!",
  [822505833047552] = "<P_Heart> (Sorriso amargo) </> Naquela época, eu realmente me senti amaldiçoado, até o clima favoreceu os Feysacianos.",
  [822505833047296] = "Aqueles malditos canhões Feysac nos perseguiam como se tivessem olhos, enquanto os nossos explodiam um após o outro!",
  [822505833047040] = "Na guerra de há dois anos, se não fosse aquele Cardeal da Igreja, já teríamos sido comida de peixe há muito tempo.",
  [822505833046784] = "Todo War Memorial Day, viemos agradecer ao grande Senhor das Tempestades!",
  [822505833046528] = "O que vocês dois estão fazendo?",
  [822505833046272] = "Parece que deveria mudar minha opinião sobre os seguidores da Tempestade.",
  [822505833046016] = "O Senhor das Tempestades é tão inclusivo quanto o mar. Ele não se importa se quem está ajoelhado diante Dele é um nobre ou um marinheiro, porque diante do vasto mar somos todos igualmente pequenos.",
  [822505833045760] = "Isso te surpreende? Não são apenas marinheiros e piratas que acreditam no Senhor das Tempestades. A família Augustus acredita no “Senhor das Tempestades” desde a fundação de Loen, e minha família também cresceu por causa da navegação.",
  [822505833045504] = "Nobres no palácio?",
  [822505833045248] = "Ah, não precisa ser reservado. Desde os trabalhadores que descarregam na área portuária até os nobres no palácio de Backlund, a Igreja do Senhor das Tempestades está aberta a todos.",
  [822505833044992] = "Jovem, você já esteve na Igreja do Rio e do Mar?",
  [822505833044736] = "Aos irmãos que ainda estão vivos! E para aqueles... infelizes que alimentaram os peixes!",
  [822505833044480] = "Seu pai era um homem durão quando estava vivo, aprenda com ele!",
  [822505833044224] = "Ei, garoto, não pense nisso. Todos sabemos que o mar exige um preço, mas também dá recompensas.",
  [822505833043968] = "Ouvi dizer... naquela tempestade na Ilha Eskerson no ano passado, vinte navios afundaram...",
  [822505833043712] = "O mais difícil não é a longa viagem, é lembrar quem gosta de peixe e quem odeia frutos do mar... <P_Heart> (Arrepios) </> Nunca mais cometerei esse erro!",
  [822505833043456] = "Corro pelas rotas marítimas, permanecendo no arquipélago durante meses seguidos. Muitas pessoas encontram mulheres locais nos portos onde atracam e fazem uma segunda casa.",
  [822505833043200] = "Haha! Você me ouviu, isso mesmo, dois portos, duas casas, duas mulheres gentis e boas!",
  [822505833042944] = "Que a tempestade esteja acima, abençoe-me para retornar em segurança para minhas esposas.",
  [822505833042688] = "Hmph, e daí se for ruim? Ouvi dizer que 'Storm Bringer' canta muito mal também!",
  [822505833042432] = "Ainda não está certo, você canta muito mal.",
  [822505833042176] = "Impacto-!",
  [822505833041920] = "Ei, por que você está arrastando suas palavras de novo?",
  [822505833041664] = "Isso é porque você é ignorante. Ouvi dizer que há piscina, salão de baile e quadra de squash no navio. Tsk tsk, é praticamente um palácio à beira-mar! Assim que eu economizar dinheiro suficiente, com certeza irei dar uma olhada.",
  [822505833041408] = "<P_Heart> (Encolhe os ombros) </> Diga o que quiser. De qualquer forma, eu não gastaria uma fortuna para viajar em um navio tão chamativo.",
  [822505833041152] = "Que época é essa, ainda falando em bater em icebergs! Além disso, os cartazes estão afixados na igreja, por isso deve ter a bênção da Igreja das Tempestades.",
  [822505833040896] = "Um navio deste tamanho seria fatal se batesse em alguma coisa, como um iceberg...",
  [822505833040640] = "Esta é a tecnologia mais recente; Ouvi dizer que só as placas de aço são terrivelmente grossas. E olhe a escala, dez baralhos!",
  [822505833040384] = "Estou no mar há vinte anos e nunca vi um navio se gabar assim. Se você me perguntar, espero que não afunde em sua viagem inaugural!",
  [822505833040128] = "Boa sorte! Eu irei te encontrar se precisar de um.",
  [822505833039872] = "Se precisar de um retrato, pode vir me procurar. Mas irei embora em breve; é realmente emocionante.",
  [822505833039616] = "Boa sorte!",
  [822505833039360] = "Proteção da Deusa, ganhei um ingresso de barco na Competição de Combate ao Mal no Bar do Dragão Maligno! Em breve embarcarei no navio.",
  [822505833039104] = "Ei, não sei para onde esse navio está indo. Mas acho que minha oportunidade chegou... Você quer uma pintura, {{Sr.|Sra.}}?",
  [822505833038848] = "Não, não. Depois de me dar bem, descobri que eles eram amigáveis ​​e fortes, e logo todos estavam pescando e indo para o mar juntos. Caso contrário, como você poderia me ver indo passar férias em Tingen?",
  [822505833038592] = "E então? Por que eles desembarcaram? Eles estavam tentando confiscar seus recursos em Bayam?",
  [822505833038336] = "Mais alto que os Feysacianos! A primeira vez que os pescadores viram aquele grupo de pessoas da Nova Cidade Prateada, ficaram tão chocados que quase engoliram um tubarão!",
  [822505833038080] = "Mais alto que os Feysacians?",
  [822505833037824] = "Aquele grupo de pessoas tinha mais de dois metros e meio de altura, ali parado como muros altos.",
  [822505833037568] = "O que você está olhando? Pinte sua pintura!",
  [822505833037056] = "...Esqueça, esqueça, eu vou te dar. Eu realmente aprendi algo hoje...",
  [822505833036800] = "O quê, intimidar um pintor surdo-mudo? Cuidado, ou eu vou te bater!",
  [822505833036544] = "1 libra de ouro. Já está terminado, nem um centavo a menos!",
  [822505833036288] = "Diga isso de novo, quanto você está me cobrando por esse retrato?",
  [822505833036032] = "Então você está vendendo pinturas... Não, obrigado.",
  [822505833035776] = "Nós os vendemos muito barato e a qualidade é excelente.",
  [822505833035520] = "Shh... fale baixo. {{Sr.|Sra.}}, você quer comprar uma pintura? Do tipo que te faz feliz; não é caro.",
  [822505833035264] = "Chegue mais perto...",
  [822505833035008] = "Velho, vocês dois estão bem?",
  [822505833034752] = "Tudo bem, vou esperar o cliente que vier me buscar.",
  [822505833034496] = "Eu não me importaria de ganhar tanto dinheiro... mas estou velho e cheio de doenças. Um velho mendigo também não me procuraria para este último trabalho.",
  [822505833034240] = "Fors ainda é jovem; ela não aceitará o trabalho de um velho mendigo.",
  [822505833033984] = "Vá embora! Você está bloqueando todos os meus negócios.",
  [822505833033728] = "A vida de um mendigo não vale muito, e a vida de um velho mendigo vale ainda menos a pena ser salva. Este é o meu único desejo que resta...",
  [822505833033472] = "Esqueça, não posso ganhar esse dinheiro. É melhor você tomar e consultar um médico.",
  [822505833033216] = "Eu só quero encontrá-lo mais uma vez... só uma última vez...",
  [822505833032960] = "Olá, {{PlayerName}}{{Sr.|Sra.}}, fico feliz em poder ajudar.",
  [822505833032704] = "Eu cuidarei de tudo para alugar uma casa em Tingen para você... eu prometo!",
  [822505833032448] = "<P_Heart> (Um professor problemático...) </>",
  [822505833032192] = "Este colega, quer calcular a fortuna de hoje? Sou membro do Clube Adivinhação, garanto que você ficará satisfeito.",
  [822505833031936] = "(Casa para alugar? Mas... essa pessoa é confiável?)",
  [822505833031680] = "Por que não dar uma olhada nas casas que tenho em mãos? Sem depósito, carteira assinada, garanto que você ficará satisfeito!",
  [822505833031424] = "(Inclinando-se) Olhando para você, você deve ter acabado de chegar em Tingen e está preocupado em saber onde encontrar um lugar para ficar, certo?",
  [822505833030912] = "{{Sr.|Sra.}}, você quer alugar uma casa?",
  [822505833030656] = "...Isso não tem nada a ver com você. É melhor você ter cuidado para não ser expulso por faltar a muitas aulas!",
  [822505833030400] = "Professor, você trabalha há seis anos e ainda é auxiliar de ensino?",
  [822505833030144] = "Não me venha com isso, sou auxiliar de ensino há seis anos, já ouvi essa desculpa muitas vezes.",
  [822505833029888] = "Professor, sou da Universidade de Tingen, vizinha da auditoria, e não sou aluno desta turma.",
  [822505833029632] = "Parar! Finalmente peguei você, foi você quem faltou à aula da última vez, certo? Qual é o seu nome e em que curso você está?",
  [822505833029376] = "De qualquer forma, é melhor tirar uma soneca confortável.",
  [822505833029120] = "Faltar na chamada significa ter um registro de ausência, o que significa perder o bônus, então não preciso trabalhar tanto para ficar entre os primeiros...",
  [822505833028864] = "Perdi a chamada das nove horas da manhã... Enfim, como já perdi, não faz diferença se vou ou não.",
  [822505833028608] = "Você parece tão confortável. Sem aula?",
  [822505833028352] = "Esses fragmentos são simplesmente naturais! Quero usá-los para fazer uma escultura – um coração partido...",
  [822505833028096] = "Você não disse que queria ouvir a verdade? Você fica infeliz quando eu digo isso, eu realmente não entendo...",
  [822505833027840] = "Você nem se dá ao trabalho de inventar uma desculpa superficial, que expectativas ainda posso ter para você...",
  [822505833027584] = "Esse pedaço de lixo parece ter sido enterrado em um cemitério por cinquenta anos antes de ser desenterrado, e você chama isso de presente? Eu sou uma lata de lixo!",
  [822505833027328] = "Se você vai discutir, por que quebrar o presente?",
  [822505833027072] = "Você pode experimentar a História da Música Clássica da Professora Associada Babette. Ela nunca faz atendimento, basta fazer o exame no final do semestre.",
  [822505833026816] = "Ele é de Feynapot e sua filosofia é muito diferente da dos professores de Loen.",
  [822505833026560] = "Fui reprovado novamente na disciplina eletiva do semestre passado por causa do professor Lawrence, devo ir orar na estátua do primeiro diretor?",
  [822505833026304] = "<P_Heart> (Um casal apaixonado...) </>",
  [822505833025280] = "Vovó Janet está velha, estou aqui para ajudá-la a promover: alunos que ajudam a conseguir toda a torta que conseguem comer!",
  [822505833025024] = "Meu? Não, sou apenas um estudante comum.",
  [822505833024768] = "Você está com a vovó Janet?",
  [822505833024512] = "Se você é da Dicy, uma mordida e garanto que sentirá o sabor da casa!",
  [822505833024256] = "Olá, gostaria de experimentar a autêntica torta Dicy da vovó Janet?",
  [822505833024000] = "<P_Heart> (Um professor e um aluno estão discutindo algo...) </>",
  [822505833023744] = "Ah, que irritante, vocês são como folhas murchas de alface!",
  [822505833023488] = "Ou talvez esqueça, nossa fábrica já entrou em greve tantas vezes e nunca vi nenhum efeito real.",
  [822505833023232] = "Minha esposa está grávida, infelizmente é melhor jogar pelo seguro.",
  [822505833022976] = "...Mas a última pessoa que liderou uma greve teve seu bônus de final de ano totalmente deduzido.",
  [822505833022720] = "Bloqueie o portão da fábrica até que o dono da fábrica coloque o dinheiro em nossas mãos! Quem está disposto a se juntar a nós?",
  [822505833022464] = "Irmãos, a fábrica nos deve um mês de salário, conversei com Leo e Santo, não começaremos a trabalhar hoje até que nos dêem uma explicação!",
  [822505833022208] = "Ei, a oportunidade não espera por ninguém, se você chegar atrasado, a vaga será arrebatada - não diga que não avisei.",
  [822505833021952] = "...Deixe-me pensar um pouco mais sobre isso.",
  [822505833021696] = "Apenas me dê 2 soli e eu lhe darei as horas extras deste mês.",
  [822505833021440] = "Não hesite, lutei com unhas e dentes para conseguir esta vaga. Se você não acredita em mim, vá até o portão da fábrica e veja quantas pessoas estão fazendo fila para se inscrever.",
  [822505833021184] = "Esse...",
  [822505833020928] = "Turno noturno, 12 horas, 6 centavos por dia.",
  [822505833020672] = "Como está o pagamento?",
  [822505833020416] = "Tenho hora extra na siderúrgica, vamos nos mudar em breve, vou vender essa vaga para vocês barato, que tal?",
  [822505833020160] = "Estou realmente com pouco dinheiro, Bonnie acabou de ser demitida da fábrica, agora é difícil até mesmo conseguir pagar as mensalidades das crianças.",
  [822505833019648] = "...Talvez não devêssemos nos comparar a circunstâncias tão inferiores – oh, droga! Juro que uma grande aranha passou pela aba do seu chapéu!",
  [822505833019392] = "Pelo menos ainda temos esses 2 centavos.",
  [822505833019136] = "Suspiro, esqueça, algo é melhor que nada. Ouvi dizer que algumas fábricas fazem “horas extras voluntárias” e você não ganha nem um centavo por trabalhar a noite toda.",
  [822505833018880] = "Heh, pagamento duplo? Ele disse isso da última vez também, mas deu apenas 2 centavos extras, nem o suficiente para comprar um copo de cerveja barata.",
  [822505833018624] = "Tudo bem... pelo menos o capataz disse que hoje há pagamento em dobro pelas horas extras.",
  [822505833018368] = "Sonhe, tem mais dois carrinhos!",
  [822505833018112] = "Depois de empurrar esse carrinho, deveremos conseguir sair do trabalho, certo?",
  [822505833017856] = "Fique contente, cara, o carvão ainda é leve, empurrar minério de ferro da última vez foi o que você chamaria de cansativo.",
  [822505833017600] = "Este carrinho de carvão é muito pesado, meus braços parecem que vão quebrar ao empurrá-lo.",
  [822505833017088] = "Sinceramente, não tenho certeza... mas posso tentar! Como vou saber o resultado se não tentar, certo?",
  [822505833016832] = "Obrigado pelo seu incentivo, vou tentar.",
  [822505833016576] = "A poesia não distingue entre alto e baixo, desde que o conteúdo seja bom o suficiente, com certeza será amado pelas pessoas.",
  [822505833016320] = "Realmente? Mas... será que alguém vai ler poemas escritos por um trabalhador como eu?",
  [822505833016064] = "<P_Heart> (Navegando) </> Esses poemas... são todos muito bons, talvez você possa enviá-los para os jornais e revistas de Tingen.",
  [822505833015808] = "Desde a primavera passada, escrevo algumas linhas durante os intervalos do turno da noite. Olha, este é o meu caderno.",
  [822505833015552] = "Esse poema é lindo, quando você começou a escrever poesia?",
  [822505833015296] = "\"O canto das conchas na praia South Will\"",
  [822505833015040] = "\"Preparando vinho arco-íris no Pass Valley\"",
  [822505833014784] = "“As páginas amareladas do diário de viagem de um trabalhador”",
  [822505833014528] = "\"Minha caixa de ferramentas esconde a distância\"",
  [822505833014272] = "Deixe-me pensar no que tenho na minha caixa de ferramentas... Hmm! Eu tenho inspiração—",
  [822505833014016] = "\"Florescendo com flores cor de ferrugem\"",
  [822505833013760] = "“Meus poemas brotarão nas ruínas”",
  [822505833013504] = "\"Quando o último rolamento quebrar\"",
  [822505833013248] = "\"Quando o último rebite enferruja\"",
  [822505833012992] = "Rebites... este é o objeto com o qual estou mais familiarizado. Algumas linhas surgem naturalmente em minha mente—",
  [822505833012736] = "“Esculpir poemas que ninguém entende em chapas de ferro”",
  [822505833012480] = "\"Então, usar uma chave inglesa como caneta e manchas de óleo como tinta\"",
  [822505833012224] = "\"Eu ouço as estrelas enferrujadas suspirando\"",
  [822505833011968] = "\"As engrenagens esmagam o brilho do crepúsculo\"",
  [822505833011712] = "Gears... deixe-me pensar, talvez eu possa escrever assim—",
  [822505833010944] = "É simples meu amigo, basta dizer qualquer palavra, de preferência relacionada à fábrica.",
  [822505833010688] = "Claro, o que devo fazer?",
  [1143563228289280] = "Existem muitos conteúdos incertos sobre a história da Quarta Época. Você deve começar sua pesquisa a partir de relíquias existentes para eliminar fatores incertos.",
  [822505833010176] = "Este é um poema que você escreveu?",
  [822505833009920] = "\"Mesmo assim, eles usam meus rascunhos de poesia para preencher a base de rolamento que vaza...\"",
  [1143563228823808] = "No dia em que preparei a poção, Susie abriu a porta e entrou no laboratório, lambendo uma porção da poção do Espectador. Felizmente, preparei dois conjuntos de materiais na época.",
  [1143563228821760] = "Portanto, sua segunda linha do nome honorífico é 'Abençoado do Rei Amarelo e Preto'.",
  [822505833009152] = "\"As cinzas desfocam o halo da lua\"",
  [822505833008896] = "Isso é muito difícil. A propósito, ouvi dizer que a Catedral do Número Sagrado oferece assistência médica gratuita recentemente, você deveria dar uma olhada.",
  [822505833008640] = "Sua dor de cabeça não é nada, veja só: fui atingido no pé por aquele carrinho de minério transportado do condado de Sivellas, e ele ainda está inchado.",
  [822505833008384] = "Essa sensação é como ter um grupo de mineiros martelando dentro da sua cabeça!",
  [822505833008128] = "Espero que desta vez não haja carga ruim, vazou o último lote de vinho tinto e o cheiro me deu dor de cabeça por uma semana inteira!",
  [822505833007872] = "Talvez o vento e as ondas do mar estivessem muito fortes, atrasando a viagem. Aposto que essas ondas eram mais altas que a torre da Catedral dos Números Sagrados!",
  [822505833007616] = "Esse maldito navio afundou no mar para alimentar os peixes? Estou esperando há tanto tempo que estou quase dormindo.",
  [822505833007360] = "Um dia, farei com que todos saibam meu nome: Annie Bonney! Tal como a Dona Edwina, farei parte das lendas do mar!",
  [822505833007104] = "Eu, eu quero viver uma vida curta e apaixonada, não uma vida longa e chata.",
  [822505833006848] = "Isso ainda é melhor do que ficar preso nas docas por toda a vida! Pelo menos aqueles marinheiros e piratas viram as verdadeiras lendas do mar!",
  [822505833006592] = "Mas o mar é perigoso... Diz-se que as coisas mais terríveis no mar nem são as tempestades, mas sim aquelas coisas invisíveis.",
  [822505833006336] = "Tosse, não é importante... Um dia, navegarei em busca dos tesouros do mar. Mesmo que não encontre o tesouro, ainda posso navegar sob o luar, bebendo Ranzhi, cantando canções de marinheiro...",
  [822505833006080] = "Onde você conseguiu isso? Como o mapa de rotas deles poderia cair em suas mãos? É verdade?",
  [822505833005824] = "Olhar! Recebi o mapa de rotas deles há três anos! Diz-se que o “Sonho Dourado” enterrou um tesouro imensurável em uma ilha misteriosa!",
  [822505833005568] = "Mas o Velho Tom disse que viu com os próprios olhos! Quando o Sonho Dourado passar, até as ondas do mar ficarão paradas!",
  [822505833005312] = "Por que parece uma história inventada por marinheiros bêbados...",
  [822505833005056] = "Exatamente! Este {{Sr.|Sra.}}, você também deve querer embarcar no magnífico e misterioso “Sonho Dourado”!",
  [822505833004800] = "Isso é muito mágico.",
  [822505833004544] = "Ouvi dizer que há uma biblioteca no navio dela e os livros dentro dela viram as páginas sozinhos!",
  [822505833004288] = "Sim, a linda e ótima Sra. Edwina Edwards! Um mentor sábio que orienta com habilidade, um professor culto e capaz!",
  [822505833004032] = "O navio do almirante Iceberg? Eu ouvi alguns rumores.",
  [822505833003776] = "Ei, você já ouviu falar do \"Sonho Dourado\"? Dizem que as velas daquele navio se transformam em cristal sob o luar!",
  [822505833003520] = "Espero que você encontre um tolo disposto a morrer por 5 centavos.",
  [822505833003264] = "Pirralhos ingratos! Quando você estiver morrendo de fome e não aguentar mais, não volte me implorando...",
  [822505833003008] = "Se você realmente deseja contratar alguém, mostre alguma sinceridade.",
  [822505833002752] = "Esqueça, senhor! Você só quer que nos prejudiquemos, não é?",
  [822505833002496] = "É difícil encontrar empregos agora. Se você estiver disposto a aceitar o preço de 5 centavos, posso considerar contratar mais uma pessoa.",
  [822505833002240] = "Sim, caro senhor, seu preço é realmente \"generoso\" o suficiente para ser movido!",
  [822505833001984] = "5 centavos? Caro senhor, você está brincando? A fábrica deu 10 centavos da última vez.",
  [822505833001728] = "Oh, meus queridos filhos! Tenho uma excelente oportunidade de trabalho aqui, você só precisa trabalhar 12 horas por dia e pode ganhar... hum, 5 centavos!",
  [822505833001472] = "Carne de porco premium, processada com técnica secreta de defumação, cada fatia exala um rico aroma frutado, em borracha e satisfatório, adequado para qualquer momento!",
  [822505833001216] = "Carnes e peixes frescos, com a pele frita dourada e crocante, e o interior macio e suculento, uma mordida e quase dá para sentir o aroma salgado da brisa marítima da Rua Cruz de Ferro, é definitivamente a sua melhor escolha para repor as energias!",
  [822505833000960] = "Tudo bem, tenha um bom dia!",
  [822505833000448] = "O gato está muito bem, muito competente!",
  [822505833000192] = "Deixa eu te explicar, Gato é o nome dele, espero que possa me ajudar a pegar aqueles ratos que roubam a carne frita!",
  [822505832999936] = "O gato é meu melhor parceiro!",
  [822505832999680] = "Olha esses ovos fritos dourados e translúcidos, levemente carbonizados nas bordas, escorrendo por dentro, simples mas cheios de sabor caseiro, uma mordida vai te deixar aquecido e satisfeito, compre cinco e ganhe um grátis!",
  [822505832999424] = "Há também carne de porco premium recém-assada, processada com técnica secreta de defumação, cada fatia exala um rico aroma frutado, em borracha e satisfatório, adequado para qualquer momento!",
  [822505832999168] = "Se pretende repor as energias, carne e peixe frescos, com a pele frita dourada e estaladiça, e o interior tenro e suculento, uma dentada e quase consegue sentir o aroma salgado da brisa marítima da Rua Cruz de Ferro, é definitivamente a sua melhor escolha!",
  [822505832998912] = "Olá, um dia maravilhoso começa com carne frita perfumada! O que você gostaria?",
  [822505832998656] = "Droga, você está fazendo isso de novo!",
  [822505832998400] = "Meu querido... Velho Bill... você...",
  [822505832998144] = "Então saia e me dê o dinheiro!",
  [822505832997888] = "Sim, sim, eu sei...",
  [822505832997632] = "Você sabe que o café é importante? Então se apresse e me pague de volta! Se todos fossem como você, minha barraca já teria fechado há muito tempo!",
  [822505832997376] = "Trabalhar na fábrica, ficar parado mais de dez horas seguidas, quem aguenta sem algo para se refrescar?",
  [822505832997120] = "Você toma uma xícara de café todas as manhãs, sem falta, como pode dizer que está com pouco dinheiro? Sem café não dá nem para ligar as máquinas, não pense que não sei!",
  [822505832996864] = "Ah, não faça isso. Estou realmente com pouco dinheiro ultimamente... Assim que o salário desta semana for pago, eu te pagarei imediatamente, eu juro!",
  [822505832996608] = "Você não sabe como os grãos de café são caros agora? Se você não me pagar, terei que falar com seu gerente!",
  [822505832996352] = "Stingy Old Tom nunca deixou aquela lâmpada apagar, e nunca mais ouvimos aquele som estranho equipamento. De qualquer forma, elogie o Steam!",
  [822505832996096] = "E este lugar é assombrado! Vapor acima, o pessoal da Igreja veio olhar e deixou um lampião de querosene, mas não sei se serve.",
  [822505832995840] = "Se não fosse pelo fato de querer economizar dinheiro para o casamento da Jennifer, não estaria alugando aqui.",
  [822505832995584] = "Parece que você está bem vestido, deveria alugar um lugar melhor.",
  [822505832995328] = "Você quer alugar um lugar onde 40 pessoas compartilhem um banheiro, onde não há nem cortina entre os beliches de três níveis e o ar está cheio de cheiro de suor e pés fedorentos?",
  [822505832995072] = "Posso perguntar sobre as condições aqui?",
  [822505832994816] = "Ei, você está espionando aqui, o que você quer?",
  [822505832994560] = "Trabalhar durante o dia e trabalhar à noite? Amigo, se eu soubesse que você era um workaholic, não teria dividido o beliche com o Mackey, deveria apenas ter dormido no seu!",
  [822505832994304] = "Essa noite? Tenho que trabalhar para ganhar mais dinheiro para Jennifer.",
  [822505832994048] = "Que tal um drink no \"Wild Heart\"? Quase caí na fornalha de aço hoje, se não relaxar vou enlouquecer!",
  [822505832993792] = "Assim que passar, acenderei velas sempre que quiser, comprarei um lampião a gás novo e o manterei aceso pelo tempo que quiser...",
  [822505832993536] = "Melhor se concentrar na revisão primeiro. Afinal, não posso nem comprar velas, tenho que me virar aqui.",
  [822505832993280] = "Pense na vida daquelas pessoas decentes, sentadas em um escritório, recebendo um salário fixo todo mês, sem precisar se preocupar com a próxima refeição.",
  [822505832993024] = "Suspiro, este “Código do Reino” é realmente grosso e difícil de mastigar... mas se eu não conseguir passar no concurso público, ficarei preso na Lower Street pelo resto da minha vida.",
  [822505832992768] = "De qualquer forma, quando eu tiver dinheiro, devo sair da Rua Cruz de Ferro e ir para um lugar melhor... Quando chegar a hora, você vem comigo!",
  [822505832992512] = "Pare de sonhar! Ruas pavimentadas com ouro? Isso machucaria seus pés! Mas... se eu pudesse mesmo ir a Backlund, também gostaria de ver.",
  [822505832992256] = "O que é um vestido novo! Quando tiver dinheiro, comprarei um burrinho e vou montá-lo até Backlund! Ouvi dizer que as ruas lá são pavimentadas com ouro!",
  [822505832992000] = "Claro! Ouvi dizer que os trabalhadores do cais podem ganhar vários centavos por dia! Se eu economizar um pouco, talvez consiga comprar um vestido novo!",
  [822505832991744] = "Diga-me, quando crescermos, seremos capazes de ser como aqueles adultos, vestindo roupas decentes todos os dias e tilintando moedas nos bolsos?",
  [822505832991488] = "Que tal adicionar um intensificador de sabor? Não, não, isso deixaria meus clientes viciados...",
  [822505832991232] = "Não, o sabor do novo produto ainda não é especial o suficiente...",
  [822505832990976] = "Já sou um velho sem paixão; os clientes devem preferir um dono de barraca tão entusiasmado quanto ele.",
  [822505832990720] = "Suspiro, aquele cara, Ryan, tem uma voz de falcão mais alta do que a minha e frita carne mais rápido também. Todos os clientes são atraídos por ele...",
  [822505832990464] = "Então vamos continuar, a palavra “persistência”...",
  [822505832990208] = "Eu posso fazer isso! No futuro, quero ser como você, vovô, e ir para a escola dominical gratuita para ensinar a todos.",
  [822505832989952] = "Você pode, mas se quiser ajudá-los a escrever cartas mais longas, você precisa dominar mais cem palavras.",
  [822505832989696] = "Vovô Jude, esta é a trecentésima quadragésima primeira palavra que aprendi. Posso ajudá-lo a escrever cartas para todos agora?",
  [822505832989440] = "A Deusa não se importa em consertar varandas...",
  [822505832989184] = "Você é realmente uma boa pessoa, que a Proteção da Deusa esteja com você!",
  [822505832988928] = "Tudo bem, considerando que você mora na Iron Cross Street. Mas se a madeira ao redor estiver completamente podre, você terá que pagar a mais.",
  [822505832988672] = "Então vou adicionar meia garrafa de Black Land! Isso é tudo que me resta!",
  [822505832988416] = "Esse preço só vai comprar materiais de menor qualidade, a varanda vai vazar quando chover.",
  [822505832988160] = "Minha varanda só tem um pequeno buraco, é só consertar. 2 soli incluindo mão de obra, que tal?",
  [822505832987904] = "Os materiais para consertar a varanda custam no mínimo 2 soli, a mão de obra é extra.",
  [822505832987648] = "Que criança especial... Que tudo corra bem para ela.",
  [822505832987392] = "Claro que fui eu que fiz, sou natural... Isso não é da sua conta. Steam acima, se você não tiver mais nada, por favor, saia.",
  [822505832987136] = "O que é isso? Parece muito especial, não é algo que você possa comprar lá fora.",
  [822505832986880] = "<P_Heart> (Tira um dispositivo mecânico) </> Se você quiser fazer alguma coisa, seu grito fará com que toda a Rua Cruz de Ferro ouça.",
  [822505832986624] = "Conhecimento... Hmph, o vovô diz que o conhecimento é importante, mas ele também diz que algumas pessoas o usam para fazer coisas ruins. É melhor você não estar tramando nada.",
  [822505832986368] = "Sou apenas um transeunte com algum interesse em letras e conhecimento.",
  [822505832986112] = "Algumas pessoas sempre gostam de bisbilhotar coisas que não deveriam saber... Você não é uma dessas pessoas, é?",
  [822505832985856] = "Apenas cartas, nada de especial. Se você não tem nada para fazer, por favor, não fique aqui.",
  [822505832985600] = "Não fique nervoso, querido filho, só estou curioso para saber o que você está escrevendo.",
  [822505832985344] = "Não é nada! Apenas rabiscando... Precisa de algo?",
  [822505832985088] = "Você está aprendendo a escrever?",
  [822505832984832] = "Esse maldito mundo, nos forçando a fazer esse tipo de trabalho...",
  [822505832984576] = "Não se preocupe, querido Iron Needle, somos o melhor time da Iron Cross Street!",
  [822505832984320] = "Irei pela direita em um momento; você e Wool o distraem.",
  [822505832984064] = "Ah, ele é mais prolixo que a senhora do bordel!",
  [822505832983808] = "Agulha de Ferro, fale baixo, Wool já nos avisou diversas vezes.",
  [822505832983552] = "Eu... acho que ele nos notou. Os olhos dele são tão assustadores, assim como aqueles convidados de que mamãe falou...",
  [822505832983296] = "Por que você está demorando? O relógio de bolso daquele idiota está quase tremendo na minha cara! Você vai fazer isso ou não?",
  [822505832983040] = "Espere mais um pouco, espere mais um pouco...",
  [822505832982784] = "Mas você vê, não precisamos de piedade. Agulha de ferro e fio de seda são bons para fazer recados, feltro e tecido são ótimos para tecer, lã é boa para coletar informações... somos bons em tudo.",
  [822505832982528] = "Hmph, quanto aos pais... alguns morreram em acidentes de fábrica, alguns foram levados por doenças e outros... simplesmente nos abandonaram na rua.",
  [822505832982272] = "Sim, respeitado senhor/senhora.",
  [822505832982016] = "Você... são todos órfãos?",
  [822505832981760] = "Claro, tudo depende das suas necessidades. O lema da nossa \"Gangue do Chapéu\" é: desde que o preço seja justo, não há nada que não possamos fazer.",
  [822505832981504] = "E, caro senhor, se precisar de alguma... bem, informação menos formal, temos maneiras de obtê-la. Afinal, neste bairro os ouvidos das crianças são sempre os mais aguçados.",
  [822505832981248] = "Essas crianças são rápidas e perspicazes. Você pode nos encontrar pelo recurso Red Hat; somos muito bons em fazer recados e tecer pequenos artesanatos.",
  [822505832980992] = "Com prazer. Embora sejamos apenas um grupo de crianças sem-abrigo, as nossas capacidades nunca devem ser subestimadas.",
  [822505832980736] = "Você se importa de me apresentar a Hat Gang?",
  [822505832980480] = "Não subestime a capacidade dos órfãos de coletar informações. Há algo que você precisa?",
  [822505832980224] = "Eu conheço você, o jovem que tem ligações com a polícia.",
  [822505832979968] = "Você está comprando? Se não, vou perguntar a outra pessoa.",
  [822505832979712] = "<P_Heart> (Sussurrando) </> Ela não deveria ter descoberto meu relacionamento com os dois, certo...",
  [822505832979456] = "{{Sr.|Sra.}}, quer um jornal?",
  [822505832979200] = "<P_Heart> (Sussurrando) </> Quem sabe de que é feita a comida do asilo? E se forem ratos...",
  [822505832978944] = "Aguente isso.",
  [822505832978688] = "Mas estou com muita fome.",
  [822505832978432] = "Os alimentos de socorro devem ser deixados para aqueles que mais precisam. Podemos trocar trabalho por comida.",
  [822505832978176] = "Mãe, deixe-me pegar uma... não, meia porção de comida!",
  [822505832977920] = "Sou apenas um entregador, que más intenções posso ter?",
  [1112707914834176] = "Missão concluído",
  [822505832977408] = "Não pergunte, são apenas negócios. Se você não tiver ratos vivos, não atrapalhe.",
  [822505832977152] = "Você está colecionando ratos? Para quê?",
  [822505832976896] = "Animais que guincham, do tipo que ainda pode guinchar! Estou pagando por eles!",
  [822505832976640] = "Que guinchos?",
  [822505832976128] = "O próprio Ove se culpou muito, pois estava trabalhando e não percebeu o estado da criança... Suicidou-se em casa.",
  [822505832975872] = "A família Ove morava lá dentro; A Sra. Ove morreu na fábrica e o pequeno Ove morreu congelado no inverno.",
  [822505832975616] = "Você quer dizer aquela casa mal-assombrada? Até ajudei a fechar as janelas.",
  [822505832975360] = "Mas tenho que agradecer a ele, caso contrário não teria conseguido esse emprego e as crianças de casa morreriam de fome.",
  [822505832975104] = "O trabalhador anterior caiu para a morte.",
  [822505832974848] = "Para quê?",
  [822505832974592] = "Claro que eu mesmo peguei. Para comer carne, eliminei os ratos em vários quarteirões!",
  [822505832974336] = "Carne de rato? Onde você conseguiu isso?",
  [818107786597632] = "Ele está sempre obcecado em cultivar as abóboras mais doces, haha, mas as abóboras dele são realmente muito deliciosas!",
  [818107786597376] = "Ah... você quer dizer o Sr. Rumber do campo de abóboras ao lado.",
  [818107786597120] = "Oh! Se gostar, fique à vontade para levar um pouco para beber quando estiver pronto.",
  [818107786596864] = "Pretendo transformar essas uvas em vinho, basta colocá-las em um barril de madeira e aguardar a fermentação... Esse deve ser o vinho mais saboroso da pequena cidade!",
  [818107786596352] = "Estas uvas parecem ótimas!",
  [818107786595584] = "O que, o que? Ele vai usar essas uvas para fazer vinho. Uh, bem, isso parece muito bom... Eu gosto de beber!",
  [818107786595072] = "Hmph, você é sensato. Minhas abóboras serão definitivamente as maiores e mais doces!",
  [818107786594816] = "Ah... essas abóboras parecem deliciosas.",
  [818107786594560] = "Claro, é a festa da pequena cidade para celebrar a colheita e agradecer à terra. Vejam as abóboras douradas espalhadas pela minha porta, que frutas doces, que grande poder de colheita!",
  [813709740112128] = "Para onde você quer ir? Com certeza chegarei lá na hora certa!",
  [813709740109312] = "Estou perguntando se parece bom!",
  [813709740109056] = "Está bem vermelho.",
  [809242974016768] = "<P_Heart> (Deixe-o terminar um dos relacionamentos para beneficiar todas as três pessoas.) </>",
  [809242974011904] = "O poste de luz próximo quebrou repentinamente recentemente e não consigo ver nada quando saio do trabalho!",
  [809242974011136] = "O poste está consertado! Agora posso andar à noite sem me preocupar.",
  [809242974010880] = "<P_Heart> (Parece perigoso, irei dar uma olhada à noite...) </>",
  [809242974010624] = "Eles simplesmente não nos tratam como seres humanos! Perguntar? Perguntar é um desperdício de esforço!",
  [809242974010368] = "<P_Heart> (Segurando a testa) </> Essa lâmpada, vou perguntar sobre ela de novo...",
  [809242974009856] = "<P_Heart> (Raiva) </> Tenho uma aprendiz que percorreu esse caminho depois do trabalho há alguns dias e depois desapareceu, desapareceu!",
  [809242974009600] = "<P_Heart> (Desamparado) </> Eu relatei isso aos superiores, mas ninguém lidou com isso. Suspiro, eles não se importam se vivemos ou morremos.",
  [809242973991680] = "Se você ainda tem tempo para estudar aquela maldita nuvem, então arraste nossos marinheiros de volta do bar!",
  [809242973991424] = "Realmente? Mas não acho que julguei mal. Olha aquela nuvem...",
  [809242973989376] = "Irei primeiro ao Castelo Lamud para pacificar Gina, depois pedirei dinheiro emprestado a Gina para ver Lily; ela sempre atendeu a todos os meus pedidos.",
  [809242973989120] = "Mas eu entendo o que você quer dizer. Se ir para um deles não tiver um bom resultado, então irei para os dois!",
  [809242973988864] = "Não! Se eu deixar Lily, perderei minha paixão pela vida... Se Gina me deixar, ficarei louco. Não posso desistir de nenhum deles.",
  [809242973988608] = "Os resultados de você ir ao Golden Autumn Lake e ao Lamud Castle não são bons no meu adivinhação. Deve-se ser devotado em amor; é melhor para você e para aquelas duas jovens.",
  [809242973988352] = "<P_Heart> (Melhor aconselhá-lo.) </>",
  [809242973988096] = "Obrigado pela sua revelação! Gina, vou procurar você agora. Os recantos tranquilos do castelo foram feitos para partilharmos os nossos corações!",
  [809242973987840] = "O Castelo Lamud é uma boa escolha.",
  [809242973987584] = "<P_Heart> (Deixe-o aprender uma lição e parar de ser mulherengo.) </>",
  [809242973987328] = "Você é realmente incrível! Eu senti a pequena Lily me chamando em meu coração... Vou procurá-la imediatamente!",
  [809242973987072] = "Golden Autumn Lake pode ser mais adequado para você.",
  [809242973986560] = "Grande Vidente, posso perguntar para onde devo ir?",
  [809242973986304] = "Ok, eu entendo.",
  [809242973986048] = "Por favor, me dê uma revelação! Para qual lugar devo comprar uma passagem do Trem a Vapor?",
  [809242973985792] = "Grande Vidente, <P_Yellow> Golden Autumn Lake </> e <P_Yellow> Lamud Castle </> ambos têm pessoas esperando por mim, mas meu dinheiro só me permite ir a um lugar para a consulta.",
  [809242973985536] = "Isso é ótimo!",
  [809242973985280] = "Sim, adivinhei de antemão que alguém aqui precisava de ajuda.",
  [809242973985024] = "Você é... não, você é um Vidente!",
  [809242973984768] = "Senhor, que tipo de revelação você precisa?",
  [809242973984000] = "Obrigado, obrigado... As crianças terão pão para comer hoje...",
  [809242973983488] = "Suspiro, parece que as crianças vão sentir fome de novo...",
  [809242973983232] = "Ei, ei! Haha! Não, não vá embora, a melhor parte ainda está por vir!",
  [809242973982976] = "Esse é o pior palhaço que já vi... Aposto que ele não vai ganhar um centavo hoje.",
  [809242973972736] = "Oh, desculpe, estou um pouco animado agora. Você precisa que eu mande você de volta para o Evil Dragon Bar? É bem longe daqui.",
  [809242973972480] = "Quando chegar a hora, deixe Gehrman entrar por aquele lado, e então diretamente...",
  [809242973972224] = "Huh? Você me seguiu também? Devo dizer que esta é uma ótima sugestão.",
  [809242973971968] = "Então, por favor, fique à vontade; Preciso fazer um brainstorming aqui por um tempo.",
  [809242973971200] = "Então fique parado. Em primeiro lugar, declaro: se você cair na chaminé de alguém novamente, lembre-se de manter isso em segredo para mim!",
  [809242973970944] = "É incrível! Eu sabia! Obter a aprovação deles me deixa mais feliz do que vencer qualquer competição de culinária. Esta é a verdadeira “Certificação Medalha de Ouro”!",
  [804913647020032] = "E então?",
  [519041161239040] = "Cuidado onde pisa, não deixe que as pedras te façam tropeçar!",
  [519041161099776] = "Miau...",
  [519041161094656] = "Eu sou o Rei de Tingen!",
  [519041161094400] = "Eu sou o Rei da Rua Cruz de Ferro!",
  [519041161026816] = "Ouvi dizer que você está com pouco dinheiro ultimamente?",
  [519041160983552] = "Miau!",
  [519041160974336] = "Amigo, tem algum \"guincho\"?",
  [519041160772096] = "Miau.",
}
